// safefind1 (10.11 17:08:59, host crash entering the chapter 3 drawn world):
// the SDK's UFunction::FindFunction, on a name it has not cached, walks every
// object and asks each one for its full name - one object there was being
// destroyed (the playable Alice had just been replaced by the drawn one) and
// its name chain was freed (read at 0xCC in FName::ToString). This lookup
// only names objects whose class is Function (read under SEH first), caches
// every function once, and remembers names it did not find.
namespace
{
	UClass* SafeObjectClass(UObject* object)
	{
		__try
		{
			return object ? object->Class : nullptr;
		}
		__except (EXCEPTION_EXECUTE_HANDLER)
		{
			return nullptr;
		}
	}

	std::map<std::string, UFunction*>& SafeFunctionCache()
	{
		static std::map<std::string, UFunction*> cache;
		return cache;
	}

	void RebuildSafeFunctionCache()
	{
		UClass* const functionClass = UFunction::StaticClass();
		TArray<UObject*>* const objects = UObject::GObjObjects();
		if (!functionClass || !objects)
			return;
		auto& cache = SafeFunctionCache();
		for (int32_t index = 0; index < objects->size(); ++index)
		{
			UObject* const object = objects->at(index);
			if (!object || SafeObjectClass(object) != functionClass)
				continue;
			cache[object->GetFullName()] = reinterpret_cast<UFunction*>(object);
		}
	}

	UFunction* FindFunctionSafe(const std::string& fullName)
	{
		auto& cache = SafeFunctionCache();
		static std::chrono::steady_clock::time_point lastRebuild{};
		auto found = cache.find(fullName);
		if (found != cache.end())
			return found->second;
		// a miss: the function's package may have loaded since - look again,
		// at most every 5 s
		const auto now = std::chrono::steady_clock::now();
		if (lastRebuild == std::chrono::steady_clock::time_point{}
			|| now - lastRebuild > std::chrono::seconds(5))
		{
			lastRebuild = now;
			RebuildSafeFunctionCache();
			found = cache.find(fullName);
			if (found != cache.end())
				return found->second;
		}
		return nullptr;
	}
}

