	// Spare PlayerState flag bits used by this file. Kept here (same values
	// as Protocol.hpp) so a build with an older Protocol.hpp still compiles.
	constexpr std::uint32_t kStateHysteria = 1u << 18;
	constexpr std::uint32_t kStateWeaponFaded = 1u << 19;
	// AlicePawn.SlideState (ESlideState 0..4) in flag bits 20..22: drives
	// AliceGameAnimNode_BlendBySlide (normal/forward/backward/left/right).
	// PlayerAction 13 = Respawn (Protocol.hpp); a constant so an older
	// Protocol.hpp without the enum member still compiles.
	constexpr AliceCoopProtocol::PlayerAction kActionRespawn =
		static_cast<AliceCoopProtocol::PlayerAction>(13);
	// The weapon Alice really draws is hidden (put away: slide, respawn,
	// interactions). StateWeaponHidden cannot say that: it tests
	// Weapon.Mesh, which WeaponForAlice always keeps hidden (it draws
	// through CurMeshComponent) - every log shows sourceHidden=yes.
	constexpr std::uint32_t kStateWeaponPutAway = 1u << 23;
	// AlicePawn.NbOfAttachedNPC (bolterflies leeching her), 0..7, in flag
	// bits 24..26. The grabbed locomotion (BlendByStance child EBPS_Attached:
	// AliceW_Attached_Idle/Walk) needs it besides PawnStance: with only the
	// stance the proxy played Attached_React once and fell back to idle.
	constexpr int kStateAttachedNpcShift = 24;
	constexpr std::uint32_t kStateAttachedNpcMask = 7u << kStateAttachedNpcShift;
	// The cutscene this game holds at the barrier follows a pig snout being
	// peppered: the peer joins the cutscene where it stands, without the
	// teleport to this Alice and back (the players keep exploring).
	constexpr std::uint32_t kStateNoTeleportCutscene = 1u << 27;
	// Alice's umbrella (deflect) is out: AlicePawn.Umbrella (a static mesh
	// component) or her UmbrellaInstance is shown. The proxy shows its own
	// umbrella and puts its weapon away meanwhile.
	constexpr std::uint32_t kStateUmbrella = 1u << 28;
	constexpr int kStateSlideShift = 20;
	constexpr std::uint32_t kStateSlideMask = 7u << kStateSlideShift;
	// PlayerStatePayload.abilityMask carries ability bits 0..17 only (the
	// receiver masks with AliceAbilityBits); bits 24..27 carry the pawn's
	// EBasePawnStance and bit 31 says they are valid.
	constexpr std::uint32_t kStanceValid = 1u << 31;
	constexpr int kStanceShift = 24;
	// AlicePawn.AimOffsetPct.Y (-1..1) quantized to 0..254 (127 = level):
	// low 6 bits in 18..23, high 2 bits in 28..29.
	std::uint32_t PackAimPitch(std::uint8_t pitch)
	{
		return (static_cast<std::uint32_t>(pitch & 0x3Fu) << 18)
			| (static_cast<std::uint32_t>((pitch >> 6) & 0x3u) << 28);
	}
	std::uint8_t UnpackAimPitch(std::uint32_t mask)
	{
		return static_cast<std::uint8_t>(((mask >> 18) & 0x3Fu)
			| (((mask >> 28) & 0x3u) << 6));
	}

