		void RememberLocalShot(const void* projectile, std::uint32_t id,
			std::uint8_t kind)
		{
			g_lastShotActivity = Clock::now();
			if (g_localShotIds.size() > 256)
				g_localShotIds.clear();
			g_localShotIds[projectile] = { id, kind };
		}

		// A cosmetic copy must not hit anything the shooter's shot did not:
		// the enemies stand a little differently in each game, so it struck
		// whichever one was in its way here (a bolterfly in front of the
		// hive the shooter was hitting). It still meets walls and floors
		// (bCollideWorld); its real end comes from the shooter.
		void RegisterRemoteShot(AActor* actor, std::uint32_t id,
			std::uint8_t kind)
		{
			if (!actor)
				return;
			static UFunction* setCollision = FindFunctionSafe(
				"Function Engine.Actor.SetCollision");
			if (setCollision)
			{
				AActor_execSetCollision_Params parameters{};
				parameters.bNewColActors = 0;
				parameters.bNewBlockActors = 0;
				parameters.bNewIgnoreEncroachers = 1;
				actor->ProcessEvent(setCollision, &parameters, nullptr);
			}
			if (g_remoteShots.size() > 128)
				g_remoteShots.clear();
			g_remoteShots[(static_cast<std::uint64_t>(kind) << 32) | id] = actor;
			g_remoteShotBorn[actor] = Clock::now();
			if (g_remoteShotEver.size() > 512)
				g_remoteShotEver.clear();
			g_remoteShotEver.insert(actor);
			g_lastShotActivity = Clock::now();
		}
