		bool IsLiveUObject(const UObject* object); // leavesafe1
		inline bool IsReadableRange(const void* address, size_t bytes); // leavesafe1
		const void* g_leavingWorldPawn = nullptr;
		std::chrono::steady_clock::time_point g_leavingWorldAt{};
		bool LeavingWorld()
		{
			if (g_leavingWorld)
			{
				bool over = CurrentWorldTag() != g_leavingWorldTag
					|| std::chrono::steady_clock::now() - g_leavingWorldAt
						> std::chrono::seconds(20);
				if (!over && std::chrono::steady_clock::now() - g_leavingWorldAt
					> std::chrono::milliseconds(1500))
				{
					// leavesafe1 (10.11 23:20:15 host crash, LeavingWorld from
					// the enemy recorder's ProcessEvent hook, read at
					// controller+0x614): while a world is torn down the saved
					// player controller can already be freed - its Alice is
					// only read when its memory is still there and it is
					// still a live object (checked at most 10 times a second).
					static std::chrono::steady_clock::time_point nextCheck{};
					static bool newPawn = false;
					const auto checkNow = std::chrono::steady_clock::now();
					if (checkNow >= nextCheck)
					{
						nextCheck = checkNow + std::chrono::milliseconds(100);
						AAlicePawn* pawn = nullptr;
						AAlicePlayerController* const controller = g_State.AlicePlayerController;
						if (controller && IsReadableRange(controller, 0x700) && IsLiveUObject(controller))
							pawn = controller->MyAlicePawn;
						if (!pawn)
							pawn = g_State.AlicePawn; // only compared, never read
						newPawn = pawn && pawn != g_leavingWorldPawn;
					}
					over = newPawn;
				}
				if (over)
					g_leavingWorld = false;
			}
			return g_leavingWorld;
		}
