		int g_proxyBuiltShadow = -1; // archproxy1: now the proxy KIND built (ProxyKindOf)
		// archproxy1: 0 = London / asylum, 1 = drawn (shadow), 2 = Wonderland
		// (doll, giant, rolling, transition... are all built as Wonderland)
		int ProxyKindOf(int archetype)
		{
			// asylumproxy1 (12.11 04:18: the host turned from the Asylum Alice
			// into the London Alice in the same map, the client still saw the
			// Asylum one): the Asylum Alice is a kind of her own, so a change
			// between her and the London Alice builds the proxy again
			if (archetype == 8)
				return 3;
			if (archetype == 0)
				return 0;
			if (archetype == 3)
				return 1;
			return 2;
		}
