		// Checking a TArray's count and capacity cannot catch a stale backing
		// pointer, because both live in the array header and stay plausible after
		// the storage behind them is gone. Ask the OS whether the range is really
		// committed and readable.
		inline bool IsReadableRange(const void* address, size_t bytes)
		{
			if (!address || bytes == 0)
				return false;
			MEMORY_BASIC_INFORMATION info{};
			if (VirtualQuery(address, &info, sizeof(info)) == 0)
				return false;
			if (info.State != MEM_COMMIT)
				return false;
			constexpr DWORD readable = PAGE_READONLY | PAGE_READWRITE
				| PAGE_WRITECOPY | PAGE_EXECUTE_READ | PAGE_EXECUTE_READWRITE
				| PAGE_EXECUTE_WRITECOPY;
			if ((info.Protect & readable) == 0)
				return false;
			if (info.Protect & (PAGE_GUARD | PAGE_NOACCESS))
				return false;
			const uintptr_t start = reinterpret_cast<uintptr_t>(address);
			const uintptr_t regionEnd =
				reinterpret_cast<uintptr_t>(info.BaseAddress) + info.RegionSize;
			return start + bytes <= regionEnd;
		}
		// IsLiveUObject walks the entire GObjObjects array, which is fine once per
		// spawn and ruinous once per component per frame. For the per-frame cloth
		// path just read the flags: the pointer is already known to belong to the
		// proxy we are holding, so membership does not need re-proving.
		// Rejects pointers that cannot be a UObject at all (null page, odd
		// alignment, kernel range). During world teardown the emitter pool's
		// ActiveComponents can hold such garbage (crash 19:47:35: 0x1E3).
		// highaddr1 (10.11 22:44:49, host): the Colossal Ruin was "<dead>" for
		// the mod from its spawn ("registry entry not live; scan found
		// nothing", every plate hit "enemy not here"), so each game had its
		// own Ruin. The game is large-address aware: objects can live above
		// 2 GB, and the fixed 0x7FFF0000 limit threw those away. The limit is
		// the process's real highest user address.
		inline std::uintptr_t HighestUserAddress()
		{
			static const std::uintptr_t highest = []
			{
				SYSTEM_INFO info{};
				GetSystemInfo(&info);
				const auto top = reinterpret_cast<std::uintptr_t>(info.lpMaximumApplicationAddress);
				return top > 0x10000u ? top : static_cast<std::uintptr_t>(0x7FFEFFFFu);
			}();
			return highest;
		}

		// highaddr3 (10.11 23:03, input lag, then the client's game thread
		// froze): highaddr2 asked Windows (VirtualQuery) about EVERY pointer
		// above 2 GB - the object scans run that for each of tens of
		// thousands of objects, many frames a second. The memory regions
		// found readable are now remembered (up to 64, forgotten after a
		// second), so a scan costs a few lookups instead of a system call
		// per object.
		// Set around level travel / return to title / death restart, cleared
		// shortly after the new world appears. Pool and component scans are
		// skipped meanwhile.
		Clock::time_point g_worldTransitionUntil{};
		inline bool IsHighAddressReadable(std::uintptr_t address)
		{
			struct Region { std::uintptr_t base; std::uintptr_t end; };
			thread_local Region regions[64]{};
			thread_local int count = 0;
			thread_local int next = 0;
			thread_local ULONGLONG stamp = 0;
			const ULONGLONG tick = GetTickCount64();
			// enemyfree1 (12.11 15:53:08 crash after the Executioner's death
			// restart): while a world is torn down its memory is released
			// region by region, and a region remembered as readable a moment
			// ago may already be gone. The remembered regions are not
			// trusted then - Windows is asked about every pointer.
			if (tick - stamp > 1000 || Clock::now() < g_worldTransitionUntil)
			{
				count = 0;
				next = 0;
				stamp = tick;
			}
			const std::uintptr_t last = address + 0x3F;
			for (int i = 0; i < count; ++i)
			{
				if (address >= regions[i].base && last < regions[i].end)
					return true;
			}
			MEMORY_BASIC_INFORMATION info{};
			if (VirtualQuery(reinterpret_cast<const void*>(address), &info, sizeof(info)) == 0
				|| info.State != MEM_COMMIT)
			{
				return false;
			}
			constexpr DWORD readable = PAGE_READONLY | PAGE_READWRITE
				| PAGE_WRITECOPY | PAGE_EXECUTE_READ | PAGE_EXECUTE_READWRITE
				| PAGE_EXECUTE_WRITECOPY;
			if ((info.Protect & readable) == 0 || (info.Protect & (PAGE_GUARD | PAGE_NOACCESS)))
				return false;
			const std::uintptr_t base = reinterpret_cast<std::uintptr_t>(info.BaseAddress);
			const std::uintptr_t end = base + info.RegionSize;
			regions[next] = Region{ base, end };
			next = (next + 1) % 64;
			if (count < 64)
				++count;
			if (last < end)
				return true;
			// the 64 bytes run into the next region: ask once more for it
			return IsReadableRange(reinterpret_cast<const void*>(address), 0x40);
		}

		inline bool IsPlausibleObjectPointer(const void* object)
		{
			const auto address = reinterpret_cast<std::uintptr_t>(object);
			if (address < 0x10000u || (address & 3u) != 0 || address >= HighestUserAddress())
				return false;
			// highaddr2 (10.11 22:54:23 client crash in TickCineDiag, read at
			// 0x9493E108): above 2 GB the old limit had also been throwing away
			// junk pointers (a stale interp group entry). Up there a pointer
			// only counts when its memory is really there.
			if (address >= 0x7FFF0000u)
				return IsHighAddressReadable(address);
			return true;
		}

		inline bool WorldTransitionActive()
		{
			return Clock::now() < g_worldTransitionUntil;
		}

		inline bool IsUsableObjectFast(const UObject* object)
		{
			if (!object || !IsPlausibleObjectPointer(object))
				return false;
			return (object->ObjectFlags
				& (RF_PendingKill | RF_Unreachable
					| RF_BeginDestroyed | RF_FinishDestroyed
					| RF_ZombieComponent)) == 0;
		}
		// The object and every outer up the chain are still valid (GetFullName
		// walks them all; a level being streamed out leaves broken chains).
		inline bool ObjectChainUsable(const UObject* object)
		{
			for (int depth = 0; object && depth < 24; ++depth)
			{
				if (!IsUsableObjectFast(object))
					return false;
				object = object->Outer;
			}
			return true;
		}
