		// ---- World-event tunnel (WORLDTUNNEL) ---------------------------
		// Logs 01:24 (same build on both sides): the client put three
		// SharedWorldEvent datagrams (type 11) on the wire and the host never
		// received one, while ProjectileEvent (type 10) from the client does
		// arrive (PROJECTILESTAGE arrived). The relay does not forward type 11
		// (the same thing happened to ParticleNotify, which was moved into the
		// animation packet). Every world event is therefore ALSO sent inside a
		// ProjectileEvent of the normal 68-byte size. Both copies carry the
		// same actor/serial, so the receiver keeps whichever comes first.
		constexpr std::uint8_t kTunnelProjectileKind = 0xEE;
		constexpr std::uint32_t kTunnelProjectileId = 0x57D10000u;
		static_assert(sizeof(ProjectileEventPayload) == 68, "tunnel layout");

		std::uint32_t TunnelNameHash(const char* text, std::size_t length)
		{
			std::uint32_t hash = 2166136261u;
			for (std::size_t index = 0; index < length && text[index]; ++index)
			{
				hash ^= static_cast<unsigned char>(text[index]);
				hash *= 16777619u;
			}
			return hash;
		}

		ProjectileEventPayload PackWorldEventTunnel(
			const SharedWorldEventPayload& event)
		{
			ProjectileEventPayload tunnel{};
			tunnel.eventSerial = event.eventSerial;
			tunnel.mapHash = event.mapHash;
			tunnel.actorId = event.actorId;
			tunnel.projectileId = kTunnelProjectileId
				| static_cast<std::uint32_t>(event.kind);
			tunnel.clientTimeMs = event.entityKey;
			tunnel.kind = static_cast<ProjectileEventKind>(kTunnelProjectileKind);
			tunnel.variant = static_cast<std::uint8_t>(event.kind);
			tunnel.reserved = static_cast<std::uint16_t>(event.flags
				| ((event.originActorId & 0xFFu) << 8));
			const std::int32_t numbers[3] =
				{ event.damage, event.health, event.healthMax };
			std::memcpy(tunnel.location, numbers, sizeof(numbers));
			std::memcpy(tunnel.rotation, event.hitLocation,
				sizeof(event.hitLocation));
			std::memcpy(tunnel.velocity, event.momentum,
				sizeof(event.momentum));
			const std::size_t nameLength =
				strnlen_s(event.damageType, sizeof(event.damageType));
			const std::uint32_t nameHash = nameLength == 0
				? 0u : TunnelNameHash(event.damageType, nameLength);
			std::memcpy(&tunnel.extra, &nameHash, sizeof(nameHash));
			return tunnel;
		}

		bool UnpackWorldEventTunnel(const ProjectileEventPayload& tunnel,
			SharedWorldEventPayload& event)
		{
			if (static_cast<std::uint8_t>(tunnel.kind) != kTunnelProjectileKind
				|| (tunnel.projectileId & 0xFFFF0000u) != kTunnelProjectileId)
			{
				return false;
			}
			event = SharedWorldEventPayload{};
			event.eventSerial = tunnel.eventSerial;
			event.mapHash = tunnel.mapHash;
			event.actorId = tunnel.actorId;
			event.entityKey = tunnel.clientTimeMs;
			event.kind = static_cast<SharedWorldEventKind>(tunnel.variant);
			event.flags = static_cast<std::uint8_t>(tunnel.reserved & 0xFFu);
			event.originActorId = (tunnel.reserved >> 8) & 0xFFu;
			std::int32_t numbers[3]{};
			std::memcpy(numbers, tunnel.location, sizeof(numbers));
			event.damage = numbers[0];
			event.health = numbers[1];
			event.healthMax = numbers[2];
			std::memcpy(event.hitLocation, tunnel.rotation,
				sizeof(event.hitLocation));
			std::memcpy(event.momentum, tunnel.velocity,
				sizeof(event.momentum));
			std::uint32_t nameHash = 0;
			std::memcpy(&nameHash, &tunnel.extra, sizeof(nameHash));
			if (nameHash != 0)
			{
				// Resolved on the game thread (ResolveSharedDamageType).
				sprintf_s(event.damageType, "#dt:%08x", nameHash);
			}
			return true;
		}

		void SendSharedWorldEvent(const SharedWorldEventPayload& event)
		{
			const auto packet = MakePacket(PacketType::SharedWorldEvent,
				g_sessionId.load(), g_playerId.load(), g_sequence++, event);
			SendBytes(&packet, sizeof(packet));
			if (g_config.tunnelWorldEvents)
			{
				const auto tunnel = MakePacket(PacketType::ProjectileEvent,
					g_sessionId.load(), g_playerId.load(), g_sequence++,
					PackWorldEventTunnel(event));
				SendBytes(&tunnel, sizeof(tunnel));
			}
		}

