		// londonclose1: the class versions of interactInLondonX and
		// exitInteractState are empty; inside state PlayerInteractInLondon
		// script runs the state's versions. ProcessEvent runs exactly the
		// function it is given, so the state's own functions are called.
		bool CallInteractInLondonStateFunction(AAlicePlayerController* controller,
			const char* name)
		{
			if (!controller || !IsUsableObjectFast(controller))
				return false;
			UFunction* function = FindFunctionSafe(
				(std::string("Function AliceGame.AlicePlayerController.PlayerInteractInLondon.")
					+ name).c_str());
			if (!function)
				return false;
			std::uint8_t parameters[16]{};
			controller->ProcessEvent(function, parameters, nullptr);
			return true;
		}


