		// CRASH FIX (HEAPGUARD 21:52: one block freed 10x by the script VM,
		// FUN_004dbb10 (struct destroy) -> FUN_004f36d0
		// (UArrayProperty::DestroyValue) -> appFree): FAnimationParaConfig
		// holds a TArray<FName> (and an FString). The proxy's config lives in
		// the mod for the whole session and was memcpy'd into the parameters of
		// the native PlayConfigAnim/StopConfigAnim (const OUT parm) and memcpy'd
		// back. Its AnimationNames buffer was allocated by the SDK's push_back
		// with the mod's CRT; the engine destroys/reassigns that parameter with
		// appFree/appRealloc, and the mod kept handing the very same pointer
		// back on every call: a foreign/stale buffer freed again and again by
		// the game allocator.
		// Now every call gets its own copy allocated by the GAME allocator; the
		// engine may do what it likes with it during the call, afterwards the
		// mod frees whatever the parameter holds (in UE3 the caller owns the
		// parameters) and the array is never copied back.
		struct RawGameArray
		{
			void* data;
			std::int32_t num;
			std::int32_t max;
		};
		static_assert(sizeof(RawGameArray) == 12, "TArray layout");

		bool PrepareGameAnimConfig(const FAnimationParaConfig& source,
			FAnimationParaConfig& target)
		{
			std::memcpy(&target, &source, sizeof(target));
			auto& names = reinterpret_cast<RawGameArray&>(target.AnimationNames);
			auto& desc = reinterpret_cast<RawGameArray&>(target.AnimationDescName);
			desc = RawGameArray{ nullptr, 0, 0 };
			names = RawGameArray{ nullptr, 0, 0 };
			const auto& from =
				reinterpret_cast<const RawGameArray&>(source.AnimationNames);
			if (from.num <= 0 || !from.data)
				return true;
			const std::int32_t count = std::min<std::int32_t>(from.num, 16);
			void* const data = GameMalloc(
				static_cast<std::uint32_t>(count * sizeof(FName)));
			if (!data)
				return false;
			std::memcpy(data, from.data, count * sizeof(FName));
			names = RawGameArray{ data, count, count };
			return true;
		}

		void ReleaseGameAnimConfig(FAnimationParaConfig& target)
		{
			auto& names = reinterpret_cast<RawGameArray&>(target.AnimationNames);
			auto& desc = reinterpret_cast<RawGameArray&>(target.AnimationDescName);
			GameFree(names.data);
			GameFree(desc.data);
			names = RawGameArray{ nullptr, 0, 0 };
			desc = RawGameArray{ nullptr, 0, 0 };
		}

		// Deep copy of FAliceExplosionLightTemplate (TArray<FLightValues>
		// TimeShift + scalars) using the game allocator, so the target owns its
		// own buffer exactly as an UnrealScript struct assignment would.
		bool CopyExplosionLightTemplate(FAliceExplosionLightTemplate& target,
			const FAliceExplosionLightTemplate& source)
		{
			auto& to = reinterpret_cast<RawGameArray&>(target.TimeShift);
			const auto& from = reinterpret_cast<const RawGameArray&>(source.TimeShift);
			if (to.data == from.data && to.data)
			{
				// Already sharing (an older build did this): never free a buffer
				// that someone else owns; give the target its own copy.
				to = RawGameArray{ nullptr, 0, 0 };
			}
			void* copy = nullptr;
			std::int32_t count = 0;
			if (from.data && from.num > 0 && from.num <= 256)
			{
				count = from.num;
				copy = GameMalloc(static_cast<std::uint32_t>(
					count * sizeof(FLightValues)));
				if (!copy)
					return false;   // keep the target's own (default) light
				std::memcpy(copy, from.data, count * sizeof(FLightValues));
			}
			GameFree(to.data);
			to = RawGameArray{ copy, count, count };
			target.HighDetailFrameTime = source.HighDetailFrameTime;
			target.bCheckFrameRate = source.bCheckFrameRate;
			target.CastShadows = source.CastShadows;
			return true;
		}

		// ownanim1: set while this mod replays an animation on a copy.
		bool g_replayingEnemyAnim = false;

		bool NativePlayConfigAnim(AAliceGamePawn* pawn,
			int32_t blendNodeIndex, int32_t configType,
			FAnimationParaConfig& config)
		{
			static UFunction* function = nullptr;
			if (!function)
				function = FindFunctionSafe(
					"Function AliceGame.AliceGamePawn.PlayConfigAnim");
			AAliceGamePawn_execPlayConfigAnim_Params parameters{};
			if (!PrepareGameAnimConfig(config, parameters.AnimConfig))
			{
				static bool logged = false;
				if (!logged)
				{
					logged = true;
					Log("ANIMSTAGE PlayConfigAnim skipped: the game allocator was "
						"not found, a config array cannot be passed safely.");
				}
				return false;
			}
			parameters.BlendNodeIndex = blendNodeIndex;
			parameters.configtype = configType;
			DiagMark("anim.config-play", pawn, blendNodeIndex);
			g_replayingEnemyAnim = true;
			const bool invoked = InvokeNativeFunction(
				pawn, function, parameters);
			g_replayingEnemyAnim = false;
			ReleaseGameAnimConfig(parameters.AnimConfig);
			return invoked;
		}

		bool NativeStopConfigAnim(AAliceGamePawn* pawn, float blendOutTime,
			FAnimationParaConfig& config, bool forceStop = false)
		{
			static UFunction* function = nullptr;
			if (!function)
				function = FindFunctionSafe(
					"Function AliceGame.AliceGamePawn.StopConfigAnim");
			AAliceGamePawn_execStopConfigAnim_Params parameters{};
			if (!PrepareGameAnimConfig(config, parameters.AnimConfig))
				return false;
			parameters.BlendOutTime = blendOutTime;
			parameters.bForceStop = forceStop;
			parameters.bForceAnimNotify = false;
			parameters.bForceAnimEnd = false;
			DiagMark("anim.config-stop", pawn, 0);
			const bool invoked = InvokeNativeFunction(
				pawn, function, parameters);
			ReleaseGameAnimConfig(parameters.AnimConfig);
			return invoked;
		}

		// ---- Enemy presentation: look target and custom animations -------
		// ENEMYLOOK: AliceGameKynapsePawn tracks "Alice" with its head
		// (bAlwaysLookatAlice / HeadLookAtActor), and on every machine that
		// Alice is the LOCAL one. An enemy fighting the other player therefore
		// stared at the wrong Alice. Each shared enemy now head-tracks the
		// Alice it actually fights: on the host the aggro target (host pawn or
		// client proxy), on the client the local Alice for client-driven
		// enemies and the host proxy for host-driven ones.
		// ENEMYANIM: the machine that drives an enemy (host, or the client for
		// enemies chasing the client) plays its hit reactions and attacks
		// through AliceGamePawn.AnimBlendNodes custom animations. The other
		// machine only received position/rotation, so hits looked like nothing
		// happened. Every custom animation started on a driven enemy is sent
		// (blend node index + sequence name hash + rate + loop) and replayed on
		// the peer's copy with PlayConfigAnim, the way the game plays it.
		constexpr SharedWorldEventKind kEventEnemyAnim =
			static_cast<SharedWorldEventKind>(16);

		struct EnemyAnimTrack
		{
			std::uint32_t nameHash = 0;
			float lastTime = 0.0f;
			Clock::time_point lastSent{};
		};
		// animsync1 (31.10): a looping attack (the Ruin's run-up to the ground
		// slam) stayed on the copy forever while the driver had walked on: its
		// "stop" was lost or did not stop a loop (bForceStop was off). The
		// driver now repeats every slot's state once a second (what plays, or
		// that nothing plays) and the copy only changes what differs.
		struct EnemyAnimLastPlay
		{
			std::uint32_t hash = 0;
			float length = 0.0f;
			Clock::time_point at{};
		};
		std::unordered_map<AAliceGameKynapsePawn*, std::unordered_map<int, EnemyAnimLastPlay>> g_enemyAnimLastPlay;
		struct PendingDeathAnim
		{
			SharedWorldEventPayload event{};
			Clock::time_point received{};
			Clock::time_point lastTry{};
			int tries = 0;
		};
		std::unordered_map<AAliceGameKynapsePawn*, PendingDeathAnim> g_pendingDeathAnims;
		bool g_reapplyingDeathAnim = false;
		struct EnemyAnimStopRepeat
		{
			Clock::time_point first{};
			Clock::time_point last{};
			std::uint32_t hash = 0; // stalestop1: the animation that ended
		};
		std::unordered_map<AAliceGameKynapsePawn*, std::unordered_map<int, EnemyAnimStopRepeat>> g_enemyAnimStopSent;
		// Copy side: when a slot last heard "play" from the driver. A looping
		// replay that has not been confirmed for 2.5 s is stopped here.
		std::unordered_map<AAliceGameKynapsePawn*, std::unordered_map<int, Clock::time_point>> g_enemyAnimPlayRx;
		// slotguard1: the driver's last animation per slot of a copy, put back
		// at once when the copy's own reaction cuts it (see TickEnemySlotGuard)
		struct SlotGuardEntry { SharedWorldEventPayload event{}; Clock::time_point at{}; Clock::time_point lastRestore{}; };
		std::unordered_map<AAliceGameKynapsePawn*, std::unordered_map<int, SlotGuardEntry>> g_slotGuard;
		bool g_slotGuardReplaying = false;
		std::unordered_map<AAliceGameKynapsePawn*,
			std::unordered_map<int, EnemyAnimTrack>> g_enemyAnimTracks;
		std::unordered_map<AAliceGameKynapsePawn*, AActor*> g_enemyLookTargets;
		std::unordered_map<AAliceGameKynapsePawn*, bool> g_drivenWhileAlive;
		Clock::time_point g_nextEnemyPresentationTick{};
		int g_enemyAnimLogsLeft = 60;

		// Does THIS machine drive the enemy (its AI / damage reactions run here)?
		bool LocallyDrivesSharedEnemy(std::uint64_t key)
		{
			if (g_config.role == Role::Host)
			{
				const auto aggro = g_hostEnemyAggro.find(key);
				// clientDriveFailed: the host runs it after all (bolterflies,
				// a client that never took it) - the 30.10 host retired the
				// shots of its own running Ruins and ignored shield hits.
				return aggro == g_hostEnemyAggro.end()
					|| !aggro->second.initialized
					|| !aggro->second.targetClient
					|| aggro->second.clientDriveFailed;
			}
			// soloclient1 (13.11 01:3x: the client played on its own, joined to
			// the server with no host - the Menacing Ruin's shot stayed stuck
			// in its hand: every shot of an enemy the host did not hand over
			// was retired here as "the mirrored copy's", but there was no host
			// to send the real one). Without the host in this map, this game
			// runs its own enemies.
			if (!g_remotePresentation.valid || g_currentMap.empty()
				|| _stricmp(g_remotePresentation.state.mapName, g_currentMap.c_str()) != 0)
			{
				return true;
			}
			const auto binding = g_clientSharedEnemyBindings.find(key);
			return binding != g_clientSharedEnemyBindings.end()
				&& binding->second.authorized
				&& binding->second.clientAuthority;
		}

		AActor* SharedEnemyLookTarget(std::uint64_t key, AAlicePawn* localPawn)
		{
			AActor* const proxy = g_remotePawn && IsLiveUObject(g_remotePawn)
				&& !g_remotePawn->bDeleteMe ? g_remotePawn : nullptr;
			if (g_config.role == Role::Host)
			{
				const auto aggro = g_hostEnemyAggro.find(key);
				const bool client = aggro != g_hostEnemyAggro.end()
					&& aggro->second.initialized && aggro->second.targetClient;
				return client && proxy ? proxy : localPawn;
			}
			const auto binding = g_clientSharedEnemyBindings.find(key);
			if (binding == g_clientSharedEnemyBindings.end()
				|| !binding->second.authorized)
			{
				return nullptr;
			}
			return binding->second.clientAuthority || !proxy ? localPawn : proxy;
		}

		void ApplyEnemyLookTarget(AAliceGameKynapsePawn* enemy, AActor* target,
			bool driven)
		{
			if (!enemy || !target)
				return;
			// ruinstun1 (09.11 solo 22:26 vs co-op 21:19): a knocked-down
			// Drifting Ruin turns its head tracking off (ToggleSkeletalControl)
			// and wobbles on the ground in Aglie_Idle_Land. In co-op this
			// function saw HeadLookAtActor gone and switched the tracking
			// straight back on at full strength (SetHeadTrackActor 11 ms
			// later) - the look-at control held the body still, "it lies in
			// an idle pose" for both players. A flyer out of the air is left
			// without head tracking; it gets it back once it flies again.
			// crabstun1 (11.11 21:32: "alone the stunned crab turns fully
			// over; in co-op it does not know which animation to show", on
			// both screens). Same story as the Ruin: on a hit the crab turns
			// its look-at control off (ToggleSkeletalControl) and flips onto
			// its back (KnockBack2A, then 2B lying, 2C getting up) - and this
			// function switched the tracking straight back on, each frame,
			// on the host and on the client: the look-at control pulled the
			// body back toward the target while the animation turned it
			// over. A knocked-down enemy is left without head tracking until
			// it stands again.
			bool knockedDown = false;
			{
				static UClass* const crabClass = AAliceGameCannonCrabPawn::StaticClass();
				if (crabClass && enemy->IsA(crabClass) && enemy->SphinxEventAnimTreeBranchIndex == 2)
					knockedDown = true;
				if (!knockedDown && enemy->Mesh && IsUsableObjectFast(enemy->Mesh))
				{
					UAnimNodeSequence* const oneShot = FindDominantOneShotSequence(enemy->Mesh);
					if (oneShot)
					{
						const std::string anim = oneShot->AnimSeqName.ToString();
						knockedDown = anim.find("KnockBack") != std::string::npos
							|| anim.find("Knockdown") != std::string::npos
							|| anim.find("KnockDown") != std::string::npos;
					}
				}
			}
			{
				static UClass* const flyerClass = AAliceGameKynapseFlyPawn::StaticClass();
				if (knockedDown || (flyerClass && enemy->IsA(flyerClass)
					&& enemy->Physics != EPhysics::PHYS_Flying))
				{
					if (enemy->HeadLookAtActor && g_enemyLookTargets[enemy] == enemy->HeadLookAtActor)
					{
						static UFunction* offHeadTrack = FindFunctionSafe(
							"Function AliceGame.AliceGamePawn.SetHeadTrackActor");
						if (offHeadTrack)
						{
							AAliceGamePawn_eventSetHeadTrackActor_Params parameters{};
							parameters.ActorToTrack = nullptr;
							parameters.SkelControlName = FName("None");
							parameters.LookatBoneName = FName("None");
							parameters.bEnableStrength = false;
							enemy->ProcessEvent(offHeadTrack, &parameters, nullptr);
						}
						enemy->HeadLookAtActor = nullptr;
						static int ruinStunLogsLeft = 20;
						if (ruinStunLogsLeft > 0)
						{
							--ruinStunLogsLeft;
							Log("RUINSTUN head tracking left off on " + ObjectName(enemy)
								+ (knockedDown ? std::string(" while it is knocked down (crabstun1).")
									: " while it is out of the air (physics="
										+ std::to_string(static_cast<int>(enemy->Physics)) + ")."));
						}
					}
					return;
				}
			}
			enemy->bAlwaysLookatAlice = false;
			const bool changed = g_enemyLookTargets[enemy] != target;
			if (enemy->HeadLookAtActor == target && !changed)
				return;
			g_enemyLookTargets[enemy] = target;
			static UFunction* setHeadTrack = nullptr;
			if (!setHeadTrack)
				setHeadTrack = FindFunctionSafe(
					"Function AliceGame.AliceGamePawn.SetHeadTrackActor");
			if (setHeadTrack)
			{
				AAliceGamePawn_eventSetHeadTrackActor_Params parameters{};
				parameters.ActorToTrack = target;
				parameters.SkelControlName = FName("None");
				parameters.LookatBoneName = FName("None");
				parameters.bEnableStrength = true;
				enemy->ProcessEvent(setHeadTrack, &parameters, nullptr);
			}
			enemy->HeadLookAtActor = target;
			// Ranged aim and turn-to-target also read the controller - but
			// only on a copy whose AI does not run here. Writing the
			// controller of an enemy whose own AI runs here (and filling an
			// empty Enemy) skipped its notice/engage step: such enemies
			// stood still until an Alice hit them (22:15 test).
			if (!driven && enemy->Controller
				&& IsLiveUObject(enemy->Controller))
			{
				AController* const controller = enemy->Controller;
				AAlicePawn* const localPawn = GetLocalPawn();
				auto isAlice = [&](const AActor* actor)
				{
					return actor && (actor == localPawn || actor == g_remotePawn);
				};
				if (target->IsA(APawn::StaticClass()) && isAlice(controller->Enemy))
					controller->Enemy = reinterpret_cast<APawn*>(target);
				if (isAlice(controller->Focus))
					controller->Focus = target;
			}
			if (changed && g_enemyAnimLogsLeft > 0)
			{
				--g_enemyAnimLogsLeft;
				Log("ENEMYLOOK " + ObjectName(enemy) + " -> " + ObjectName(target)
					+ '.');
			}
		}

		void SendEnemyAnim(std::uint64_t key, AAliceGameKynapsePawn* enemy,
			int blendIndex, UAnimNodeSequence* sequence, bool stop, bool locomotion = false,
			std::uint32_t stoppedHash = 0)
		{
			const std::string name = sequence
				? sequence->AnimSeqName.ToString() : std::string();
			SharedWorldEventPayload event{};
			event.kind = kEventEnemyAnim;
			event.entityKey = key;
			event.originActorId = g_config.role == Role::Host ? 1u : 2u;
			event.health = blendIndex;
			event.damage = static_cast<std::int32_t>(
				TunnelNameHash(name.c_str(), name.size()));
			if (stop && !sequence && stoppedHash != 0)
				event.damage = static_cast<std::int32_t>(stoppedHash); // stalestop1
			event.healthMax = sequence
				? static_cast<std::int32_t>(std::lround(sequence->Rate * 1000.0f))
				: 1000;
			event.flags = static_cast<std::uint8_t>(
				(sequence && sequence->bLooping ? 1u : 0u) | (stop ? 2u : 0u)
				| (enemy && enemy->Health <= 0 ? 4u : 0u)
				| (sequence && !sequence->bPlaying ? 8u : 0u)
				// rootopt2: Translate (2, the attacks: rootBone=221) takes the
				// root out of the pose just like Discard - both count.
				| (sequence && (sequence->RootBoneOption[0] != ERootBoneAxis::RBA_Default
					|| sequence->RootBoneOption[1] != ERootBoneAxis::RBA_Default) ? 16u : 0u)
				| (sequence && sequence->RootBoneOption[2] != ERootBoneAxis::RBA_Default ? 32u : 0u)
				| (locomotion ? 64u | 1u : 0u)); // locosync1: walk/turn loop
			event.hitLocation[0] = sequence ? sequence->CurrentTime : 0.0f;
			QueueSharedWorldEvent(event);
			if (sequence)
			{
				static std::unordered_set<std::string> rootLogged;
				if (rootLogged.size() < 80 && rootLogged.insert(name).second)
				{
					Log("ROOTOPT TX " + name + " on " + ObjectName(enemy) + ": rootBone="
						+ std::to_string(static_cast<int>(sequence->RootBoneOption[0]))
						+ std::to_string(static_cast<int>(sequence->RootBoneOption[1]))
						+ std::to_string(static_cast<int>(sequence->RootBoneOption[2]))
						+ " meshRmm=" + std::to_string(enemy && enemy->Mesh ? static_cast<int>(enemy->Mesh->RootMotionMode) : -1) + '.');
				}
			}
			if (enemy && enemy->Health <= 0)
			{
				static int deathTx = 40;
				if (deathTx > 0)
				{
					--deathTx;
					Log("DEATHANIM TX " + ObjectName(enemy) + " node " + std::to_string(blendIndex)
						+ " anim=" + (stop ? std::string("<stop>") : name) + '.');
				}
			}
			if (g_enemyAnimLogsLeft > 0)
			{
				--g_enemyAnimLogsLeft;
				Log("ENEMYANIM TX key=" + SharedWorldKeyText(key) + ", enemy="
					+ ObjectName(enemy) + ", node=" + std::to_string(blendIndex)
					+ ", anim=" + name + (stop ? ", stop." : '.' + std::string()));
			}
		}

		UAnimNodeSequence* CustomSequenceOf(UAliceGameAnimNode_BlendBase* node)
		{
			UAnimNodeSequence* best = nullptr;
			float bestWeight = 0.05f;
			for (int32_t c = 0; c < node->Children.size(); ++c)
			{
				const FAnimBlendChild& child = node->Children.at(c);
				if (child.Anim && child.Anim->IsA(UAnimNodeSequence::StaticClass())
					&& child.Weight > bestWeight)
				{
					bestWeight = child.Weight;
					best = reinterpret_cast<UAnimNodeSequence*>(child.Anim);
				}
			}
			return best;
		}

		// HAND-OVER FREEZE (30.10 01:08:34): while the other game drove an
		// enemy, its animations were replayed here with PlayConfigAnim
		// (bCauseActorAnimEnd off) over the animation this copy's own Sphinx
		// action had started - that action waits for its OnAnimEnd forever.
		// Handed back, the AI stood still (38 s, no state change) while the
		// other copy went on. When a copy starts driving, every custom
		// animation slot reports its end, so the waiting actions finish and
		// the AI picks its next move.
		void ReleaseEnemyAnimWaits(AAliceGameKynapsePawn* enemy, const char* why)
		{
			if (!enemy || !IsUsableObjectFast(enemy) || enemy->Health <= 0)
				return;
			int released = 0;
			const int32_t count = std::min<int32_t>(enemy->AnimBlendNodes.size(), 32);
			for (int32_t index = 0; index < count; ++index)
			{
				UAliceGameAnimNode_BlendBase* const node = enemy->AnimBlendNodes.at(index);
				if (!node || !IsUsableObjectFast(node))
					continue;
				// release2 (31.10 12:54): only the child with weight was ended -
				// after the replay had stopped the slot no child had any, and
				// "released 0" every time: the Ruin whose spawn animation the
				// replay had replaced never moved (AI BROKEN). Every sequence
				// child of every custom slot reports its end now.
				for (int32_t c = 0; c < node->Children.size(); ++c)
				{
					const FAnimBlendChild& child = node->Children.at(c);
					if (!child.Anim || !IsUsableObjectFast(child.Anim)
						|| !child.Anim->IsA(UAnimNodeSequence::StaticClass()))
					{
						continue;
					}
					auto* const sequence = reinterpret_cast<UAnimNodeSequence*>(child.Anim);
					enemy->eventOnAnimEnd(sequence, sequence->CurrentTime, 0.0f);
					++released;
				}
			}
			static int logsLeft = 40;
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("HANDOVER released " + std::to_string(released) + " animation wait(s) of "
					+ ObjectName(enemy) + " (" + why + ").");
			}
		}

		// locosync1 (10.11 20:44:43, Colossal Ruin driven by the client): its
		// walking and turning (Tank_S1_Walk, Turn_Lft/Rgt_45, S2_Attack_Walk,
		// the turning shots) come from its tree's speed / rotate nodes, not
		// from an animation slot, so only slot animations reached the copy -
		// on the host it stood in Tank_S1_Idle_1 while it walked and turned.
		// When the driver plays no slot animation on its full-body slot, the
		// strongest moving animation of its tree is sent for that slot as a
		// loop (flag 64), and its stop once it goes back to idle.
		std::unordered_map<AAliceGameKynapsePawn*, std::uint32_t> g_locoSent;
		void CaptureDrivenEnemyLocomotion(std::uint64_t key, AAliceGameKynapsePawn* enemy)
		{
			if (!enemy || !enemy->Mesh || !IsUsableObjectFast(enemy->Mesh) || enemy->Health <= 0)
				return;
			// only the Colossal Ruin for now: the other enemies' copies walk
			// well enough from their own trees
			static UClass* const tankClass = AAliceGameDoomTankPawn::StaticClass();
			if (!tankClass || !enemy->IsA(tankClass))
				return;
			const int32_t nodes = std::min<int32_t>(enemy->AnimBlendNodes.size(), 32);
			int slotIndex = -1;
			for (int32_t index = 0; index < nodes; ++index)
			{
				UAliceGameAnimNode_BlendBase* const node = enemy->AnimBlendNodes.at(index);
				if (!node || !IsUsableObjectFast(node))
					continue;
				if (node->bIsPlayingCustomAnim)
				{
					g_locoSent.erase(enemy); // a real slot animation runs; it is sent itself
					return;
				}
				if (slotIndex < 0 && node->NodeName.ToString().find("FullBody") != std::string::npos)
					slotIndex = index;
			}
			if (slotIndex < 0)
				return;
			UAnimNodeSequence* best = nullptr;
			float bestWeight = 0.3f;
			const int32_t count = std::min<int32_t>(enemy->Mesh->AnimTickArray.size(), 2048);
			for (int32_t i = 0; i < count; ++i)
			{
				UAnimNode* const node = enemy->Mesh->AnimTickArray.at(i);
				if (!node || !node->IsA(UAnimNodeSequence::StaticClass()) || node->NodeTotalWeight <= bestWeight)
					continue;
				auto* const sequence = reinterpret_cast<UAnimNodeSequence*>(node);
				if (!sequence->AnimSeq || !sequence->bPlaying)
					continue;
				bestWeight = node->NodeTotalWeight;
				best = sequence;
			}
			const std::string name = best ? best->AnimSeqName.ToString() : std::string();
			const bool moving = best && name.find("Idle") == std::string::npos
				&& (name.find("Walk") != std::string::npos || name.find("Turn") != std::string::npos
					|| name.find("Run") != std::string::npos);
			auto sent = g_locoSent.find(enemy);
			if (!moving)
			{
				if (sent != g_locoSent.end())
				{
					SendEnemyAnim(key, enemy, slotIndex, nullptr, true, true);
					g_locoSent.erase(sent);
				}
				return;
			}
			const std::uint32_t hash = TunnelNameHash(name.c_str(), name.size());
			static std::unordered_map<AAliceGameKynapsePawn*, Clock::time_point> lastLoco;
			const auto now = Clock::now();
			if (sent != g_locoSent.end() && sent->second == hash
				&& now - lastLoco[enemy] < std::chrono::milliseconds(500))
			{
				return;
			}
			g_locoSent[enemy] = hash;
			lastLoco[enemy] = now;
			SendEnemyAnim(key, enemy, slotIndex, best, false, true);
		}

		void CaptureDrivenEnemyAnims(std::uint64_t key, AAliceGameKynapsePawn* enemy)
		{
			CaptureDrivenEnemyLocomotion(key, enemy); // locosync1
			auto& tracks = g_enemyAnimTracks[enemy];
			const int32_t count = std::min<int32_t>(enemy->AnimBlendNodes.size(), 32);
			for (int32_t index = 0; index < count; ++index)
			{
				UAliceGameAnimNode_BlendBase* const node =
					enemy->AnimBlendNodes.at(index);
				if (!node || !IsLiveUObject(node))
					continue;
				UAnimNodeSequence* const sequence =
					node->bIsPlayingCustomAnim ? CustomSequenceOf(node) : nullptr;
				const auto found = tracks.find(index);
				const auto now = Clock::now();
				if (!sequence || !sequence->AnimSeq)
				{
					auto& stops = g_enemyAnimStopSent[enemy];
					if (found != tracks.end())
					{
						const std::uint32_t endedHash = found->second.nameHash;
						tracks.erase(found);
						SendEnemyAnim(key, enemy, index, nullptr, true, false, endedHash);
						stops[index] = EnemyAnimStopRepeat{ now, now, endedHash };
					}
					else
					{
						// Repeat the stop of a slot that played before, once a
						// second for 6 s (the copy ignores it if nothing plays).
						const auto stop = stops.find(index);
						if (stop != stops.end() && now - stop->second.last > std::chrono::seconds(1)
							&& now - stop->second.first < std::chrono::seconds(6))
						{
							SendEnemyAnim(key, enemy, index, nullptr, true, false, stop->second.hash);
							stop->second.last = now;
						}
					}
					continue;
				}
				const std::string name = sequence->AnimSeqName.ToString();
				const std::uint32_t hash = TunnelNameHash(name.c_str(), name.size());
				const bool restarted = found != tracks.end()
					&& found->second.nameHash == hash
					&& sequence->CurrentTime + 0.05f < found->second.lastTime;
				const bool refresh = found != tracks.end() && enemy->Health > 0
					&& now - found->second.lastSent > std::chrono::milliseconds(200);
				Clock::time_point lastSent = found != tracks.end() ? found->second.lastSent : Clock::time_point{};
				if (found == tracks.end() || found->second.nameHash != hash || restarted || refresh)
				{
					SendEnemyAnim(key, enemy, index, sequence, false);
					lastSent = now;
				}
				tracks[index] = EnemyAnimTrack{ hash, sequence->CurrentTime, lastSent };
			}
		}

		bool ResolveEnemyAnimName(AAliceGameKynapsePawn* enemy, std::uint32_t hash,
			FName& out)
		{
			static std::unordered_map<std::uint64_t, FName> cache;
			const std::uint64_t cacheKey =
				(static_cast<std::uint64_t>(reinterpret_cast<uintptr_t>(
					enemy->Mesh)) << 32) | hash;
			const auto cached = cache.find(cacheKey);
			if (cached != cache.end())
			{
				out = cached->second;
				return true;
			}
			if (!enemy->Mesh)
				return false;
			const auto& sets = enemy->Mesh->AnimSets;
			for (int32_t s = 0; s < sets.size(); ++s)
			{
				UAnimSet* const set = sets.at(s);
				if (!set || !IsLiveUObject(set))
					continue;
				for (int32_t q = 0; q < set->Sequences.size(); ++q)
				{
					UAnimSequence* const sequence = set->Sequences.at(q);
					if (!sequence)
						continue;
					const std::string name = sequence->SequenceName.ToString();
					if (TunnelNameHash(name.c_str(), name.size()) == hash)
					{
						cache.emplace(cacheKey, sequence->SequenceName);
						out = sequence->SequenceName;
						return true;
					}
				}
			}
			// enemyanimset1 (10.11 19:43, Colossal Ruin driven by the client):
			// its artillery-rain attacks (Tank_S1_Attack_Range2_*) and more
			// never played on the host's copy - those clips live in an
			// animation set the driver's Ruin took on during the fight, which
			// the copy's mesh never got, so the name could not be resolved.
			// The set holding the clip is looked for among all loaded sets
			// (once per enemy mesh and clip, at most every 3 s) and added to
			// the copy's mesh - an own buffer from the game's allocator, as
			// for the giant Alice (animsets1).
			static std::unordered_map<std::uint64_t, Clock::time_point> searched;
			const auto now = Clock::now();
			auto& last = searched[cacheKey];
			if (last != Clock::time_point{} && now - last < std::chrono::seconds(3))
				return false;
			last = now;
			TArray<UObject*>* const objects = UObject::GObjObjects();
			UClass* const animSetClass = UAnimSet::StaticClass();
			if (!objects || !animSetClass)
				return false;
			UAnimSet* holder = nullptr;
			FName holderName;
			for (int32_t index = 0; index < objects->size() && !holder; ++index)
			{
				UObject* const object = objects->at(index);
				if (!object || object->IsDefaultObject() || !IsUsableObjectFast(object)
					|| !object->IsA(animSetClass))
				{
					continue;
				}
				auto* const set = reinterpret_cast<UAnimSet*>(object);
				for (int32_t q = 0; q < set->Sequences.size(); ++q)
				{
					UAnimSequence* const sequence = set->Sequences.at(q);
					if (!sequence || !IsUsableObjectFast(sequence))
						continue;
					const std::string name = sequence->SequenceName.ToString();
					if (TunnelNameHash(name.c_str(), name.size()) == hash)
					{
						holder = set;
						holderName = sequence->SequenceName;
						break;
					}
				}
			}
			static int logsLeft = 30;
			if (!holder)
			{
				if (logsLeft > 0)
				{
					--logsLeft;
					Log("ENEMYANIMSET no loaded animation set has the clip the driver plays on "
						+ ObjectName(enemy) + " (hash " + std::to_string(hash) + ").");
				}
				return false;
			}
			auto& to = reinterpret_cast<RawGameArray&>(enemy->Mesh->AnimSets);
			if (to.num < 0 || to.num > 64)
				return false;
			void* const grown = GameMalloc(static_cast<std::uint32_t>((to.num + 1) * sizeof(void*)));
			if (!grown)
				return false;
			if (to.num > 0 && to.data)
				std::memcpy(grown, to.data, to.num * sizeof(void*));
			static_cast<UAnimSet**>(grown)[to.num] = holder;
			// the old buffer is left alone (something may still read it this
			// frame); sequences are looked up by name when they are played
			to = RawGameArray{ grown, to.num + 1, to.num + 1 };
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("ENEMYANIMSET " + ObjectName(enemy) + " takes the animation set " + ObjectName(holder)
					+ " for " + holderName.ToString() + " (now " + std::to_string(to.num) + " sets).");
			}
			cache.emplace(cacheKey, holderName);
			out = holderName;
			return true;
		}

		// rootopt1 (31.10 17:06, Madcaps): the copy reported RootMotionMode
		// Ignore + fake root motion. The driver moves the actor with the
		// attack's root motion and keeps the mesh root in place (its sequence
		// discards the root translation); the copy's replay kept the root
		// translation in the mesh, so it lunged forward twice as far (mesh +
		// pose) and snapped back when the attack ended. The driver's
		// discard flags are sent (16: X/Y, 32: Z) and applied to the replay.
		void ApplyDriverRootOption(UAnimNodeSequence* sequence, std::uint32_t flags)
		{
			if (!sequence)
				return;
			const ERootBoneAxis horizontal = (flags & 16u) ? ERootBoneAxis::RBA_Discard : ERootBoneAxis::RBA_Default;
			const ERootBoneAxis vertical = (flags & 32u) ? ERootBoneAxis::RBA_Discard : ERootBoneAxis::RBA_Default;
			sequence->RootBoneOption[0] = horizontal;
			sequence->RootBoneOption[1] = horizontal;
			sequence->RootBoneOption[2] = vertical;
		}

		void OnRemoteEnemyAnim(const SharedWorldEventPayload& event,
			AWorldInfo* world)
		{
			if (!g_config.sharedEnemyTransforms || !world)
				return;
			AAliceGameKynapsePawn* const enemy =
				FindSharedEnemy(event.entityKey, world);
			// deathanim1: a dead copy still takes the death animation - unless
			// this game drove it while it lived (deathanim2). deathanim3: for
			// a dead enemy "who drives it" is not asked - the host forgets the
			// aggro of a dead enemy and believed it drove it, so the client's
			// Grunt_Attack_Death never played here (13:05:09, an idle body).
			if (!enemy || enemy->bDeleteMe)
				return;
			if (enemy->Health <= 0)
			{
				static int deathRx = 40;
				if (deathRx > 0)
				{
					--deathRx;
					Log("DEATHANIM RX " + ObjectName(enemy) + " node " + std::to_string(event.health)
						+ (event.flags & 2u ? " stop" : " play") + (g_drivenWhileAlive[enemy]
							? ": ignored, this game drove it." : ": applied."));
				}
				if (g_drivenWhileAlive[enemy])
					return;
			}
			else if (LocallyDrivesSharedEnemy(event.entityKey))
				return; // our own AI plays this enemy's animations
			const int blendIndex = event.health;
			if (blendIndex < 0 || blendIndex >= enemy->AnimBlendNodes.size())
				return;
			const bool looping = (event.flags & 1u) != 0;
			const bool stop = (event.flags & 2u) != 0;
			// deathanim4: the driver's death animation (flag 4). The copy's
			// own death comes a little later (the lethal hit, 14:24:03) and
			// clears it - an idle body until the hide. Kept and re-applied.
			if ((event.flags & 4u) && !stop && !g_reapplyingDeathAnim)
				g_pendingDeathAnims[enemy] = PendingDeathAnim{ event, Clock::now(), {}, 0 };
			// deathanim5 (14:52:33): the driver itself stopped the death
			// animation later (its dying sequence goes on) - the copy re-played
			// it nine times over that stop. A stop ends the re-applying.
			if (stop && enemy->Health <= 0 && !g_reapplyingDeathAnim)
			{
				const auto pending = g_pendingDeathAnims.find(enemy);
				if (pending != g_pendingDeathAnims.end() && pending->second.event.health == blendIndex)
					g_pendingDeathAnims.erase(pending);
			}
			// deadstop1 (client crash 0x009AD616 twice, 17:14:29 and 19:44:19,
			// Card Guard fights): both times the host's "stop" reached a Card
			// Guard here that was already dead and playing its own death
			// (CardGD_Zombie_Dead03 / its last attack), and 130-200 ms later
			// the next Card Guard's walk check (line traces, FUN_007c34d0)
			// crashed on the half-torn-down body. A dead enemy's animation is
			// never stopped from the other game: its own death runs out.
			// The first of the two (17:14:29) stopped a LIVE Card Guard in
			// the middle of its CardGD_Attack_All rush, which the mod itself
			// flags ("got StopConfigAnim during an attack"): a Card Guard in
			// the middle of an action is left to finish it as well.
			const bool cardGuardMidAction = stop
				&& enemy->IsA(AAliceGameCardGuardPawn::StaticClass()) && enemy->Health > 0
				&& enemy->SphinxEventAnimTreeBranchIndex != UsualEnemyBranch(enemy);
			if (stop && (enemy->Health <= 0 || enemy->bTearOff || enemy->bPlayedDeath
				|| cardGuardMidAction))
			{
				static int deadStopLogs = 30;
				if (deadStopLogs > 0)
				{
					--deadStopLogs;
					Log("DEADSTOP the other game's stop of " + ObjectName(enemy)
						+ (cardGuardMidAction && enemy->Health > 0
						? " is ignored: it is in the middle of an action here."
						: " is ignored: it is dead here and plays its own death."));
				}
				return;
			}
			FName animName;
			if (!stop && !ResolveEnemyAnimName(enemy,
				static_cast<std::uint32_t>(event.damage), animName))
			{
				if (g_enemyAnimLogsLeft > 0)
				{
					--g_enemyAnimLogsLeft;
					Log("ENEMYANIM RX unresolved anim on " + ObjectName(enemy) + '.');
				}
				return;
			}
			// animsync1: the driver repeats its state every second; change only
			// what differs, so a repeat never restarts an animation.
			{
				UAliceGameAnimNode_BlendBase* const node = enemy->AnimBlendNodes.at(blendIndex);
				if (!node || !IsLiveUObject(node))
					return;
				UAnimNodeSequence* const current =
					node->bIsPlayingCustomAnim ? CustomSequenceOf(node) : nullptr;
				const bool playing = current && current->AnimSeq;
				if (stop)
				{
					if (!playing)
					{
						g_enemyAnimPlayRx[enemy].erase(blendIndex);
						g_slotGuard[enemy].erase(blendIndex); // slotguard1
						return;
					}
					// stalestop1 (11.11 19:23:34, Cannon Crab): a late stop of
					// the driver's previous animation (each event goes three
					// times) cut the flip that had already replaced it here.
					// A stop that names another animation than the one this
					// slot plays is old news.
					{
						static const std::uint32_t emptyHash = TunnelNameHash("", 0);
						const std::string playingName = current->AnimSeqName.ToString();
						const std::uint32_t playingHash = TunnelNameHash(playingName.c_str(), playingName.size());
						const std::uint32_t stopHash = static_cast<std::uint32_t>(event.damage);
						if (stopHash != 0 && stopHash != emptyHash && stopHash != playingHash)
						{
							static int staleStopLogs = 30;
							if (staleStopLogs > 0)
							{
								--staleStopLogs;
								Log("ANIMSYNC stale stop for " + ObjectName(enemy) + " ignored: it plays "
									+ playingName + " here (stalestop1).");
							}
							return;
						}
					}
					g_enemyAnimPlayRx[enemy].erase(blendIndex);
					g_slotGuard[enemy].erase(blendIndex); // slotguard1
					// guardstop1 (10.11 00:16:02 client crash 0x009AD616, the
					// third time in a Card Guard fight): the host's stop cut
					// this copy's CardGD_Attack_All rush ("got StopConfigAnim
					// during an attack") while its branch was still the usual
					// one, so deadstop1 let it through - the walk check crashed
					// 265 ms later. A Card Guard's attack is never stopped from
					// the other game; it plays out (as in 17:14 / 19:44).
					if (enemy->IsA(AAliceGameCardGuardPawn::StaticClass()))
					{
						const std::string playingName = current->AnimSeqName.ToString();
						if (playingName.find("Attack") != std::string::npos
							|| playingName.find("Lunge") != std::string::npos)
						{
							static int guardStopLogs = 30;
							if (guardStopLogs > 0)
							{
								--guardStopLogs;
								Log("GUARDSTOP the other game's stop of " + ObjectName(enemy)
									+ " is ignored: it plays " + playingName + " here, which runs out.");
							}
							return;
						}
					}
					static int stopLogs = 40;
					if (stopLogs > 0)
					{
						--stopLogs;
						Log("ANIMSYNC stop " + ObjectName(enemy) + " node " + std::to_string(blendIndex)
							+ ": was playing " + current->AnimSeqName.ToString() + '.');
					}
				}
				else
				{
					g_enemyAnimPlayRx[enemy][blendIndex] = Clock::now();
					if (!g_slotGuardReplaying && enemy->Health > 0)
					{
						SlotGuardEntry& guard = g_slotGuard[enemy][blendIndex];
						guard.event = event;
						guard.at = Clock::now();
					}
					if (playing && current->AnimSeqName.ToString() == animName.ToString())
					{
						// animtime1 (31.10 15:27, shield Madcap): the copy ran
						// its own clock - the attack ended early there and the
						// weapon-stuck pause (the driver holds the animation)
						// never showed. Follow the driver's time and pause.
						ApplyDriverRootOption(current, event.flags);
						const bool driverPaused = (event.flags & 8u) != 0;
						const float driverTime = event.hitLocation[0]
							+ (driverPaused ? 0.0f : 0.05f * current->Rate);
						// animtime2: 0.3 s - small corrections made the copy jerk.
						if (std::fabs(current->CurrentTime - driverTime) > 0.3f)
							NativeSetPosition(current, driverTime);
						if (driverPaused && current->bPlaying)
							current->bPlaying = 0;
						else if (!driverPaused && !current->bPlaying)
							current->bPlaying = 1;
						return;
					}
				}
			}
			// Same config shape the proxy uses for its replayed animations.
			FAnimationParaConfig config{};
			auto& names = reinterpret_cast<RawGameArray&>(config.AnimationNames);
			names = RawGameArray{ stop ? nullptr : &animName, stop ? 0 : 1,
				stop ? 0 : 1 };
			reinterpret_cast<RawGameArray&>(config.AnimationDescName) =
				RawGameArray{ nullptr, 0, 0 };
			config.BlendNodeIndex = static_cast<std::uint8_t>(blendIndex);
			config.AnimType = static_cast<int32_t>(EAnimConfigType::EACT_Arbitrary);
			config.BlendInTime = g_slotGuardReplaying ? 0.0f : 0.1f; // slotguard1: no fade back in
			config.BlendOutTime = 0.2f;
			config.PlayRate = std::clamp(event.healthMax / 1000.0f, 0.05f, 10.0f);
			config.bLoop = looping;
			config.bCauseActorAnimEnd = false;
			config.bTriggerFakeRootMotion = false;
			config.bNotExtendAnimTimeForFakeRootMotion = true;
			config.AnimPlayType =
				static_cast<std::uint8_t>(EConfigAnimPlayType::ECAPT_OneByOne);
			// replayloop1 (31.10 17:31, Madcap dodge): the copy's dodge ended a
			// little before the driver's; the next refresh (5 a second) found
			// the slot empty and started the dodge again - the copy rolled in
			// a loop. A refresh of the animation this slot just played is not
			// replayed when the driver is already at its end.
			if (!stop && !g_reapplyingDeathAnim && enemy->Health > 0)
			{
				const auto lastIt = g_enemyAnimLastPlay[enemy].find(blendIndex);
				if (lastIt != g_enemyAnimLastPlay[enemy].end()
					&& lastIt->second.hash == static_cast<std::uint32_t>(event.damage))
				{
					const float driverTime = event.hitLocation[0];
					const float length = lastIt->second.length;
					const auto sincePlay = Clock::now() - lastIt->second.at;
					const bool nearEnd = length > 0.0f && driverTime > length - 0.25f;
					const bool justStarted = driverTime <= 0.15f && sincePlay < std::chrono::milliseconds(400);
					const bool stale = driverTime > 0.15f && length > 0.0f
						&& sincePlay < std::chrono::duration_cast<Clock::duration>(
							std::chrono::duration<float>(length + 0.3f));
					// grabsync1 (10.11 00:07:37, Zombie Card Guard grab): the
					// copy's Grab_C was cut at 0.94 s by its own native grab
					// logic once this Alice was let go (it went to Strafe_Lft),
					// while the driver held the grab to 3 s; the refresh was
					// skipped as "stale" since this slot had played it. When
					// the slot no longer plays it, the driver's animation is
					// put back at the driver's time.
					bool stillHere = true;
					if (stale && !nearEnd)
					{
						UAliceGameAnimNode_BlendBase* const slot = enemy->AnimBlendNodes.at(blendIndex);
						UAnimNodeSequence* const current = slot && IsLiveUObject(slot)
							&& slot->bIsPlayingCustomAnim ? CustomSequenceOf(slot) : nullptr;
						stillHere = current && current->AnimSeqName.ToString() == animName.ToString();
						if (!stillHere)
						{
							static int grabSyncLogsLeft = 20;
							if (grabSyncLogsLeft > 0)
							{
								--grabSyncLogsLeft;
								Log("ANIMSYNC restore " + ObjectName(enemy) + " node "
									+ std::to_string(blendIndex) + ": " + animName.ToString()
									+ " was cut here, the other game still plays it at "
									+ std::to_string(driverTime) + " s.");
							}
						}
					}
					if (nearEnd || justStarted || (stale && stillHere))
					{
						reinterpret_cast<RawGameArray&>(config.AnimationNames) = RawGameArray{ nullptr, 0, 0 };
						return;
					}
				}
			}
			const bool invoked = stop
				? NativeStopConfigAnim(enemy, 0.2f, config, true)
				: NativePlayConfigAnim(enemy, blendIndex,
					static_cast<int32_t>(EAnimConfigType::EACT_Arbitrary), config);
			// The local copy only borrowed animName; never let anything free it.
			names = RawGameArray{ nullptr, 0, 0 };
			if (invoked && !stop)
			{
				EnemyAnimLastPlay last{};
				last.hash = static_cast<std::uint32_t>(event.damage);
				last.at = Clock::now();
				UAliceGameAnimNode_BlendBase* const node = enemy->AnimBlendNodes.at(blendIndex);
				if (node && IsLiveUObject(node))
					for (int32_t c = 0; c < node->Children.size(); ++c)
					{
						UAnimNode* const child = node->Children.at(c).Anim;
						if (child && child->IsA(UAnimNodeSequence::StaticClass()))
						{
							auto* const seq = reinterpret_cast<UAnimNodeSequence*>(child);
							if (seq->AnimSeq && seq->AnimSeqName.ToString() == animName.ToString())
							{
								const float rate = seq->Rate > 0.01f ? seq->Rate : 1.0f;
								last.length = seq->AnimSeq->SequenceLength / rate;
								break;
							}
						}
					}
				g_enemyAnimLastPlay[enemy][blendIndex] = last;
			}
			if (invoked && !stop && event.hitLocation[0] <= 0.15f)
			{
				UAliceGameAnimNode_BlendBase* const node = enemy->AnimBlendNodes.at(blendIndex);
				if (node && IsLiveUObject(node))
					for (int32_t c = 0; c < node->Children.size(); ++c)
					{
						UAnimNode* const child = node->Children.at(c).Anim;
						if (child && child->IsA(UAnimNodeSequence::StaticClass())
							&& reinterpret_cast<UAnimNodeSequence*>(child)->AnimSeqName.ToString() == animName.ToString())
						{
							ApplyDriverRootOption(reinterpret_cast<UAnimNodeSequence*>(child), event.flags);
						}
					}
			}
			if (invoked && !stop && event.hitLocation[0] > 0.15f)
			{
				UAliceGameAnimNode_BlendBase* const node = enemy->AnimBlendNodes.at(blendIndex);
				if (node && IsLiveUObject(node) && node->bIsPlayingCustomAnim)
					if (UAnimNodeSequence* const fresh = CustomSequenceOf(node))
						if (fresh->AnimSeqName.ToString() == animName.ToString())
						{
							ApplyDriverRootOption(fresh, event.flags);
							NativeSetPosition(fresh, event.hitLocation[0]);
							if (event.flags & 8u)
								fresh->bPlaying = 0;
						}
			}
			if (g_enemyAnimLogsLeft > 0)
			{
				--g_enemyAnimLogsLeft;
				Log("ENEMYANIM RX " + std::string(stop ? "stop" : "play") + " enemy="
					+ ObjectName(enemy) + ", node=" + std::to_string(blendIndex)
					+ ", anim=" + (stop ? std::string("-") : animName.ToString())
					+ ", invoked=" + (invoked ? "yes." : "no."));
			}
		}

		// slotguard1 (10.11 22:04:38-44, Colossal Ruin stunned, driven by the
		// client): the host's copy played the driver's Tank_S2_Rest_B, and
		// each hit on its head (its own TakeDamage reaction) cut that slot -
		// the body went to idle for ~0.3 s until the next refresh put the
		// animation back with a fade: the flicker on stuns and hits. Every
		// frame, a copy's slot that lost the driver's animation (no stop from
		// the driver, its last refresh younger than 450 ms) gets it back at
		// once, at the driver's time and without a fade.
		void TickEnemySlotGuard()
		{
			if (!g_connected || g_config.localMirror || WorldTransitionActive() || !g_currentWorld)
			{
				g_slotGuard.clear();
				return;
			}
			static UClass* const tankClass = AAliceGameDoomTankPawn::StaticClass();
			// crabguard1 (11.11 chapter 2: the copy of the Cannon Crab flickered
			// while it lay on its back - KnockBack2A cut by each hit's own
			// reaction here): the Cannon Crab gets the same guard
			static UClass* const crabClass = AAliceGameCannonCrabPawn::StaticClass();
			const auto now = Clock::now();
			static int logsLeft = 30;
			for (auto it = g_slotGuard.begin(); it != g_slotGuard.end();)
			{
				AAliceGameKynapsePawn* const enemy = it->first;
				if (!enemy || !IsUsableObjectFast(enemy) || enemy->bDeleteMe || enemy->Health <= 0
					|| !(tankClass && enemy->IsA(tankClass)) && !(crabClass && enemy->IsA(crabClass))
					|| it->second.empty())
				{
					it = g_slotGuard.erase(it);
					continue;
				}
				for (auto slotIt = it->second.begin(); slotIt != it->second.end();)
				{
					SlotGuardEntry& guard = slotIt->second;
					const int blendIndex = slotIt->first;
					const auto age = now - guard.at;
					if (age > std::chrono::milliseconds(450) || LocallyDrivesSharedEnemy(guard.event.entityKey)
						|| blendIndex < 0 || blendIndex >= enemy->AnimBlendNodes.size())
					{
						slotIt = it->second.erase(slotIt);
						continue;
					}
					UAliceGameAnimNode_BlendBase* const node = enemy->AnimBlendNodes.at(blendIndex);
					UAnimNodeSequence* const current = node && IsLiveUObject(node) && node->bIsPlayingCustomAnim
						? CustomSequenceOf(node) : nullptr;
					std::string currentName;
					if (current && current->AnimSeq)
						currentName = current->AnimSeqName.ToString();
					const bool same = !currentName.empty()
						&& TunnelNameHash(currentName.c_str(), currentName.size())
							== static_cast<std::uint32_t>(guard.event.damage);
					if (same || now - guard.lastRestore < std::chrono::milliseconds(150))
					{
						++slotIt;
						continue;
					}
					const bool driverPaused = (guard.event.flags & 8u) != 0;
					const float seconds = std::chrono::duration<float>(age).count();
					const float rate = std::clamp(guard.event.healthMax / 1000.0f, 0.05f, 10.0f);
					SharedWorldEventPayload replay = guard.event;
					replay.hitLocation[0] = guard.event.hitLocation[0] + (driverPaused ? 0.0f : seconds * rate);
					// a one-shot the driver is about to finish is left to end
					const auto last = g_enemyAnimLastPlay[enemy].find(blendIndex);
					const bool looping = (guard.event.flags & 1u) != 0;
					if (!looping && last != g_enemyAnimLastPlay[enemy].end()
						&& last->second.length > 0.0f && replay.hitLocation[0] > last->second.length - 0.25f)
					{
						slotIt = it->second.erase(slotIt);
						continue;
					}
					if (looping && last != g_enemyAnimLastPlay[enemy].end() && last->second.length > 0.05f)
						replay.hitLocation[0] = std::fmod(replay.hitLocation[0], last->second.length);
					guard.lastRestore = now;
					if (logsLeft > 0)
					{
						--logsLeft;
						Log("SLOTGUARD " + ObjectName(enemy) + " node " + std::to_string(blendIndex)
							+ ": the driver's animation was cut here (now "
							+ (currentName.empty() ? std::string("nothing") : currentName)
							+ "), put back at " + std::to_string(replay.hitLocation[0]) + " s (slotguard1).");
					}
					g_slotGuardReplaying = true;
					OnRemoteEnemyAnim(replay, g_currentWorld);
					g_slotGuardReplaying = false;
					++slotIt;
				}
				++it;
			}
		}

		void ReapplyPendingDeathAnims(Clock::time_point now)
		{
			for (auto it = g_pendingDeathAnims.begin(); it != g_pendingDeathAnims.end();)
			{
				AAliceGameKynapsePawn* const enemy = it->first;
				PendingDeathAnim& pending = it->second;
				if (now - pending.received > std::chrono::seconds(3) || pending.tries >= 3
					|| !enemy || !IsUsableObjectFast(enemy) || enemy->bDeleteMe
					|| g_drivenWhileAlive[enemy])
				{
					it = g_pendingDeathAnims.erase(it);
					continue;
				}
				if (enemy->Health > 0 || now - pending.lastTry < std::chrono::milliseconds(200))
				{
					++it;
					continue;
				}
				const int index = pending.event.health;
				bool playing = false;
				if (index >= 0 && index < enemy->AnimBlendNodes.size())
				{
					UAliceGameAnimNode_BlendBase* const node = enemy->AnimBlendNodes.at(index);
					if (node && IsLiveUObject(node) && node->bIsPlayingCustomAnim)
					{
						if (UAnimNodeSequence* const current = CustomSequenceOf(node))
						{
							const std::string name = current->AnimSeqName.ToString();
							playing = TunnelNameHash(name.c_str(), name.size())
								== static_cast<std::uint32_t>(pending.event.damage);
						}
					}
				}
				pending.lastTry = now;
				if (!playing)
				{
					++pending.tries;
					g_reapplyingDeathAnim = true;
					OnRemoteEnemyAnim(pending.event, g_currentWorld);
					g_reapplyingDeathAnim = false;
					static int logsLeft = 40;
					if (logsLeft > 0)
					{
						--logsLeft;
						Log("DEATHANIM re-applied on " + ObjectName(enemy) + " (try "
							+ std::to_string(pending.tries) + "): its own death had cleared it.");
					}
				}
				++it;
			}
		}

		// ---- Armour plates (Menacing Ruin) -----------------------------
		// The Ruins' armour is a set of AliceGameNPCAttachedActor on the
		// pawn (NPCAttachedActors[i]: HP, ActorState Idle/Damage/Die). A hit
		// on a plate goes to the plate's own TakeDamage, not the pawn's, so
		// the mod never shared it: the client broke the plates of its own
		// copy only, the host's stayed whole - and the two games drove one
		// enemy in two different states (frozen, broken animation, no way
		// to kill it, 26.10). Each game now watches every plate of every
		// shared enemy; a plate that loses HP or dies here is sent (kind
		// 41: entityKey, damage=plate index, health=HP, flags=state), and
		// the other game takes the lower HP and kills a dead plate through
		// the pawn's own KillNPCAttachedActor, so its AI and animation go
		// the same way the game would.
		constexpr SharedWorldEventKind kEventEnemyArmour =
			static_cast<SharedWorldEventKind>(41);
		struct ArmourPlateState
		{
			int hp = -1;
			int state = -1;
		};
		std::unordered_map<std::uint64_t, std::vector<ArmourPlateState>> g_armourSeen;
		const void* g_armourWorld = nullptr;

		std::uint64_t SharedKeyForEnemy(AAliceGameKynapsePawn* enemy, std::uint64_t localKey)
		{
			if (g_config.role == Role::Client)
			{
				const auto alias = g_clientEnemyHostKeyByActor.find(enemy);
				if (alias != g_clientEnemyHostKeyByActor.end())
					return alias->second;
			}
			return localKey;
		}

		AAliceGameKynapsePawn* EnemyForSharedKey(std::uint64_t key)
		{
			if (g_config.role == Role::Client)
			{
				for (const auto& [actor, hostKey] : g_clientEnemyHostKeyByActor)
				{
					if (hostKey == key && actor && IsLiveUObject(actor))
						return const_cast<AAliceGameKynapsePawn*>(actor);
				}
				if (AAliceGameKynapsePawn* const dead = DeadCopyForHostKey(key))
					return dead;
			}
			const auto found = g_sharedEnemyRegistry.find(key);
			const char* miss = nullptr;
			if (found == g_sharedEnemyRegistry.end() || !found->second)
				miss = "not in the registry";
			else
			{
				AAliceGameKynapsePawn* const enemy = found->second;
				if (!IsLiveUObject(enemy) || !enemy->IsA(AAliceGameKynapsePawn::StaticClass()))
					miss = "registry entry not live";
				else if (enemy->WorldInfo != g_currentWorld)
					miss = "registry entry in another world";
				else
					return enemy;
			}
			// enemykey1 (10.11 19:27:32-40, host: seven plate hits of the client's
			// Colossal Ruin were dropped as "enemy not here" while that Ruin was
			// alive and following the client's poses - the host's copy kept
			// all its plates, so each game fought its own Ruin). A miss is
			// looked up once more among all enemies (at most every 2 s per key).
			static std::unordered_map<std::uint64_t, Clock::time_point> lastScan;
			static std::unordered_map<std::uint64_t, AAliceGameKynapsePawn*> scanned;
			const auto now = Clock::now();
			auto cachedHit = scanned.find(key);
			if (cachedHit != scanned.end() && cachedHit->second && IsLiveUObject(cachedHit->second)
				&& cachedHit->second->WorldInfo == g_currentWorld && !cachedHit->second->bDeleteMe)
			{
				return cachedHit->second;
			}
			auto& last = lastScan[key];
			if (last != Clock::time_point{} && now - last < std::chrono::seconds(2))
				return nullptr;
			last = now;
			AAliceGameKynapsePawn* hit = nullptr;
			if (TArray<UObject*>* const objects = UObject::GObjObjects())
			{
				for (int32_t index = 0; index < objects->size() && !hit; ++index)
				{
					UObject* const object = objects->at(index);
					if (!object || object->IsDefaultObject() || !IsUsableObjectFast(object)
						|| !object->IsA(AAliceGameKynapsePawn::StaticClass()))
					{
						continue;
					}
					auto* const candidate = reinterpret_cast<AAliceGameKynapsePawn*>(object);
					if (candidate->WorldInfo != g_currentWorld || candidate->bDeleteMe)
						continue;
					if (SharedKeyForEnemy(candidate, SharedEnemyStableKey(candidate)) == key)
						hit = candidate;
				}
			}
			static int logsLeft = 30;
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("ENEMYKEY key=" + SharedWorldKeyText(key) + " " + miss + "; scan "
					+ (hit ? "found " + ObjectName(hit) : std::string("found nothing")) + '.');
			}
			if (hit)
				scanned[key] = hit;
			return hit;
		}

		// platedead1 (10.11 22:03:12 / 22:04:02): small head 2 of the Colossal
		// Ruin died on the host while the client drove it; when the host took
		// the Ruin back its AI (which never saw that death) woke the plate
		// again with full HP. After the stun dead heads showed up again too.
		// A small plate that died in either game stays dead in both: it is
		// killed again (the native death path) if it comes back, and hidden
		// if it shows.
		struct DeadPlates
		{
			AAliceGameKynapsePawn* enemy = nullptr;
			std::uint32_t mask = 0;
			Clock::time_point at[16]{};
			Clock::time_point lastFix[16]{};
		};
		std::unordered_map<std::uint64_t, DeadPlates> g_deadPlates;

		void MarkPlateDead(std::uint64_t key, AAliceGameKynapsePawn* enemy, int index, const char* why)
		{
			if (!enemy || index < 0 || index >= 16)
				return;
			static UClass* const tankClass = AAliceGameDoomTankPawn::StaticClass();
			if (!tankClass || !enemy->IsA(tankClass))
				return;
			DeadPlates& dead = g_deadPlates[key];
			if (dead.enemy != enemy)
				dead = DeadPlates{ enemy };
			if (dead.mask & (1u << index))
				return;
			dead.mask |= 1u << index;
			dead.at[index] = Clock::now();
			static int logsLeft = 40;
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("PLATEDEAD " + ObjectName(enemy) + " plate " + std::to_string(index)
					+ " is dead for good (" + why + ") (platedead1).");
			}
		}

		void TickSharedEnemyArmour()
		{
			if (!g_config.enabled || !g_config.sharedEnemyHealth
				|| g_config.localMirror || !g_connected || WorldTransitionActive())
			{
				return;
			}
			static Clock::time_point nextPass{};
			const auto now = Clock::now();
			if (now < nextPass)
				return;
			nextPass = now + std::chrono::milliseconds(100);
			if (g_armourWorld != g_currentWorld)
			{
				g_armourWorld = g_currentWorld;
				g_armourSeen.clear();
				g_deadPlates.clear(); // platedead1
			}
			static int logsLeft = 80;
			for (const auto& [localKey, enemy] : g_sharedEnemyRegistry)
			{
				if (!enemy || !IsLiveUObject(enemy) || enemy->bDeleteMe)
					continue;
				const int32_t count = (std::min)(enemy->NPCAttachedActors.size(), 16);
				if (count <= 0)
					continue;
				const std::uint64_t key = SharedKeyForEnemy(enemy, localKey);
				auto& seen = g_armourSeen[key];
				const bool first = seen.empty();
				if (static_cast<int32_t>(seen.size()) < count)
					seen.resize(count);
				// platewake1 (10.11 20:15:13, Colossal Ruin in its rage stage,
				// driven by the host): the teapot stun made the Ruin bring out
				// its head (plate 6, 225 HP) - on the client's copy plates 5 and
				// 6 never existed ("plate gone here"): the copy's paused AI never
				// woke them, so the other player had no head to hit. The game
				// that drives the enemy sends which plates are out (awake) and
				// the other game wakes / puts away the same ones.
				const bool drivesHere = LocallyDrivesSharedEnemy(key);
				for (int32_t index = 0; drivesHere && index < count; ++index)
				{
					AAliceGameNPCAttachedActor* const plate =
						enemy->NPCAttachedActors.at(index).AttachedActor;
					const auto deadIt = g_deadPlates.find(key);
					const bool knownDead = deadIt != g_deadPlates.end() && deadIt->second.enemy == enemy
						&& index < 16 && (deadIt->second.mask & (1u << index)) != 0; // platedead1
					const bool out = plate && IsLiveUObject(plate) && plate->bIsAwake && !knownDead
						&& plate->ActorState != ENPCAttachedActorState::ENPCAAS_Die;
					const bool plateDied = plate && IsLiveUObject(plate)
						&& (knownDead || plate->ActorState == ENPCAttachedActorState::ENPCAAS_Die);
					// headwake1 (10.11 21:40:57, the stun head of the Colossal
					// Ruin): the copy's head was woken (awake=1, its hits
					// replayed) but stayed invisible - the driver's game also
					// un-hides the plate (HideNPCAttachedActor), which the wake
					// alone never did. The plate's hidden state goes along.
					const bool plateHidden = plate && IsLiveUObject(plate)
						&& (plate->bHidden
							|| (plate->SkeletalMeshComponent && plate->SkeletalMeshComponent->HiddenGame));
					const std::uint64_t slot = key ^ (0x77AA000000000000ull + static_cast<std::uint64_t>(index));
					static std::unordered_map<std::uint64_t, std::pair<int, Clock::time_point>> sentOut;
					auto& sent = sentOut[slot];
					const int wanted = out ? (plateHidden ? 3 : 1) : 0;
					if (sent.first == wanted
						&& (!out || now - sent.second < std::chrono::seconds(2)))
					{
						continue;
					}
					if (sent.first <= 0 && !out)
					{
						sent.first = 0; // nothing to tell before a plate was ever out
						continue;
					}
					sent = { wanted, now };
					SharedWorldEventPayload wake{};
					wake.kind = static_cast<SharedWorldEventKind>(69);
					wake.entityKey = key;
					wake.originActorId = g_config.role == Role::Host ? 1u : 2u;
					wake.damage = index;
					wake.health = out ? plate->HP : 0;
					wake.healthMax = out ? plate->FullHP : 0;
					wake.flags = static_cast<std::uint8_t>((out ? 1u : 0u) | (plateDied ? 2u : 0u)
						| (out && plateHidden ? 4u : 0u) | 8u); // 8: hidden state is sent (headwake1)
					QueueSharedWorldEvent(wake);
				}
				// plateanim1 (10.11, UE Explorer AliceGameNPCAttachedActor): a
				// plate plays its own animations on its Slot_FullBody_Main
				// (PlayConfigAnim) - the mortar tubes of the Colossal Ruin's
				// shell rain, the plates' hit / death moves - and their notifies
				// make the plate's particles. The copy's plates played none of it.
				// The driver sends each plate's slot animation; the copy's plate
				// plays it (its notifies then make the same particles there).
				for (int32_t index = 0; drivesHere && index < count; ++index)
				{
					AAliceGameNPCAttachedActor* const plate =
						enemy->NPCAttachedActors.at(index).AttachedActor;
					if (!plate || !IsLiveUObject(plate) || plate->AnimBlendNodes.size() <= 0)
						continue;
					UAliceGameAnimNode_BlendBase* const node = plate->AnimBlendNodes.at(0);
					if (!node || !IsUsableObjectFast(node))
						continue;
					UAnimNodeSequence* const sequence =
						node->bIsPlayingCustomAnim ? CustomSequenceOf(node) : nullptr;
					struct PlateAnimSent { std::uint32_t hash = 0; float time = 0.0f; };
					static std::unordered_map<std::uint64_t, PlateAnimSent> plateSent;
					auto& last = plateSent[key ^ (0x5A1E000000000000ull + static_cast<std::uint64_t>(index))];
					if (!sequence || !sequence->AnimSeq)
					{
						last.hash = 0;
						continue;
					}
					const std::string animName = sequence->AnimSeqName.ToString();
					const std::uint32_t hash = TunnelNameHash(animName.c_str(), animName.size());
					const bool restarted = last.hash == hash && sequence->CurrentTime + 0.05f < last.time;
					last.time = sequence->CurrentTime;
					if (last.hash == hash && !restarted)
						continue;
					last.hash = hash;
					SharedWorldEventPayload anim{};
					anim.kind = static_cast<SharedWorldEventKind>(70);
					anim.entityKey = key;
					anim.originActorId = g_config.role == Role::Host ? 1u : 2u;
					anim.damage = index;
					anim.health = static_cast<std::int32_t>(hash);
					anim.healthMax = static_cast<std::int32_t>(std::lround(sequence->Rate * 1000.0f));
					anim.flags = static_cast<std::uint8_t>(sequence->bLooping ? 1u : 0u);
					anim.hitLocation[0] = sequence->CurrentTime;
					QueueSharedWorldEvent(anim);
				}
				for (int32_t index = 0; index < count; ++index)
				{
					AAliceGameNPCAttachedActor* const plate =
						enemy->NPCAttachedActors.at(index).AttachedActor;
					if (!plate || !IsLiveUObject(plate))
						continue;
					const int hp = plate->HP;
					const int state = static_cast<int>(plate->ActorState);
					ArmourPlateState& last = seen[index];
					if (first || last.state < 0)
					{
						last.hp = hp;
						last.state = state;
						if (logsLeft > 0)
						{
							--logsLeft;
							Log("ENEMYARMOUR " + ObjectName(enemy) + " plate " + std::to_string(index)
								+ " " + ObjectName(plate) + ": hp=" + std::to_string(hp) + '/'
								+ std::to_string(plate->FullHP) + " state=" + std::to_string(state)
								+ " awake=" + (plate->bIsAwake ? "1" : "0") + '.');
						}
						continue;
					}
					const bool lostHp = hp < last.hp;
					const bool died = state == static_cast<int>(ENPCAttachedActorState::ENPCAAS_Die)
						&& last.state != state;
					// v2: the state is only logged now. Sending it and forcing it
					// on the other copy (HP 0, KillNPCAttachedActor) left the
					// host's plate at HP 0 but alive - the Ruin immortal and
					// frozen (26.10 11:09: "killed here (state now 0)"). The
					// hits themselves are replayed instead (kind 43).
					if ((lostHp || died) && false)
					{
						SharedWorldEventPayload event{};
						event.kind = kEventEnemyArmour;
						event.entityKey = key;
						event.originActorId = g_config.role == Role::Host ? 1u : 2u;
						event.damage = index;
						event.health = hp;
						event.healthMax = plate->FullHP;
						event.flags = static_cast<std::uint8_t>(state);
						QueueSharedWorldEvent(event);
						if (logsLeft > 0)
						{
							--logsLeft;
							Log("ENEMYARMOUR TX " + ObjectName(enemy) + " plate " + std::to_string(index)
								+ ": hp " + std::to_string(last.hp) + "->" + std::to_string(hp)
								+ ", state " + std::to_string(last.state) + "->" + std::to_string(state) + '.');
						}
					}
					if ((lostHp || died) && logsLeft > 0)
					{
						--logsLeft;
						Log("ENEMYARMOUR " + ObjectName(enemy) + " plate " + std::to_string(index)
							+ ": hp " + std::to_string(last.hp) + "->" + std::to_string(hp)
							+ ", state " + std::to_string(last.state) + "->" + std::to_string(state) + '.');
					}
					last.hp = hp;
					last.state = state;
					if (plate->ActorState == ENPCAttachedActorState::ENPCAAS_Die && plate->FullHP > 0
						&& plate->FullHP <= 100)
					{
						MarkPlateDead(key, enemy, index, "died here"); // platedead1
					}
				}
				EnforceDeadPlates(key, enemy); // platedead1
				// locktarget1 (10.11 22:04:27, Colossal Ruin stunned while the
				// client drove it): the host could not lock on to it - the
				// driver's AI opens the lock-on sockets (LockTargetsSet, the
				// head while stunned), the copy's paused AI never did. The
				// driver sends which sockets are enabled / critical.
				if (drivesHere)
				{
					const auto& sockets = enemy->LockOnInfo.TargetSockets;
					const int32_t socketCount = (std::min)(sockets.size(), 31);
					std::int32_t enabled = 0;
					std::int32_t critical = 0;
					for (int32_t i = 0; i < socketCount; ++i)
					{
						if (sockets.at(i).bEnable)
							enabled |= 1 << i;
						if (sockets.at(i).bCriticalUI)
							critical |= 1 << i;
					}
					struct LockSent { std::int32_t enabled = -1; std::int32_t critical = -1; Clock::time_point at{}; };
					static std::unordered_map<std::uint64_t, LockSent> lockSent;
					LockSent& sentLock = lockSent[key];
					if (socketCount > 0 && (sentLock.enabled != enabled || sentLock.critical != critical
						|| now - sentLock.at > std::chrono::seconds(2)))
					{
						sentLock = { enabled, critical, now };
						SharedWorldEventPayload lockEvent{};
						lockEvent.kind = static_cast<SharedWorldEventKind>(71);
						lockEvent.entityKey = key;
						lockEvent.originActorId = g_config.role == Role::Host ? 1u : 2u;
						lockEvent.damage = enabled;
						lockEvent.health = critical;
						lockEvent.healthMax = socketCount;
						QueueSharedWorldEvent(lockEvent);
					}
				}
			}
		}

		// ---- HITPROBE: why the other Alice's copy of an enemy cannot be hit --
		// 26.10 logs: every Alice hit lands only on the copy whose AI runs on
		// her own machine. A copy driven from the other game (host: controller
		// paused, client: pawn paused, both: Enemy/Focus pointed at the other
		// Alice) never even gets the weapon's PlayPhysicalMaterialEffect -
		// the swing passes through it, so it is "immortal" for her. Dump,
		// for the enemy nearest to this Alice, what differs between a driven
		// and a not-driven copy, and what CanMeleeAttackActor answers with
		// each of those differences undone for one call.
		AAlicePawn* g_hitProbeLocalPawn = nullptr;
		AActor* g_hitProbeLocalWeapon = nullptr;
		Clock::time_point g_hitProbeWindowUntil{};
		int g_hitProbeEventLogsLeft = 160;
		bool g_hitProbeQuerying = false; // our own calls below are not the game's

		std::uint64_t HitProbeEnemyKey(AAliceGameKynapsePawn* enemy)
		{
			if (!enemy)
				return 0;
			if (g_config.role == Role::Client)
			{
				const auto alias = g_clientEnemyHostKeyByActor.find(enemy);
				if (alias != g_clientEnemyHostKeyByActor.end())
					return alias->second;
			}
			return SharedEnemyStableKey(enemy);
		}

		void HitProbeObserveProcessEvent(UObject* object, UFunction* function)
		{
			if (g_hitProbeQuerying || g_hitProbeEventLogsLeft <= 0 || !object || !function
				|| !g_hitProbeLocalPawn || !g_hitProbeLocalWeapon)
			{
				return;
			}
			static std::unordered_set<std::string> seen;
			const auto now = Clock::now();
			if (object == g_hitProbeLocalWeapon)
			{
				const std::string name = function->GetName();
				if (name.find("Fire") != std::string::npos
					|| name.find("Melee") != std::string::npos
					|| name.find("Combo") != std::string::npos
					|| name.find("Attack") != std::string::npos
					|| name.find("Hit") != std::string::npos)
				{
					g_hitProbeWindowUntil = now + std::chrono::milliseconds(1500);
				}
				if (seen.size() < 600 && seen.insert("W:" + name).second)
				{
					--g_hitProbeEventLogsLeft;
					Log("HITPROBE weapon event " + ObjectName(function) + '.');
				}
				return;
			}
			if (now >= g_hitProbeWindowUntil)
				return;
			AAliceGameKynapsePawn* enemy = nullptr;
			const bool onPawn = object->IsA(AAliceGameKynapsePawn::StaticClass());
			if (onPawn)
				enemy = reinterpret_cast<AAliceGameKynapsePawn*>(object);
			else if (object->IsA(AAliceGameKynapseAIController::StaticClass()))
			{
				APawn* const pawn = reinterpret_cast<AController*>(object)->Pawn;
				if (pawn && pawn->IsA(AAliceGameKynapsePawn::StaticClass()))
					enemy = reinterpret_cast<AAliceGameKynapsePawn*>(pawn);
			}
			if (!enemy || (enemy->Location - g_hitProbeLocalPawn->Location)
				.SizeSquared() > 900.0f * 900.0f)
			{
				return;
			}
			const std::uint64_t key = HitProbeEnemyKey(enemy);
			const bool driven = key != 0 && LocallyDrivesSharedEnemy(key);
			const std::string tag = std::string(driven ? "D:" : "N:")
				+ (onPawn ? "pawn." : "ctrl.") + function->GetName();
			if (seen.size() < 600 && seen.insert(tag).second)
			{
				--g_hitProbeEventLogsLeft;
				Log(std::string("HITPROBE ") + (driven ? "driven" : "NOT-driven")
					+ " enemy " + ObjectName(enemy) + " got "
					+ (onPawn ? "pawn " : "controller ") + ObjectName(function)
					+ " during an attack.");
			}
		}

		void TickHitProbe()
		{
			g_hitProbeLocalPawn = nullptr;
			g_hitProbeLocalWeapon = nullptr;
			if (!g_config.enabled || g_config.localMirror || !g_connected
				|| !g_config.sharedEnemyTransforms || WorldTransitionActive())
			{
				return;
			}
			AAlicePawn* const localPawn = GetLocalPawn();
			if (!localPawn || !IsLiveUObject(localPawn) || localPawn->Health <= 0)
				return;
			g_hitProbeLocalPawn = localPawn;
			g_hitProbeLocalWeapon = localPawn->Weapon && IsLiveUObject(localPawn->Weapon)
				? localPawn->Weapon : nullptr;

			// Once per weapon class: the slots Ghidra needs for Alice's own
			// weapon (the NPC ones are in MELEEVTABLE already).
			if (g_hitProbeLocalWeapon && g_hitProbeLocalWeapon->Class)
			{
				static std::unordered_set<const void*> loggedClasses;
				if (loggedClasses.size() < 12
					&& loggedClasses.insert(g_hitProbeLocalWeapon->Class).second)
				{
					const uintptr_t moduleBase =
						reinterpret_cast<uintptr_t>(GetModuleHandleW(nullptr));
					const auto* const vtable =
						*reinterpret_cast<const uintptr_t* const*>(g_hitProbeLocalWeapon);
					if (IsReadableRange(vtable, 0x470))
					{
						const auto exe = [moduleBase](uintptr_t address)
						{
							std::ostringstream stream;
							stream << "0x" << std::hex
								<< (address - moduleBase + 0x400000);
							return stream.str();
						};
						Log("MELEEVTABLE alice weapon class "
							+ ObjectName(g_hitProbeLocalWeapon->Class)
							+ ": vtable=" + exe(reinterpret_cast<uintptr_t>(vtable))
							+ ", CanMeleeAttackActor [+0x414]=" + exe(vtable[0x414 / 4])
							+ ", [+0x410]=" + exe(vtable[0x410 / 4])
							+ ", [+0x418]=" + exe(vtable[0x418 / 4])
							+ ", weapon check [+0x45c]=" + exe(vtable[0x45c / 4])
							+ ", build=" + std::to_string(static_cast<int>(
								Addresses::GetBuild())) + '.');
					}
				}
			}

			static Clock::time_point nextPass{};
			const auto now = Clock::now();
			if (now < nextPass)
				return;
			nextPass = now + std::chrono::milliseconds(400);
			static int snapshotLogsLeft = 90;
			if (snapshotLogsLeft <= 0)
				return;

			AAliceGameKynapsePawn* nearest = nullptr;
			std::uint64_t nearestKey = 0;
			float bestDistanceSquared = 700.0f * 700.0f;
			for (const auto& [localKey, enemy] : g_sharedEnemyRegistry)
			{
				if (!enemy || !IsLiveUObject(enemy) || enemy->Health <= 0
					|| enemy->bDeleteMe || enemy->bPendingDelete
					|| enemy->WorldInfo != g_currentWorld)
				{
					continue;
				}
				const float distanceSquared =
					(enemy->Location - localPawn->Location).SizeSquared();
				if (distanceSquared < bestDistanceSquared)
				{
					bestDistanceSquared = distanceSquared;
					nearest = enemy;
					nearestKey = HitProbeEnemyKey(enemy);
				}
			}
			if (!nearest || !nearestKey)
				return;
			const bool driven = LocallyDrivesSharedEnemy(nearestKey);
			AController* const controller =
				nearest->Controller && IsLiveUObject(nearest->Controller)
					? nearest->Controller : nullptr;
			const bool kynapse = controller
				&& controller->IsA(AAliceGameKynapseAIController::StaticClass());
			auto* const aiController = kynapse
				? reinterpret_cast<AAliceGameKynapseAIController*>(controller) : nullptr;

			g_hitProbeQuerying = true;
			const int brainState = KynapseBrainState(controller);
			const std::string stateName = controller
				? controller->GetStateName().ToString() : std::string("-");
			// No CanMeleeAttackActor query any more: FUN_00c54ba0 ends in the
			// weapon's MeleeAttackActorList (+0x130), which REGISTERS the target
			// as already hit this swing - the 29.10 probe answered 1, 0, 1, 0
			// and Alice's real swings then skipped the enemy it had "asked
			// about" (nobody could break the Ruin's armour in that test).
			int shieldMask = 0;
			for (int32_t index = 0; index < (std::min)(nearest->ShieldComponentsArray.size(), 8); ++index)
			{
				if (nearest->ShieldComponentsArray.at(index).bInShield)
					shieldMask |= 1 << index;
			}
			g_hitProbeQuerying = false;

			int socketsEnabled = 0;
			for (int32_t index = 0; index < nearest->LockOnInfo.TargetSockets.size(); ++index)
			{
				if (nearest->LockOnInfo.TargetSockets.at(index).bEnable)
					++socketsEnabled;
			}
			const auto primitive = [](const UPrimitiveComponent* component)
			{
				if (!component)
					return std::string("<none>");
				return std::string("{c") + (component->CollideActors ? "1" : "0")
					+ " b" + (component->BlockActors ? "1" : "0")
					+ " z" + (component->BlockZeroExtent ? "1" : "0")
					+ " nz" + (component->BlockNonZeroExtent ? "1" : "0")
					+ " rb" + (component->BlockRigidBody ? "1" : "0")
					+ " h" + (component->HiddenGame ? "1" : "0") + '}';
			};
			const auto name = [](const UObject* object)
			{
				return object ? ObjectName(object) : std::string("<null>");
			};
			const std::string signature = std::to_string(nearestKey)
				+ (driven ? "D" : "N") + std::to_string(shieldMask)
				+ (nearest->bPauseTick ? "p" : "-")
				+ (aiController && aiController->bPauseTick ? "c" : "-")
				+ (controller && controller->Enemy == localPawn ? "e" : "-")
				+ std::to_string(brainState)
				+ std::to_string(static_cast<int>(nearest->NPCState))
				+ std::to_string(static_cast<int>(nearest->AIState))
				+ std::to_string(socketsEnabled)
				+ (nearest->bCollideActors ? "C" : "-")
				+ (nearest->bCanBeDamaged ? "d" : "-");
			static std::unordered_map<std::uint64_t, std::string> lastSignature;
			if (lastSignature[nearestKey] == signature)
				return;
			lastSignature[nearestKey] = signature;
			--snapshotLogsLeft;
			Log("HITPROBE nearest " + ObjectName(nearest) + " key="
				+ SharedWorldKeyText(nearestKey) + " dist="
				+ std::to_string(static_cast<int>(std::sqrt(bestDistanceSquared)))
				+ (driven ? " DRIVEN here" : " NOT driven here")
				+ ": inShield=0x" + std::to_string(shieldMask)
				+ " shields=" + std::to_string(nearest->ShieldComponentsArray.size())
				+ " weapon=" + name(g_hitProbeLocalWeapon)
				+ " pawnPause=" + (nearest->bPauseTick ? "1" : "0")
				+ " ctrlPause=" + (aiController && aiController->bPauseTick ? "1" : "0")
				+ " brain=" + std::to_string(brainState)
				+ " state=" + stateName
				+ " god=" + (controller && controller->bGodMode ? "1" : "0")
				+ " enemyPtr=" + name(controller ? controller->Enemy : nullptr)
				+ " npcState=" + std::to_string(static_cast<int>(nearest->NPCState))
				+ " aiState=" + std::to_string(static_cast<int>(nearest->AIState))
				+ " healthState=" + std::to_string(static_cast<int>(nearest->HealthState))
				+ " fighting=" + (nearest->bIsFighting ? "1" : "0")
				+ " physics=" + std::to_string(static_cast<int>(nearest->Physics))
				+ " canBeDamaged=" + (nearest->bCanBeDamaged ? "1" : "0")
				+ " collide=" + (nearest->bCollideActors ? "1" : "0")
				+ " block=" + (nearest->bBlockActors ? "1" : "0")
				+ " projTarget=" + (nearest->bProjTarget ? "1" : "0")
				+ " hidden=" + (nearest->bHidden ? "1" : "0")
				+ " cyl=" + primitive(nearest->CollisionComponent)
				+ " mesh=" + primitive(nearest->Mesh)
				+ " lockSockets=" + std::to_string(socketsEnabled) + '/'
				+ std::to_string(nearest->LockOnInfo.TargetSockets.size())
				+ " health=" + std::to_string(nearest->Health) + '.');
		}

		// ---- ENEMYREC: what enemies really do (single player reference) -----
		// [Debug] EnemyRecord=1 writes AliceCoop_enemyrec_<map>_<pid>.log next
		// to the normal log: for every enemy near this Alice a timeline of
		//  - the script events/functions the engine calls on the enemy, its AI
		//    controller, its armour plates and its projectiles (with the
		//    parameters of the important ones: damage, shield hits);
		//  - its state whenever it changes (custom animations on its blend
		//    nodes and the dominant animation, AI state, brain, target,
		//    NPC/AI/health state, fighting, shields, plates, health);
		//  - its shots (class, trace, destination, target, flight) and their
		//    course changes (deflections);
		//  - this Alice's weapon events and her own state (special move,
		//    deflect/umbrella, weapon, health).
		// Works without a second player. Recorded once in single player and
		// once in co-op (both copies), the two show what co-op leaves out.
		UAnimNodeSequence* FindDominantOneShotSequence(USkeletalMeshComponent* component);
		std::wstring g_enemyRecDirectory;
		std::ofstream g_enemyRec;
		std::string g_enemyRecMap;
		bool g_enemyRecQuerying = false;
		Clock::time_point g_enemyRecStart{};
		struct EnemyRecShot
		{
			AActor* actor = nullptr;
			FVector lastVelocity{};
			bool described = false;
			Clock::time_point since{};
		};
		std::unordered_map<const void*, EnemyRecShot> g_enemyRecShots;
		std::unordered_map<const void*, std::string> g_enemyRecLastState;
		std::string g_enemyRecLastAlice;

		void EnemyRecWrite(const std::string& line)
		{
			if (!g_enemyRec.is_open())
				return;
			const double seconds = std::chrono::duration<double>(
				Clock::now() - g_enemyRecStart).count();
			char stamp[32];
			sprintf_s(stamp, "%9.3f", seconds);
			g_enemyRec << '[' << Timestamp() << " +" << stamp << "] " << line << '\n';
		}

		void EnemyRecOpenForMap()
		{
			if (g_enemyRecMap == g_currentMap && g_enemyRec.is_open())
				return;
			if (g_enemyRec.is_open())
			{
				EnemyRecWrite("---- map left");
				g_enemyRec.close();
			}
			g_enemyRecMap = g_currentMap;
			g_enemyRecShots.clear();
			g_enemyRecLastState.clear();
			g_enemyRecLastAlice.clear();
			if (g_currentMap.empty() || g_enemyRecDirectory.empty()
				|| _stricmp(g_currentMap.c_str(), "AliceEntry") == 0)
			{
				return;
			}
			std::wstring map(g_currentMap.begin(), g_currentMap.end());
			const std::filesystem::path path = std::filesystem::path(g_enemyRecDirectory)
				/ (L"AliceCoop_enemyrec_" + map + L"_"
					+ std::to_wstring(GetCurrentProcessId()) + L".log");
			g_enemyRec.open(path, std::ios::app);
			g_enemyRecStart = Clock::now();
			EnemyRecWrite("---- map " + g_currentMap + ", role "
				+ (g_connected ? (g_config.role == Role::Host ? "host" : "client")
					: std::string("single player")) + ", build "
				+ std::to_string(static_cast<int>(Addresses::GetBuild())));
			Log("ENEMYREC recording enemies of " + g_currentMap + " to "
				+ path.filename().string() + '.');
		}

		bool EnemyRecNoise(const std::string& name)
		{
			static const std::unordered_set<std::string> noise = {
				"Tick", "GetHeadLookTargetLocation", "ModifyHearSoundComponent",
				"HearNoise", "FastTrace", "LineOfSightTo", "GetStateName",
				"GetBrainState", "PlayFootStepWaterEffect", "PlayFootStepSound",
				"CalcCamera", "IsDoingDeflectSpinning", "IsDeflecting",
				"EffectIsRelevant", "GetHomingTarget", "GetWeaponLevel",
				"GetDLCWeaponFlag", "IsEnableWeaponEnviorCollision",
				"GetWeaponLeveDateTrails", "GetWeaponLeveDateEffect",
				"SetLocationNoCheck", "SetRotation", "BaseChange",
				"ActiveAIEventTrigger", "IsFiring", "eventIsFiring" };
			return noise.count(name) != 0;
		}

		std::string EnemyRecName(const UObject* object)
		{
			if (!object)
				return "<null>";
			// recname1 (10.11 02:22:29 host crash, chapter 5 after a level
			// restart: "SHOT gone" named a projectile that was already freed -
			// FName::ToString read 0xFF016A3C). A dead object is never named.
			if (!IsLiveUObject(object))
			{
				char text[32];
				std::snprintf(text, sizeof(text), "<gone %p>", static_cast<const void*>(object));
				return text;
			}
			std::string name = ObjectName(object);
			const std::string level = "TheWorld.PersistentLevel.";
			const auto at = name.find(level);
			const auto space = name.find(' ');
			if (at != std::string::npos && space != std::string::npos && space < at)
				name.erase(space + 1, at + level.size() - space - 1);
			return name;
		}

		// Parameters of the events worth reading.
		std::string EnemyRecParameters(const std::string& name, const void* parameters)
		{
			if (!parameters)
				return std::string();
			if (name == "TakeDamage" || name == "ShieldDamage")
			{
				const auto* value = reinterpret_cast<const APawn_eventShieldDamage_Params*>(parameters);
				return " damage=" + std::to_string(value->Damage)
					+ " by=" + EnemyRecName(value->InstigatedBy ? value->InstigatedBy->Pawn : nullptr)
					+ " type=" + EnemyRecName(value->DamageType)
					+ " causer=" + EnemyRecName(value->DamageCauser);
			}
			if (name == "PlayShieldPhysicsMaterialEffect")
			{
				const auto* value = reinterpret_cast<const
					AAliceGameWeaponBase_eventPlayShieldPhysicsMaterialEffect_Params*>(parameters);
				return " target=" + EnemyRecName(value->TargetPawn)
					+ " shield=" + std::to_string(value->ShieldResult.ShieldIndex)
					+ (value->ShieldResult.bSpinningShield ? " spinning" : "");
			}
			if (name == "PlayPhysicalMaterialEffect")
			{
				const auto* value = reinterpret_cast<const
					AAliceGameWeaponBase_eventPlayPhysicalMaterialEffect_Params*>(parameters);
				return " target=" + EnemyRecName(value->TargetPawn)
					+ " body=" + EnemyRecName(value->CollisionResult.HitBodySetUp)
					+ (value->bRadiusAttack ? " radius" : "");
			}
			return std::string();
		}

		// ProcessEvent hook (before).
		void EnemyRecObserveProcessEvent(UObject* object, UFunction* function, const void* parameters)
		{
			if (!g_config.enemyRecord || g_enemyRecQuerying || !g_enemyRec.is_open()
				|| !object || !function)
			{
				return;
			}
			// enemyrecsafe1 (31.10 22:59:30): events fired while a world is
			// torn down (the engine's garbage collection) reached here with
			// objects already freed. Nothing is recorded around a teardown.
			if (LeavingWorld() || WorldTransitionActive() || !IsUsableObjectFast(object))
				return;
			AAlicePawn* const localPawn = GetLocalPawn();
			if (!localPawn || !IsReadableRange(localPawn, sizeof(AAlicePawn))
				|| !IsUsableObjectFast(localPawn))
			{
				return;
			}
			const char* kind = nullptr;
			AActor* anchor = nullptr;
			if (object->IsA(AAliceGameKynapsePawn::StaticClass()))
			{
				kind = "enemy";
				anchor = reinterpret_cast<AActor*>(object);
			}
			else if (object->IsA(AAliceGameKynapseAIController::StaticClass()))
			{
				kind = "ai";
				anchor = reinterpret_cast<AController*>(object)->Pawn;
			}
			else if (object->IsA(AAliceGameNPCAttachedActor::StaticClass()))
			{
				kind = "plate";
				anchor = reinterpret_cast<AActor*>(object);
			}
			else if (object->IsA(ANpcProjectile::StaticClass()))
			{
				kind = "shot";
				anchor = reinterpret_cast<AActor*>(object);
			}
			else if (object->IsA(AAliceGameWeaponBase::StaticClass()))
			{
				auto* const weapon = reinterpret_cast<AActor*>(object);
				if (weapon->Instigator == localPawn || weapon->Owner == localPawn)
					kind = "alice-weapon";
				else if (weapon->Instigator
					&& weapon->Instigator->IsA(AAliceGameKynapsePawn::StaticClass()))
				{
					kind = "enemy-weapon";
					anchor = weapon->Instigator;
				}
				else
					return;
			}
			else if (object == localPawn)
				kind = "alice";
			// grabcam1: the controller's grab / camera calls too (Colossal
			// Ruin reference recording)
			else if (object == g_State.AlicePlayerController)
				kind = "alice-pc";
			else
				return;
			if (anchor && (anchor->Location - localPawn->Location).SizeSquared()
				> 4000.0f * 4000.0f)
			{
				return;
			}
			const std::string name = function->GetName();
			if (EnemyRecNoise(name))
				return;
			const bool grabOrCamera = name.find("Grab") != std::string::npos
				|| name.find("Camera") != std::string::npos
				|| name.find("ViewTarget") != std::string::npos
				|| name.find("FOV") != std::string::npos
				|| name.find("CameraAnim") != std::string::npos
				|| name.find("SpecialMove") != std::string::npos
				|| name.find("BeginState") != std::string::npos
				|| name.find("EndState") != std::string::npos
				|| name.find("GotoState") != std::string::npos;
			if (std::strcmp(kind, "alice-pc") == 0 && !grabOrCamera)
				return;
			if (std::strcmp(kind, "alice") == 0 && name != "TakeDamage"
				&& !grabOrCamera // grabcam1
				&& name.find("Deflect") == std::string::npos
				&& name.find("Umbrella") == std::string::npos
				&& name.find("Shield") == std::string::npos
				&& name.find("React") == std::string::npos
				&& name.find("KnockBack") == std::string::npos)
			{
				return; // her own movement/animation events are another log
			}
			// The same call on the same object again within 250 ms: counted.
			static std::unordered_map<std::string, std::pair<Clock::time_point, int>> recent;
			if (recent.size() > 4096)
				recent.clear();
			const auto now = Clock::now();
			char key[32];
			sprintf_s(key, "%p", static_cast<const void*>(object));
			auto& last = recent[std::string(key) + name];
			if (last.first != Clock::time_point{}
				&& now - last.first < std::chrono::milliseconds(250))
			{
				++last.second;
				return;
			}
			const int repeated = last.second;
			last = { now, 0 };
			std::string line = std::string("EVENT ") + kind + ' ' + EnemyRecName(object)
				+ " <- " + ObjectName(function) + EnemyRecParameters(name, parameters);
			if (repeated > 0)
				line += " (and " + std::to_string(repeated) + "x before)";
			EnemyRecWrite(line);
			if (std::strcmp(kind, "shot") == 0 && name == "PostBeginPlay")
			{
				EnemyRecShot shot{};
				shot.actor = reinterpret_cast<AActor*>(object);
				shot.since = now;
				g_enemyRecShots[object] = shot;
			}
		}

		std::string EnemyRecEnemyState(AAliceGameKynapsePawn* enemy)
		{
			std::ostringstream text;
			AController* const controller = enemy->Controller && IsLiveUObject(enemy->Controller)
				? enemy->Controller : nullptr;
			text << "ai=" << (controller ? controller->GetStateName().ToString() : std::string("-"))
				<< " brain=" << KynapseBrainState(controller)
				<< " target=" << EnemyRecName(controller ? controller->Enemy : nullptr)
				<< " npc=" << static_cast<int>(enemy->NPCState)
				<< " aiState=" << static_cast<int>(enemy->AIState)
				<< " healthState=" << static_cast<int>(enemy->HealthState)
				<< " fighting=" << (enemy->bIsFighting ? 1 : 0)
				<< " physics=" << static_cast<int>(enemy->Physics)
				<< " health=" << enemy->Health << '/' << enemy->HealthMax
				<< " canBeDamaged=" << (enemy->bCanBeDamaged ? 1 : 0);
			int shields = 0;
			const int32_t shieldCount = (std::min)(enemy->ShieldComponentsArray.size(), 8);
			for (int32_t index = 0; index < shieldCount; ++index)
			{
				if (enemy->ShieldComponentsArray.at(index).bInShield)
					shields |= 1 << index;
			}
			if (shieldCount > 0)
				text << " shields=0x" << std::hex << shields << std::dec << '/' << shieldCount;
			for (int32_t index = 0; index < (std::min)(enemy->NPCAttachedActors.size(), 4); ++index)
			{
				AAliceGameNPCAttachedActor* const plate = enemy->NPCAttachedActors.at(index).AttachedActor;
				if (plate && IsLiveUObject(plate))
				{
					text << " plate" << index << "=" << plate->HP << '/'
						<< static_cast<int>(plate->ActorState);
				}
			}
			text << " anims=[";
			const int32_t nodes = (std::min)(enemy->AnimBlendNodes.size(), 32);
			for (int32_t index = 0; index < nodes; ++index)
			{
				UAliceGameAnimNode_BlendBase* const node = enemy->AnimBlendNodes.at(index);
				if (!node || !IsLiveUObject(node) || !node->bIsPlayingCustomAnim)
					continue;
				UAnimNodeSequence* const sequence = CustomSequenceOf(node);
				if (sequence && sequence->AnimSeq)
					text << index << ':' << sequence->AnimSeqName.ToString() << ' ';
			}
			text << ']';
			if (UAnimNodeSequence* const dominant = FindDominantOneShotSequence(enemy->Mesh))
				text << " main=" << dominant->AnimSeqName.ToString();
			return text.str();
		}

		// JELLY BONES (30.10, client): a copy whose AI runs in the other game
		// is paused here (bPauseTick), yet a hit still starts its physics hit
		// reaction (bone springs, PhysicsWeight) - and the pawn tick that blends
		// it back never runs: the bones stay soft. Paused copies get no physics
		// hit reactions; a reaction already running is cut off (not the death
		// ragdoll: PHYS_RigidBody / health 0).
		std::unordered_set<AAliceGameKynapsePawn*> g_hitReactionsOff;

		// STALL WATCHDOG (30.10): an enemy handed back after its AI was paused
		// stood with no animation for good (fighting=0, Enemy set, brain on,
		// the wakes did nothing, hits ignored). The driving game watches its
		// own enemies: no AI activity (OnAnimEnd, a weapon, an effect) for 4 s
		// with its target near -> the AI is interrupted the way a hit does
		// (BreakByAI TakeDamage), told it sees its enemy, and woken.
		struct EnemyActivity
		{
			Clock::time_point last{};
			Clock::time_point lastKick{};
			bool driven = false;
			int kicks = 0;
			Clock::time_point lastBodySync{};
		};
		std::unordered_map<AAliceGameKynapsePawn*, EnemyActivity> g_enemyActivity;

		void NoteEnemyActivity(UObject* object, UFunction* function)
		{
			if (!g_connected || !object || !function)
				return;
			static std::unordered_map<const UFunction*, bool> isActivity;
			auto cached = isActivity.find(function);
			if (cached == isActivity.end())
			{
				const std::string name = function->GetName();
				cached = isActivity.emplace(function, name == "OnAnimEnd" || name == "SetNewWeapon"
					|| name == "ToggleLoopParticle" || name == "PlayParticleEffect"
					|| name == "PlayParticleEffectFromSphinxSequence"
					|| name == "ToggleSkeletalControl").first;
			}
			if (!cached->second || !object->IsA(AAliceGameKynapsePawn::StaticClass()))
				return;
			EnemyActivity& activity = g_enemyActivity[reinterpret_cast<AAliceGameKynapsePawn*>(object)];
			activity.last = Clock::now();
			activity.kicks = 0; // it acts again: count the kicks from zero
		}

		void KickStalledEnemy(AAliceGameKynapsePawn* enemy, AAliceGameKynapseAIController* controller,
			APawn* target, EnemyActivity& activity, Clock::time_point now)
		{
			activity.lastKick = now;
			activity.last = now; // give it 4 s to start again
			++activity.kicks;
			AController* attacker = target ? target->Controller : nullptr;
			if (!attacker && target == g_remotePawn && g_remoteController
				&& IsLiveUObject(g_remoteController))
			{
				attacker = g_remoteController;
			}
			const int brainBefore = KynapseBrainState(controller);
			ReleaseEnemyAnimWaits(enemy, "stalled");
			enemy->bIsFighting = true;
			controller->eventBreakByAI(EInterruptByAIType::e_IBAI_TakeDamage);
			controller->eventActiveAIEventTrigger(EInterruptByAIType::e_IBAI_SeeEnemy, 0, 0);
			ActivateKynapseBrain(controller);
			if (attacker)
				NudgeEnemyTowardActor(controller, enemy, attacker);
			// aibroken1: a warning that stands out in any log - the AI of
			// this enemy did not recover after 3 kicks in a row.
			if (activity.kicks == 4 || (activity.kicks > 4 && activity.kicks % 10 == 0))
			{
				Log("!!!!! AI BROKEN " + ObjectName(enemy) + " in the "
					+ (g_config.role == Role::Host ? "host" : "client")
					+ "'s game: " + std::to_string(activity.kicks - 1)
					+ " stall kicks without effect, enemy=" + ObjectName(controller->Enemy)
					+ ", fighting=" + (enemy->bIsFighting ? "1" : "0")
					+ ", health=" + std::to_string(enemy->Health) + " !!!!!");
			}
			static int logsLeft = 40;
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("STALL kicked " + ObjectName(enemy) + " (try " + std::to_string(activity.kicks)
					+ ", brain " + std::to_string(brainBefore) + "->"
					+ std::to_string(KynapseBrainState(controller)) + ", enemy "
					+ ObjectName(controller->Enemy) + ").");
			}
		}

		// KYNAPSE ENTITY (30.10): Ghidra - GetCurrentAttackTargetActor reads
		// the target from the controller's Kynapse entity (+0x3f0 -> +0x18,
		// vtable +0x50), inside the Kynapse library, not from Enemy/Focus.
		// Kynapse knows only actors registered through their KynapseHandle
		// (AlicePawn.KynapseHandle). If the proxy is not registered there,
		// no enemy can ever choose it. Logged for both Alices; in decoy mode
		// (HostRunsAll=1) the proxy is registered like the real one.
		std::string DescribeKynapseHandle(AAlicePawn* pawn)
		{
			if (!pawn || !IsUsableObjectFast(pawn))
				return "<no pawn>";
			UKynapseHandle* const handle = pawn->KynapseHandle;
			if (!handle || !IsUsableObjectFast(handle))
				return ObjectName(pawn) + " handle=<null>";
			return ObjectName(pawn) + " handle=" + ObjectName(handle)
				+ " def=" + ObjectName(handle->KEntityDefinition)
				+ " entities=" + std::to_string(handle->kynapseEntityArray.size())
				+ " entityHandles=" + std::to_string(handle->kynapseEntityHandleArray.size())
				+ " created=" + (handle->creationDone ? "1" : "0")
				+ " inWorld=" + (handle->entityAddedToWorld ? "1" : "0")
				+ " owner=" + ObjectName(handle->Owner);
		}

		void TickProxyKynapseEntity()
		{
			static AAlicePawn* lastProxy = nullptr;
			static int logs = 0;
			static Clock::time_point nextLog{};
			if (g_config.role != Role::Host || !g_connected)
				return;
			AAlicePawn* const proxy = g_remotePawn && IsUsableObjectFast(g_remotePawn)
				? g_remotePawn : nullptr;
			AAlicePawn* const local = GetLocalPawn();
			if (!proxy || !local)
				return;
			const auto now = Clock::now();
			if (proxy != lastProxy)
			{
				lastProxy = proxy;
				logs = 0;
				nextLog = now + std::chrono::seconds(2);
			}
			if (logs >= 4 || now < nextLog)
				return;
			++logs;
			nextLog = now + std::chrono::seconds(10);
			Log("KYNAPSEDIAG host Alice: " + DescribeKynapseHandle(local));
			Log("KYNAPSEDIAG proxy: " + DescribeKynapseHandle(proxy));
			if (g_config.hostRunsAllEnemies && logs == 1)
			{
				UKynapseHandle* const handle = proxy->KynapseHandle;
				if (handle && IsUsableObjectFast(handle) && !handle->entityAddedToWorld)
				{
					if (!handle->creationDone)
						handle->InitKynapseEntity();
					handle->AddKynapseEntity();
					Log("KYNAPSEDIAG proxy registered with Kynapse: " + DescribeKynapseHandle(proxy));
				}
			}
		}

