		// animsync1: a copy whose looping replay was not confirmed by the
		// driver for 2.5 s (it repeats "play" every second) stops it.
		void StopStaleReplayedAnims(AAliceGameKynapsePawn* enemy, Clock::time_point now)
		{
			const auto rx = g_enemyAnimPlayRx.find(enemy);
			if (rx == g_enemyAnimPlayRx.end())
				return;
			for (auto it = rx->second.begin(); it != rx->second.end();)
			{
				const int index = it->first;
				if (now - it->second < std::chrono::milliseconds(2500))
				{
					++it;
					continue;
				}
				it = rx->second.erase(it);
				if (index < 0 || index >= enemy->AnimBlendNodes.size())
					continue;
				UAliceGameAnimNode_BlendBase* const node = enemy->AnimBlendNodes.at(index);
				if (!node || !IsLiveUObject(node) || !node->bIsPlayingCustomAnim)
					continue;
				UAnimNodeSequence* const current = CustomSequenceOf(node);
				if (!current || !current->AnimSeq || !current->bLooping)
					continue;
				FAnimationParaConfig config{};
				reinterpret_cast<RawGameArray&>(config.AnimationNames) = RawGameArray{ nullptr, 0, 0 };
				reinterpret_cast<RawGameArray&>(config.AnimationDescName) = RawGameArray{ nullptr, 0, 0 };
				config.BlendNodeIndex = static_cast<std::uint8_t>(index);
				config.AnimType = static_cast<int32_t>(EAnimConfigType::EACT_Arbitrary);
				config.BlendOutTime = 0.2f;
				config.bCauseActorAnimEnd = false;
				const std::string name = current->AnimSeqName.ToString();
				const bool invoked = NativeStopConfigAnim(enemy, 0.2f, config, true);
				static int logsLeft = 40;
				if (logsLeft > 0)
				{
					--logsLeft;
					Log("ANIMSYNC stale loop " + name + " on " + ObjectName(enemy) + " node "
						+ std::to_string(index) + " stopped (" + (invoked ? "ok" : "failed") + ").");
				}
			}
		}

		// lockaim1 (31.10): the pepper grinder / teapot in lock-on mode aims
		// at TargetNPCSocket.Pawn.LockOnInfo.TargetSockets[i].CollisionLocation
		// (AlicePlayerController.GetAdjustedAimFor, UE Explorer). The pawn
		// refreshes those points in its own tick - which a paused copy never
		// runs: the shots flew to where the enemy stood when it was paused
		// (13:34:07, a fixed aim point in the air). Refreshed here from the
		// mesh sockets for every paused copy.
		bool SocketWorldTransform(USkeletalMeshComponent* mesh, const FName& socket,
			FVector& location, FRotator& rotation)
		{
			static UFunction* function = FindFunctionSafe(
				"Function Engine.SkeletalMeshComponent.GetSocketWorldLocationAndRotation");
			if (!function || !mesh)
				return false;
			USkeletalMeshComponent_execGetSocketWorldLocationAndRotation_Params parameters{};
			memcpy_s(&parameters.InSocketName, sizeof(parameters.InSocketName), &socket, sizeof(socket));
			if (!InvokeNativeFunction(mesh, function, parameters) || !parameters.ReturnValue)
				return false;
			location = parameters.OutLocation;
			rotation = parameters.OutRotation;
			return true;
		}

		void RefreshCopyLockOnSockets(AAliceGameKynapsePawn* enemy)
		{
			USkeletalMeshComponent* const mesh = enemy->Mesh;
			if (!mesh || !IsUsableObjectFast(mesh))
				return;
			auto& sockets = enemy->LockOnInfo.TargetSockets;
			const int32_t count = std::min<int32_t>(sockets.size(), 16);
			int moved = 0;
			float worst = 0.0f;
			for (int32_t i = 0; i < count; ++i)
			{
				FTargetableSocketInfo& info = sockets.at(i);
				FVector location;
				FRotator rotation;
				if (SocketWorldTransform(mesh, info.SocketName, location, rotation))
				{
					info.LockOnLocation = location;
					info.LockOnRotation = rotation;
				}
				if (SocketWorldTransform(mesh, info.CollisionSocketName, location, rotation))
				{
					const FVector d = location - info.CollisionLocation;
					worst = (std::max)(worst, d.SizeSquared());
					info.CollisionLocation = location;
					info.CollisionRotation = rotation;
					++moved;
				}
			}
			static int logsLeft = 20;
			if (logsLeft > 0 && worst > 300.0f * 300.0f)
			{
				--logsLeft;
				Log("LOCKAIM " + ObjectName(enemy) + ": lock-on point was "
					+ std::to_string(static_cast<int>(std::sqrt(worst)))
					+ " away from the body, refreshed " + std::to_string(moved) + " socket(s).");
			}
		}

		// posesmooth1 (31.10 15:12, Madcaps): a copy moved only when a pose
		// arrived (~10 a second), a fraction of the way each time, and stood
		// still in between - its lunges and jump attacks looked cut short and
		// jerky, ending in a jump to the real place. Now each pose only sets
		// a target (plus its velocity for the time since), and the copy glides
		// there every frame. Far targets still snap at once.
		struct EnemyPoseTarget
		{
			FVector location{};
			FRotator rotation{};
			FVector velocity{};
			Clock::time_point at{};
		};
		std::unordered_map<AAliceGameKynapsePawn*, EnemyPoseTarget> g_enemyPoseTargets;

		void NoteEnemyPoseTarget(AAliceGameKynapsePawn* enemy, const FVector& location,
			const FRotator& rotation, const FVector& velocity, bool snapped)
		{
			EnemyPoseTarget& target = g_enemyPoseTargets[enemy];
			{
				// posestep1: where do the copies jump? A new target far from the
				// previous one, or far from where the copy is.
				static int stepLogs = 200;
				const auto now = Clock::now();
				const float sincePrev = target.at == Clock::time_point{} ? 99.0f
					: std::chrono::duration<float>(now - target.at).count();
				const float step = std::sqrt((location - target.location).SizeSquared());
				const float lag = std::sqrt((location - enemy->Location).SizeSquared());
				if (stepLogs > 0 && sincePrev < 1.0f && (step > 120.0f || lag > 160.0f))
				{
					--stepLogs;
					char buffer[200];
					snprintf(buffer, sizeof(buffer), " step=%.0f in %.0f ms, lag=%.0f, speed=%.0f, physics=%d%s",
						step, sincePrev * 1000.0f, lag, std::sqrt(velocity.SizeSquared()),
						static_cast<int>(enemy->Physics), snapped ? " SNAP" : "");
					Log("POSESTEP " + ObjectName(enemy) + buffer);
				}
			}
			target.location = location;
			target.rotation = rotation;
			target.velocity = velocity;
			target.at = Clock::now();
			if (snapped)
			{
				NativeSetActorRotation(enemy, rotation);
				enemy->Rotation = rotation;
			}
		}

		bool NativeMoveActorBy(AActor* actor, const FVector& delta); // chasepush1

		// chasepush1 (12.11 17:25, Chapter4_W2_P: "the client just walks
		// through the Executioner"): in its own game the Executioner is
		// carried by the chase Matinee, and a Matinee move shoves whoever
		// stands in the way - that was the push. The copy here is put where
		// the host's one is, which shoves nobody, so this Alice could walk
		// into it and out behind it. While the copy runs its chase, this
		// Alice is moved out of it each frame (MoveSmooth: walls still stop
		// her), in the direction away from it - as if it pushed her.
		void PushAliceOutOfChaseCopy(AAliceGameKynapsePawn* enemy)
		{
			if (g_config.role != Role::Client || !enemy || enemy->Health <= 0 || enemy->bHidden
				|| !IsChaseExecutioner(enemy))
			{
				return;
			}
			AAlicePawn* const alice = GetLocalPawn();
			if (!alice || !IsUsableObjectFast(alice) || alice->Health <= 0)
				return;
			float enemyRadius = 60.0f, enemyHeight = 120.0f, aliceRadius = 25.0f, aliceHeight = 60.0f;
			if (enemy->CylinderComponent && IsUsableObjectFast(enemy->CylinderComponent))
			{
				enemyRadius = enemy->CylinderComponent->CollisionRadius;
				enemyHeight = enemy->CylinderComponent->CollisionHeight;
			}
			if (alice->CylinderComponent && IsUsableObjectFast(alice->CylinderComponent))
			{
				aliceRadius = alice->CylinderComponent->CollisionRadius;
				aliceHeight = alice->CylinderComponent->CollisionHeight;
			}
			const float keepOut = (std::max)(enemyRadius + aliceRadius, 120.0f);
			const float dx = alice->Location.X - enemy->Location.X;
			const float dy = alice->Location.Y - enemy->Location.Y;
			const float dz = alice->Location.Z - enemy->Location.Z;
			if (std::fabs(dz) > enemyHeight + aliceHeight)
				return;
			const float distance = std::sqrt(dx * dx + dy * dy);
			if (distance >= keepOut)
				return;
			FVector away;
			if (distance > 1.0f)
				away = FVector(dx / distance, dy / distance, 0.0f);
			else
			{
				// right on top of it: out in front of it, where it runs
				const float yaw = static_cast<float>(enemy->Rotation.Yaw) * (3.14159265f / 32768.0f);
				away = FVector(std::cos(yaw), std::sin(yaw), 0.0f);
			}
			const float depth = keepOut - distance + 2.0f;
			// chasepush2 (12.11 17:35:11: pushed every frame, yet the distance
			// still fell 151 -> 57): a sweep that starts inside the copy's
			// cylinder is stopped at once, so MoveSmooth never got her out.
			// She is set down outside it instead (SetLocation still refuses
			// a spot inside a wall); only if that is refused, swept.
			static UFunction* const setLocation = FindFunctionSafe("Function Engine.Actor.SetLocation");
			bool placed = false;
			if (setLocation)
			{
				AActor_execSetLocation_Params parameters{};
				parameters.NewLocation = FVector(alice->Location.X + away.X * depth,
					alice->Location.Y + away.Y * depth, alice->Location.Z);
				InvokeNativeFunction(alice, setLocation, parameters);
				placed = parameters.ReturnValue != 0;
			}
			// chasepush3 (12.11 17:47:12: "SetLocation refused, swept" every
			// frame, the distance still falling 151 -> 63 - in her hurt move
			// the game refuses to move her, and she was carried along inside
			// it, "riding without walking"): when the way out is free of the
			// level (a trace with her width), she is put there outright.
			bool forced = false;
			if (!placed)
			{
				static UFunction* const fastTrace = FindFunctionSafe("Function Engine.Actor.FastTrace");
				const FVector destination(alice->Location.X + away.X * depth,
					alice->Location.Y + away.Y * depth, alice->Location.Z);
				bool clear = false;
				if (fastTrace)
				{
					AActor_execFastTrace_Params trace{};
					trace.TraceEnd = destination;
					trace.TraceStart = alice->Location;
					// chasepush4 (12.11 18:14:35: "way blocked" every frame - a box
					// as tall as she is grazed the floor): a plain line at her
					// middle, raised a little.
					trace.TraceStart = FVector(alice->Location.X, alice->Location.Y, alice->Location.Z + 10.0f);
					trace.TraceEnd = FVector(destination.X, destination.Y, destination.Z + 10.0f);
					trace.BoxExtent = FVector(0.0f, 0.0f, 0.0f);
					InvokeNativeFunction(alice, fastTrace, trace);
					clear = trace.ReturnValue != 0;
				}
				if (clear)
					forced = NativeSetActorLocationNoCheck(alice, destination);
				if (!forced)
					NativeMoveActorBy(alice, FVector(away.X * depth, away.Y * depth, 0.0f));
			}
			static int logsLeft = 10;
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("CHASEPUSH this Alice was " + std::to_string(static_cast<int>(distance))
					+ " units inside the Executioner copy (keep-out "
					+ std::to_string(static_cast<int>(keepOut)) + "): "
					+ (placed ? "set down outside it." : forced ? "put outside it (way clear)."
						: "SetLocation refused, way blocked, swept."));
			}
		}

		void TickEnemyPoseSmoothing(AAliceGameKynapsePawn* enemy, Clock::time_point now)
		{
			const auto found = g_enemyPoseTargets.find(enemy);
			if (found == g_enemyPoseTargets.end() || !g_currentWorld)
				return;
			const EnemyPoseTarget& target = found->second;
			const float age = std::chrono::duration<float>(now - target.at).count();
			if (age > 1.0f)
				return;
			// posesmooth2: a short lead - 0.15 s of a lunge's speed overshot
			// and pulled back when it stopped ("teleported back").
			const float lead = std::clamp(age, 0.0f, 0.06f);
			const FVector predicted = target.location + target.velocity * lead;
			const float dt = std::clamp(g_currentWorld->DeltaSeconds, 0.0f, 0.1f);
			const float alpha = std::clamp(dt * 16.0f, 0.0f, 1.0f);
			const FVector next = enemy->Location + (predicted - enemy->Location) * alpha;
			NativeSetActorLocationNoCheck(enemy, next);
			enemy->Location = next;
			auto lerpAxis = [alpha](int32_t from, int32_t to) {
				int32_t diff = (to - from) & 0xFFFF;
				if (diff > 0x8000)
					diff -= 0x10000;
				return from + static_cast<int32_t>(diff * alpha);
			};
			const FRotator rotation(lerpAxis(enemy->Rotation.Pitch, target.rotation.Pitch),
				lerpAxis(enemy->Rotation.Yaw, target.rotation.Yaw),
				lerpAxis(enemy->Rotation.Roll, target.rotation.Roll));
			NativeSetActorRotation(enemy, rotation);
			enemy->Rotation = rotation;
		}

		// interpstuck1 (31.10 15:13, Madcap_3): after the skipped spawn
		// Matinee was jumped to its end, an enemy stayed in PHYS_Interpolating
		// for good - its AI never ran (a stall kick every 4 s for a minute)
		// and it stood where the Matinee had left it, under the floor. The
		// driving game drops such an enemy (unmoved for 4 s) to the ground.
		AActor* NativeActorTrace(AActor* caller, const FVector& start, const FVector& end,
			FVector& hitLocation, FTraceHitInfo& info, const FVector& extent = FVector(0, 0, 0));
		// interpstuck3 (31.10 15:47, Madcap_0 and _5 standing still for good,
		// killable): the spawn Matinee ended (InterpolationFinished at
		// 15:47:38.150) but did not give Madcap_5 its physics back - it stayed
		// PHYS_Interpolating, so its AI never moved it; Madcap_0 never even
		// rose out of the ground. The driving game now puts such an enemy on
		// the floor under it and gives it walking physics: 1 s after its
		// Matinee finished, or after 8 s unmoved outside any cutscene.
		std::unordered_map<AAliceGameKynapsePawn*, Clock::time_point> g_interpFinishedAt;
		struct InterpWatch
		{
			FVector location{};
			Clock::time_point since{};
			int fixes = 0;
		};
		std::unordered_map<AAliceGameKynapsePawn*, InterpWatch> g_enemyInterpWatch;

		void WatchStuckInterpolation(AAliceGameKynapsePawn* enemy, bool driven, Clock::time_point now)
		{
			AAlicePlayerController* const pc = g_State.AlicePlayerController;
			const bool cinematic = pc && IsUsableObjectFast(pc) && pc->bCinematicMode;
			if (!driven || static_cast<int>(enemy->Physics) != 7 || enemy->Health <= 0)
			{
				g_enemyInterpWatch.erase(enemy);
				return;
			}
			auto [it, inserted] = g_enemyInterpWatch.try_emplace(enemy, InterpWatch{ enemy->Location, now, 0 });
			InterpWatch& watch = it->second;
			if ((enemy->Location - watch.location).SizeSquared() > 4.0f * 4.0f)
			{
				watch.location = enemy->Location;
				watch.since = now;
				return;
			}
			const auto finished = g_interpFinishedAt.find(enemy);
			const bool matineeDone = finished != g_interpFinishedAt.end()
				&& now - finished->second > std::chrono::seconds(1);
			const bool longStill = !cinematic && now - watch.since > std::chrono::seconds(8);
			if ((!matineeDone && !longStill) || watch.fixes >= 3)
				return;
			++watch.fixes;
			watch.since = now;
			// The floor under it: from above its head down past its feet.
			const float half = enemy->CylinderComponent ? enemy->CylinderComponent->CollisionHeight : 60.0f;
			FVector top = enemy->Location;
			top.Z += 250.0f;
			FVector bottom = enemy->Location;
			bottom.Z -= 400.0f;
			FVector hit(0, 0, 0);
			FTraceHitInfo info{};
			// interpstuck4 (17:06:51): a zero-extent ray found no floor (the
			// floor meshes block only boxes) and the Madcap was dropped into
			// the void. A box trace now; no floor -> left as it is.
			// interpstuck5 (17:20:36): it stands in the spawn hole itself -
			// no floor right under it. The nearest floor around it then.
			AActor* floor = nullptr;
			static const float offsets[][2] = { { 0, 0 }, { 160, 0 }, { -160, 0 }, { 0, 160 }, { 0, -160 },
				{ 230, 230 }, { -230, 230 }, { 230, -230 }, { -230, -230 }, { 320, 0 }, { -320, 0 }, { 0, 320 }, { 0, -320 } };
			for (const auto& offset : offsets)
			{
				FVector from = top;
				FVector to = bottom;
				from.X += offset[0]; to.X += offset[0];
				from.Y += offset[1]; to.Y += offset[1];
				floor = NativeActorTrace(enemy, from, to, hit, info, FVector(12, 12, 12));
				if (floor)
					break;
			}
			const FVector before = enemy->Location;
			if (floor)
			{
				FVector standing = hit;
				standing.Z += half + 4.0f;
				NativeSetActorLocationNoCheck(enemy, standing);
				enemy->Location = standing;
				enemy->Velocity = FVector(0, 0, 0);
				NativeSetActorPhysics(enemy, 2);
				if (static_cast<int>(enemy->Physics) == 7)
					enemy->Physics = static_cast<EPhysics>(2);
			}
			else if (AAlicePawn* const alice = GetLocalPawn(); alice && watch.fixes >= 2)
			{
				// No floor found by any trace: out of the hole toward this
				// game's Alice, at her height (she stands on the floor), and
				// let it land.
				FVector toward = alice->Location - enemy->Location;
				toward.Z = 0.0f;
				const float length = std::sqrt(toward.SizeSquared());
				FVector standing = enemy->Location;
				if (length > 1.0f)
				{
					const float move = (std::min)(length - 80.0f, 260.0f);
					if (move > 0.0f)
						standing = standing + toward * (move / length);
				}
				standing.Z = (std::max)(standing.Z, alice->Location.Z) + 20.0f;
				NativeSetActorLocationNoCheck(enemy, standing);
				enemy->Location = standing;
				enemy->Velocity = FVector(0, 0, 0);
				NativeSetActorPhysics(enemy, 2);
				if (static_cast<int>(enemy->Physics) == 7)
					enemy->Physics = static_cast<EPhysics>(2);
				Log("INTERPSTUCK " + ObjectName(enemy) + ": no floor traced, lifted out of the hole to "
					+ FormatWorldTraceVector(standing) + '.');
			}
			static int logsLeft = 30;
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("INTERPSTUCK " + ObjectName(enemy) + " left in PHYS_Interpolating at "
					+ FormatWorldTraceVector(before) + (matineeDone ? " after its Matinee finished" : " for 8 s")
					+ ": " + (floor ? "put on the floor at " + FormatWorldTraceVector(enemy->Location) : std::string("no floor found"))
					+ ", physics now " + std::to_string(static_cast<int>(enemy->Physics)) + '.');
			}
		}

		// treediag1 (31.10 15:48, shield Madcap): while its weapon is stuck
		// after the jump attack the driver plays NO config animation (anims=[]
		// for ~3 s) - the pose comes from somewhere else in its AnimTree, which
		// the copy never gets. Dumps, for shield-carrying enemies on both
		// games, the switch nodes not on child 0 and the weighted sequences,
		// each time that changes - to find what holds the stuck pose.
		void CollectEnemyTree(UAnimNode* node, float weight, int depth, std::string& out, int& budget)
		{
			if (!node || depth > 24 || budget <= 0 || !IsUsableObjectFast(node))
				return;
			--budget;
			if (node->IsA(UAnimNodeSequence::StaticClass()))
			{
				auto* const sequence = reinterpret_cast<UAnimNodeSequence*>(node);
				if (weight > 0.25f && sequence->AnimSeq)
				{
					char buffer[160];
					snprintf(buffer, sizeof(buffer), " seq:%s@%.2f%s w%.2f", sequence->AnimSeqName.ToString().c_str(),
						sequence->CurrentTime, sequence->bPlaying ? "" : "(paused)", weight);
					out += buffer;
				}
				return;
			}
			if (!node->IsA(UAnimNodeBlendBase::StaticClass()))
				return;
			auto* const blend = reinterpret_cast<UAnimNodeBlendBase*>(node);
			int best = -1;
			float bestWeight = 0.0f;
			for (int32_t i = 0; i < blend->Children.size(); ++i)
			{
				const FAnimBlendChild& child = blend->Children.at(i);
				if (child.Weight > bestWeight)
				{
					bestWeight = child.Weight;
					best = i;
				}
			}
			if (best > 0 && weight > 0.25f)
			{
				out += " [" + node->NodeName.ToString() + "/" + ObjectName(node->Class).substr(0, 48)
					+ " ->" + std::to_string(best) + ":" + blend->Children.at(best).Name.ToString() + "]";
			}
			for (int32_t i = 0; i < blend->Children.size(); ++i)
			{
				const FAnimBlendChild& child = blend->Children.at(i);
				if (child.Weight > 0.05f)
					CollectEnemyTree(child.Anim, weight * child.Weight, depth + 1, out, budget);
			}
		}

		void DiagEnemyTree(AAliceGameKynapsePawn* enemy, bool driven, Clock::time_point now)
		{
			static std::unordered_map<AAliceGameKynapsePawn*, std::pair<std::string, Clock::time_point>> last;
			static int logsLeft = 700;
			if (logsLeft <= 0 || enemy->Health <= 0
				|| !enemy->Mesh || !enemy->Mesh->Animations)
			{
				return;
			}
			auto& entry = last[enemy];
			if (now - entry.second < std::chrono::milliseconds(250))
				return;
			entry.second = now;
			std::string tree;
			int budget = 400;
			CollectEnemyTree(enemy->Mesh->Animations, 1.0f, 0, tree, budget);
			if (tree == entry.first)
				return;
			entry.first = tree;
			--logsLeft;
			Log("ENEMYTREE " + ObjectName(enemy) + (driven ? " DRIVEN" : " copy")
				+ " rmm=" + std::to_string(static_cast<int>(enemy->Mesh->RootMotionMode))
				+ " fakeRmm=" + std::to_string(static_cast<int>(enemy->Mesh->FakeRootMotionMode))
				+ " vel=" + std::to_string(static_cast<int>(std::sqrt(enemy->Velocity.SizeSquared()))) + ":" + tree);
		}

		void TickPausedEnemyPhysics()
		{
			// enemyfree2 (12.11 19:59:54 host crash here, read at enemy+8:
			// a registry entry pointed at an enemy whose memory was already
			// freed - the flag test of IsUsableObjectFast read it raw). Not
			// while the world is torn down, and only enemies the object
			// table still holds (IsLiveUObject reads the slot guarded).
			if (!g_connected || !g_config.sharedEnemyTransforms || g_config.localMirror
				|| WorldTransitionActive() || LeavingWorld())
			{
				g_hitReactionsOff.clear();
				return;
			}
			static int logsLeft = 30;
			const auto now = Clock::now();
			ReapplyPendingDeathAnims(now);
			TickAliceFrozenRelay(now);
			TickHairParamRelay(now); // hairsync1
			// enemyfree2: a copy - the body can destroy enemies and change
			// the registry under the loop.
			std::vector<std::pair<std::uint64_t, AAliceGameKynapsePawn*>> pausedEnemies;
			pausedEnemies.reserve(g_sharedEnemyRegistry.size());
			for (const auto& [regKey, regEnemy] : g_sharedEnemyRegistry)
				pausedEnemies.emplace_back(regKey, regEnemy);
			for (const auto& [key, enemy] : pausedEnemies)
			{
				if (!enemy || !IsLiveUObject(enemy) || enemy->bDeleteMe)
					continue;
				// Stall watchdog (driving game only).
				{
					EnemyActivity& activity = g_enemyActivity[enemy];
					const std::uint64_t shared = SharedKeyForEnemy(enemy, key);
					const bool driven = shared && LocallyDrivesSharedEnemy(shared)
						&& !enemy->bPauseTick && enemy->Health > 0;
					if (driven != activity.driven)
					{
						activity.driven = driven;
						activity.last = now;
						activity.kicks = 0;
					}
					StopReplayedLoopsFor(enemy, driven);
					WatchStuckInterpolation(enemy, driven, now);
					TickEnemyBranch(shared, enemy, driven, now);
					DiagEnemyTree(enemy, driven, now);
					if (!driven && enemy->Health > 0)
					{
						TickEnemyPoseSmoothing(enemy, now);
						PushAliceOutOfChaseCopy(enemy); // chasepush1
					}
					// deathfx1: the driver tells the other game when its dead
					// body is gone (the Sphinx death sequence hid it).
					if (enemy->Health > 0)
					{
						ForgetDeathHide(enemy);
						g_enemyDeathSeen.erase(enemy);
					}
					else
					{
						if (shared && g_drivenWhileAlive[enemy] && enemy->bHidden)
							SendDeathHide(shared, enemy, now);
						// deathfx3 (31.10 16:59:15, shield Madcap_6 killed 1 s after
						// the host took it over): its death sequence never ran - no
						// death animation, no dissolve, a body turning on the spot
						// in both games. A dead body still shown 7 s (the driver)
						// or 12 s (the other game) after the death is hidden here.
						auto& seen = g_enemyDeathSeen[enemy];
						if (seen == Clock::time_point{})
							seen = now;
						const bool mine = g_drivenWhileAlive[enemy];
						if (!enemy->bHidden && now - seen > std::chrono::seconds(mine ? 7 : 12))
						{
							Log("DEATHHIDE fallback " + ObjectName(enemy) + ": dead for "
								+ std::to_string(mine ? 7 : 12) + " s and still shown, hidden here"
								+ (mine ? " (and in the other game)." : "."));
							if (mine)
							{
								NativeSetActorHidden(enemy, true);
								NativeSetActorCollision(enemy, false, false);
							}
							else
								HideDeadEnemyCopy(enemy);
							seen = now + std::chrono::hours(1);
						}
					}
					AController* const raw = enemy->Controller;
					if (driven && raw && IsUsableObjectFast(raw)
						&& raw->IsA(AAliceGameKynapseAIController::StaticClass()))
					{
						auto* const controller = reinterpret_cast<AAliceGameKynapseAIController*>(raw);
						// No Enemy at all but in a fight (the client's copy taken over
						// at 02:00:49: three wakes, enemyAfter=<null>, idle for 30 s):
						// aim at this game's Alice.
						APawn* const aim = controller->Enemy ? controller->Enemy
							: (enemy->bIsFighting ? static_cast<APawn*>(GetLocalPawn()) : nullptr);
						// Walking/turning toward its target is activity too.
						if (enemy->Velocity.SizeSquared() > 60.0f * 60.0f)
							activity.last = now;
						constexpr float NearSquared = 3000.0f * 3000.0f;
						if (aim && IsUsableObjectFast(aim) && aim->Health > 0
							&& (aim->Location - enemy->Location).SizeSquared() < NearSquared
							&& now - activity.last > std::chrono::seconds(4)
							&& now - activity.lastKick > std::chrono::seconds(4)
							&& !controller->bPauseTick && !WorldTransitionActive())
						{
							KickStalledEnemy(enemy, controller, aim, activity, now);
						}
					}
				}
				const bool paused = enemy->bPauseTick && enemy->Health > 0
					&& static_cast<int>(enemy->Physics) != 10;
				if (paused)
				{
					StopStaleReplayedAnims(enemy, now);
					RefreshCopyLockOnSockets(enemy);
				}
				if (paused)
				{
					// staleaim1 (31.10 13:05): the host's pepper grinder aimed at
					// a point 600 away next to the copy's controller/inventory -
					// where the copy WAS: a paused copy, moved by poses, kept its
					// collision bodies (physics asset) at the old place, and the
					// crosshair ray hit those invisible bodies. They follow the
					// copy now (10 times a second).
					EnemyActivity& bodies = g_enemyActivity[enemy];
					if (now - bodies.lastBodySync >= std::chrono::milliseconds(100))
					{
						bodies.lastBodySync = now;
						NativeForceUpdateComponents(enemy, false, true);
						USkeletalMeshComponent* const skel = enemy->Mesh;
						// crabflick1 (11.11 02:34:34-38, Cannon Crab on its back,
						// driven by the host): the client's copy flickered fast,
						// ~7-10 times a second - this body sync. On its back the
						// crab's legs are physics bodies (ToggleSkeletalControl),
						// and teleporting the simulated bodies to the anim pose
						// 10 times a second snapped them back and forth. For the
						// crab only the fixed bodies are moved (they are what the
						// aim ray hits), the simulated ones are left to physics.
						static UClass* const crabClass = AAliceGameCannonCrabPawn::StaticClass();
						const bool crab = crabClass && enemy->IsA(crabClass);
						// crabflick2 (11.11 20:16, the client saw no stun at all):
						// with crabflick1 the simulated bodies stayed where they
						// were, and the copy's mesh, blended with them, showed
						// the crab standing although its animation tree played
						// KnockBack2A/2B (enemyrec). The copy's crab now shows its
						// animation only (physics weight 0), so the bodies can
						// follow the pose again without any flicker.
						if (crab && skel && IsUsableObjectFast(skel) && skel->PhysicsWeight != 0.0f)
						{
							static int weightLogs = 10;
							if (weightLogs > 0)
							{
								--weightLogs;
								Log("CRABPOSE copy " + ObjectName(enemy) + " had physics weight "
									+ std::to_string(skel->PhysicsWeight) + ": shown from its animation only (crabflick2).");
							}
							skel->PhysicsWeight = 0.0f;
						}
						if (skel && IsUsableObjectFast(skel) && skel->PhysicsAssetInstance)
							skel->UpdateRBBonesFromSpaceBases(true, true);
						if (enemy->Controller && IsUsableObjectFast(enemy->Controller))
							enemy->Controller->Location = enemy->Location;
					}
					if (enemy->bCanPlayPhysicsHitReactions)
					{
						enemy->bCanPlayPhysicsHitReactions = false;
						g_hitReactionsOff.insert(enemy);
					}
					USkeletalMeshComponent* const mesh = enemy->Mesh;
					if (mesh && IsUsableObjectFast(mesh) && mesh->PhysicsWeight > 0.0f)
					{
						if (logsLeft > 0)
						{
							--logsLeft;
							Log("JELLY " + ObjectName(enemy) + ": physics weight "
								+ std::to_string(mesh->PhysicsWeight) + " on a paused copy, cut to 0.");
						}
						mesh->PhysicsWeight = 0.0f;
						mesh->bEnableFullAnimWeightBodies = false;
					}
				}
				else if (g_hitReactionsOff.erase(enemy) && enemy->Health > 0)
				{
					enemy->bCanPlayPhysicsHitReactions = true;
				}
			}
		}

		void TickEnemyRecorder()
		{
			if (!g_config.enemyRecord || WorldTransitionActive())
				return;
			EnemyRecOpenForMap();
			if (!g_enemyRec.is_open())
				return;
			AAlicePawn* const localPawn = GetLocalPawn();
			if (!localPawn || !g_currentWorld)
				return;
			static Clock::time_point nextPass{};
			static Clock::time_point nextRegistry{};
			const auto now = Clock::now();
			if (now < nextPass)
				return;
			nextPass = now + std::chrono::milliseconds(100);
			g_enemyRecQuerying = true;
			if (now >= nextRegistry)
			{
				nextRegistry = now + std::chrono::seconds(1);
				RefreshSharedEnemyRegistry(g_currentWorld);
			}
			for (const auto& [key, enemy] : g_sharedEnemyRegistry)
			{
				(void)key;
				if (!enemy || !IsLiveUObject(enemy) || enemy->bDeleteMe
					|| (enemy->Location - localPawn->Location).SizeSquared() > 4000.0f * 4000.0f)
				{
					continue;
				}
				const std::string state = EnemyRecEnemyState(enemy);
				auto& last = g_enemyRecLastState[enemy];
				if (last != state)
				{
					last = state;
					const FVector to = localPawn->Location - enemy->Location;
					EnemyRecWrite("STATE " + EnemyRecName(enemy) + " " + state
						+ " dist=" + std::to_string(static_cast<int>(std::sqrt(to.SizeSquared())))
						+ " yaw=" + std::to_string(enemy->Rotation.Yaw & 0xFFFF));
				}
				// enemyrectree1 (08.11, Drifting Ruin stun): the stun is not a
				// config animation (anims=[] on the ground, solo and co-op
				// alike), so the recorder also writes the AnimTree switches
				// and weighted sequences when they change - in single player
				// too, to compare with co-op.
				if (enemy->Health > 0 && enemy->Mesh && enemy->Mesh->Animations)
				{
					static std::unordered_map<AAliceGameKynapsePawn*, std::string> lastTree;
					std::string tree;
					int budget = 400;
					CollectEnemyTree(enemy->Mesh->Animations, 1.0f, 0, tree, budget);
					std::string& previous = lastTree[enemy];
					if (tree != previous)
					{
						previous = tree;
						EnemyRecWrite("TREE " + EnemyRecName(enemy) + " physics="
							+ std::to_string(static_cast<int>(enemy->Physics)) + ":" + tree);
					}
				}
			}
			// Alice herself.
			{
				std::ostringstream alice;
				alice << "specialMove=" << static_cast<int>(localPawn->SpecialMove)
					<< " inShield=" << (localPawn->bInShield ? 1 : 0)
					<< " deflectSpin=" << (localPawn->bIsDeflectSpinning ? 1 : 0)
					<< " weapon=" << EnemyRecName(localPawn->Weapon)
					<< " health=" << localPawn->Health;
				if (alice.str() != g_enemyRecLastAlice)
				{
					g_enemyRecLastAlice = alice.str();
					EnemyRecWrite("ALICE " + g_enemyRecLastAlice);
				}
			}
			// Shots: describe once aimed, then course changes and the end.
			for (auto it = g_enemyRecShots.begin(); it != g_enemyRecShots.end();)
			{
				EnemyRecShot& shot = it->second;
				AActor* const actor = shot.actor;
				const bool alive = actor && IsLiveUObject(actor) && !actor->bDeleteMe;
				if (!alive || now - shot.since > std::chrono::seconds(20))
				{
					EnemyRecWrite("SHOT " + std::string(alive ? "timed out " : "gone ")
						+ EnemyRecName(actor));
					it = g_enemyRecShots.erase(it);
					continue;
				}
				const FVector velocity = actor->Velocity;
				if (!shot.described)
				{
					shot.described = true;
					std::ostringstream text;
					text << "SHOT new " << EnemyRecName(actor) << " class=" << EnemyRecName(actor->Class)
						<< " from=" << EnemyRecName(actor->Instigator)
						<< " at=(" << static_cast<int>(actor->Location.X) << ','
						<< static_cast<int>(actor->Location.Y) << ',' << static_cast<int>(actor->Location.Z)
						<< ") speed=" << static_cast<int>(std::sqrt(velocity.SizeSquared()))
						<< " physics=" << static_cast<int>(actor->Physics)
						<< " base=" << EnemyRecName(actor->Base);
					if (actor->IsA(AAliceGameProjectile::StaticClass()))
					{
						UAliceGameProjectileTrace* const trace =
							reinterpret_cast<AAliceGameProjectile*>(actor)->ProjTrace;
						if (trace && IsLiveUObject(trace))
						{
							text << " trace=" << EnemyRecName(trace->Class)
								<< " dest=(" << static_cast<int>(trace->DestLocation.X) << ','
								<< static_cast<int>(trace->DestLocation.Y) << ','
								<< static_cast<int>(trace->DestLocation.Z) << ") target="
								<< EnemyRecName(trace->TargetEnemyActor)
								<< " flight=" << trace->FlightTime
								<< " rebound=" << (trace->bInRebounding ? 1 : 0);
						}
					}
					EnemyRecWrite(text.str());
				}
				else
				{
					const float speedSquared = velocity.SizeSquared();
					const float lastSquared = shot.lastVelocity.SizeSquared();
					bool changed = (speedSquared < 1.0f) != (lastSquared < 1.0f);
					if (!changed && speedSquared > 1.0f && lastSquared > 1.0f)
					{
						const float dot = (velocity.X * shot.lastVelocity.X
							+ velocity.Y * shot.lastVelocity.Y + velocity.Z * shot.lastVelocity.Z)
							/ std::sqrt(speedSquared * lastSquared);
						changed = dot < 0.9f;
					}
					if (changed)
					{
						std::ostringstream text;
						text << "SHOT course " << EnemyRecName(actor) << " speed="
							<< static_cast<int>(std::sqrt(speedSquared))
							<< " instigator=" << EnemyRecName(actor->Instigator);
						if (actor->IsA(AAliceGameProjectile::StaticClass()))
						{
							UAliceGameProjectileTrace* const trace =
								reinterpret_cast<AAliceGameProjectile*>(actor)->ProjTrace;
							if (trace && IsLiveUObject(trace))
							{
								text << " target=" << EnemyRecName(trace->TargetEnemyActor)
									<< " rebound=" << (trace->bInRebounding ? 1 : 0);
							}
						}
						EnemyRecWrite(text.str());
					}
				}
				shot.lastVelocity = velocity;
				++it;
			}
			g_enemyRecQuerying = false;
			g_enemyRec.flush();
		}

		// ---- Enemy projectiles, shared (kinds 44..47, npcshot3) ----------
		// Only the copy whose AI runs fires: its shot is sent (44) and spawned
		// on the other machine as a mirror; a shot fired by a mirrored copy is
		// retired at once. NPC shots fly along their ProjTrace (a curve to
		// DestLocation, optionally to TargetEnemyActor) - setting a velocity
		// does nothing: the 29.10 mirrors flew to the wrong Alice and seemed
		// to teleport. So the trace travels (DestLocation, target) and the
		// mirror runs the trace's own init (vtable +0x130, the call the
		// teapot shells already use). A shot the Ruin holds first (speed 0)
		// follows the hand (47) and gets its throw (45, flag 1); a shot
		// deflected here is sent (45) - here it stays real, the other copy
		// follows the new course without collision and goes when this one is
		// gone (46).
		void RetireShotActor(AActor* actor);
		bool IsExecutableAddress(uintptr_t address);
		constexpr SharedWorldEventKind kEventNpcShot = static_cast<SharedWorldEventKind>(44);
		constexpr SharedWorldEventKind kEventNpcShotDeflect = static_cast<SharedWorldEventKind>(45);
		constexpr SharedWorldEventKind kEventNpcShotGone = static_cast<SharedWorldEventKind>(46);
		constexpr SharedWorldEventKind kEventNpcShotHeld = static_cast<SharedWorldEventKind>(47);
		constexpr std::uint8_t kNpcShotThrown = 1u;
		constexpr std::uint8_t kNpcShotHasTrace = 4u;
		constexpr std::uint8_t kNpcShotHeldFlag = 8u;
		// shotcourse1 (31.10): the copy of a shot flew on the line the trace
		// had at the spawn (AlignSocketInfinity: along the hand's socket) and
		// hit a wall after 0.8 s, while the real one turned to its target;
		// a deflection was not seen either. The machine that owns a shot (the
		// driver, or the one that deflected it) now sends its course 10x a
		// second and the other one follows it.
		constexpr SharedWorldEventKind kEventNpcShotCourse = static_cast<SharedWorldEventKind>(51);
		struct NpcShotTrack
		{
			AActor* actor = nullptr;
			FVector lastVelocity{};
			bool mirrored = false;      // spawned here from the other game's shot
			bool deflectedHere = false; // this machine owns it since a deflect
			bool visualOnly = false;    // follows the other machine, no collision
			bool held = false;          // still in the enemy's hand (speed ~0)
			bool everHeld = false;
			Clock::time_point since{};
			Clock::time_point nextHeldSend{};
			Clock::time_point born{};
			Clock::time_point nextCourseSend{};
		};
		std::unordered_map<std::int32_t, NpcShotTrack> g_npcShots;
		std::unordered_map<const void*, std::int32_t> g_npcShotIdByActor;
		std::vector<AActor*> g_npcShotsPending;
		bool g_spawningMirroredNpcShot = false;
		std::vector<AActor*> g_aliceShotsPending;
		std::int32_t g_nextNpcShotId = 1;
		const void* g_npcShotWorld = nullptr;
		int g_npcShotLogsLeft = 300; // enemyanimset1: more room for the boss shots

		bool IsMirroredNpcShot(const AActor* actor)
		{
			const auto found = g_npcShotIdByActor.find(actor);
			if (found == g_npcShotIdByActor.end())
				return false;
			const auto track = g_npcShots.find(found->second);
			return track != g_npcShots.end() && track->second.mirrored;
		}

		// An original shot whose copy flies in the other game (its hit on the
		// other Alice happens there, not on her proxy here).
		bool IsOriginalNpcShot(const AActor* actor)
		{
			const auto found = g_npcShotIdByActor.find(actor);
			if (found == g_npcShotIdByActor.end())
				return false;
			const auto track = g_npcShots.find(found->second);
			return track != g_npcShots.end() && !track->second.mirrored;
		}

		FRotator RotatorFromDirection(const FVector& v)
		{
			constexpr float ToUnreal = 32768.0f / 3.14159265f;
			const float planar = std::sqrt(v.X * v.X + v.Y * v.Y);
			return FRotator(static_cast<int32_t>(std::atan2(v.Z, planar) * ToUnreal),
				static_cast<int32_t>(std::atan2(v.Y, v.X) * ToUnreal), 0);
		}

		UAliceGameProjectileTrace* NpcShotTrace(AActor* actor)
		{
			if (!actor || !actor->IsA(AAliceGameProjectile::StaticClass()))
				return nullptr;
			UAliceGameProjectileTrace* const trace =
				reinterpret_cast<AAliceGameProjectile*>(actor)->ProjTrace;
			return trace && IsLiveUObject(trace) ? trace : nullptr;
		}

		// The trace's own init (as the shooter's weapon runs it): computes the
		// curve and the start velocity from DestLocation / TargetEnemyActor.
		bool RunNpcShotTraceInit(AActor* shot, AWeapon* weapon,
			const FVector& destination, AActor* target)
		{
			UAliceGameProjectileTrace* const trace = NpcShotTrace(shot);
			if (!trace)
				return false;
			auto* const projectile = reinterpret_cast<AAliceGameProjectile*>(shot);
			trace->RefSpeed = projectile->Speed;
			trace->AngleToleranceXY = projectile->AngleToleranceXY;
			trace->AngleToleranceZ = projectile->AngleToleranceZ;
			trace->DestLocation = destination;
			trace->TargetEnemyActor = target;
			using TraceInitFn = void(__thiscall*)(void* trace, void* weapon,
				void* projectile, float maxShotDist, int firstPerson);
			void** const vtable = *reinterpret_cast<void***>(trace);
			const uintptr_t address = vtable && IsReadableRange(vtable, 0x134)
				? reinterpret_cast<uintptr_t>(vtable[0x130 / 4]) : 0;
			if (!address || !IsExecutableAddress(address))
				return false;
			reinterpret_cast<TraceInitFn>(address)(trace, weapon, projectile,
				projectile->MaxShotDist, 0);
			projectile->LastLocation = projectile->Location;
			return true;
		}

		// 0 none, 1 the sender's own Alice, 2 the receiver's Alice (the
		// sender's proxy), 3 an enemy (its key travels as entityKey).
		std::int32_t NpcShotTargetCode(const AActor* target)
		{
			if (!target)
				return 0;
			if (target == GetLocalPawn())
				return 1;
			if (target == g_remotePawn)
				return 2;
			// IsA is not const in this SDK.
			if (const_cast<AActor*>(target)->IsA(AAliceGameKynapsePawn::StaticClass()))
				return 3;
			return 0;
		}

		AActor* NpcShotTargetFromCode(std::int32_t code, std::uint64_t key)
		{
			switch (code)
			{
			case 1: return g_remotePawn; // the sender's Alice is the proxy here
			case 2: return GetLocalPawn();
			case 3: return key ? EnemyForSharedKey(key) : nullptr;
			default: return nullptr;
			}
		}

		// SHARED RUIN: an enemy fights one Alice (its AI runs in her game), so
		// only she was ever shot at - and only a shot deflected back at a
		// Menacing Ruin opens it. Every second shot goes to the other Alice
		// when both are in the fight: here it flies at her proxy, in her game
		// its copy flies at her - she can deflect it or take the hit.
		bool RetargetNpcShotToOtherAlice(AActor* shot, AAliceGameKynapsePawn* enemy)
		{
			// noretarget1 (30.10): the shots must fly only at the Alice the
			// Ruin chose - its AI already aims at the Alice of its own game.
			if (shot || enemy)
				return false;
			AAlicePawn* const localPawn = GetLocalPawn();
			AAlicePawn* const other = g_remotePawn && IsLiveUObject(g_remotePawn)
				&& !g_remotePawn->bDeleteMe && !g_remotePawn->bHidden
				? g_remotePawn : nullptr;
			static int reasonLogs = 20;
			auto refuse = [&](const char* reason)
			{
				if (reasonLogs > 0)
				{
					--reasonLogs;
					Log(std::string("NPCSHOT stays on its Alice: ") + reason + '.');
				}
				return false;
			};
			if (!shot || !enemy || !localPawn)
				return false;
			if (!other)
				return refuse("no visible proxy");
			if (other->Health <= 0)
				return refuse("the proxy's health is 0");
			constexpr float FightSquared = 2500.0f * 2500.0f;
			if ((enemy->Location - localPawn->Location).SizeSquared() > FightSquared
				|| (enemy->Location - other->Location).SizeSquared() > FightSquared)
			{
				return refuse("an Alice is farther than 2500");
			}
			static std::unordered_map<const void*, unsigned> shotsByEnemy;
			if (shotsByEnemy.size() > 64)
				shotsByEnemy.clear();
			if ((shotsByEnemy[enemy]++ & 1u) == 0)
				return false; // this one stays on the Alice it fights
			const FVector aim(other->Location.X, other->Location.Y,
				other->Location.Z + 20.0f);
			const float speed = std::sqrt(shot->Velocity.SizeSquared());
			// AlignSocketInfinity (the Ruin's shot) flies straight on from its
			// start velocity: re-run the trace, then turn the velocity too.
			RunNpcShotTraceInit(shot, enemy->Weapon, aim, other);
			FVector direction = aim - shot->Location;
			const float length = std::sqrt(direction.SizeSquared());
			if (speed < 1.0f || length < 1.0f)
				return false;
			shot->Velocity = FVector(direction.X / length * speed,
				direction.Y / length * speed, direction.Z / length * speed);
			NativeSetActorRotation(shot, RotatorFromDirection(shot->Velocity));
			// The trace keeps steering toward DestLocation: put it on the new
			// line (the Ruin's straight shots fly ~MaxShotDist).
			if (UAliceGameProjectileTrace* const trace = NpcShotTrace(shot))
			{
				const float reach = (std::max)(length,
					reinterpret_cast<AAliceGameProjectile*>(shot)->MaxShotDist);
				trace->DestLocation = FVector(shot->Location.X + direction.X / length * reach,
					shot->Location.Y + direction.Y / length * reach,
					shot->Location.Z + direction.Z / length * reach);
				trace->TargetEnemyActor = other;
			}
			static int retargetLogs = 20;
			if (retargetLogs > 0)
			{
				--retargetLogs;
				Log("NPCSHOT re-aimed " + ObjectName(shot) + " at the other Alice "
					+ ObjectName(other) + ", distance " + std::to_string(static_cast<int>(length)) + '.');
			}
			return true;
		}

		// ProcessEvent hook (before): a new NPC projectile.
		void ObserveNpcShotSpawn(UObject* object, UFunction* function)
		{
			if (!g_connected || !g_config.sharedEnemyTransforms
				|| g_config.localMirror || g_spawningMirroredNpcShot)
			{
				return;
			}
			static std::unordered_map<const UFunction*, bool> isPostBeginPlay;
			auto cached = isPostBeginPlay.find(function);
			if (cached == isPostBeginPlay.end())
				cached = isPostBeginPlay.emplace(function,
					function->GetName() == "PostBeginPlay").first;
			if (!cached->second)
				return;
			// ALICESHOT (31.10): the user's own pepper grinder / teapot shots
			// sometimes fly aside - what did they aim at?
			if (object->IsA(AAliceGameProjectile::StaticClass())
				&& !object->IsA(ANpcProjectile::StaticClass()))
			{
				AAlicePawn* const localPawn = GetLocalPawn();
				if (localPawn && reinterpret_cast<AActor*>(object)->Instigator == localPawn
					&& g_aliceShotsPending.size() < 16)
				{
					g_aliceShotsPending.push_back(reinterpret_cast<AActor*>(object));
				}
				return;
			}
			if (!object->IsA(ANpcProjectile::StaticClass()))
				return;
			if (g_npcShotsPending.size() < 64)
				g_npcShotsPending.push_back(reinterpret_cast<AActor*>(object));
		}

		// aliceshotdiag4: what does a ray toward the aim point hit? The
		// aim points of the host's grinder sat in the air with no actor near
		// (13:34:07, only dead emitters): some component far from its actor.
		AActor* NativeActorTrace(AActor* caller, const FVector& start, const FVector& end,
			FVector& hitLocation, FTraceHitInfo& info, const FVector& extent)
		{
			static UFunction* function = nullptr;
			if (!function)
				function = FindFunctionSafe("Function Engine.Actor.Trace");
			if (!function || !caller)
				return nullptr;
			AActor_execTrace_Params parameters{};
			parameters.TraceEnd = end;
			parameters.TraceStart = start;
			parameters.bTraceActors = 1;
			parameters.Extent = extent;
			parameters.ExtraTraceFlags = 0;
			// trace2 (31.10 17:31): every trace came back empty (the ALICESHOT
			// rays and all INTERPSTUCK floors): Actor.Trace is native but not an
			// intrinsic (iNative 0), which InvokeNativeFunction refuses.
			// Called through ProcessEvent then; the flags are logged once.
			static bool flagsLogged = false;
			if (!flagsLogged)
			{
				flagsLogged = true;
				Log("TRACEFN Actor.Trace flags=0x" + [&] { char b[16]; snprintf(b, sizeof(b), "%x", function->FunctionFlags); return std::string(b); }()
					+ " iNative=" + std::to_string(static_cast<int>(function->iNative)) + '.');
			}
			if ((function->FunctionFlags & 0x400) != 0 && function->iNative != 0)
				InvokeNativeFunction(caller, function, parameters);
			else
				caller->ProcessEvent(function, &parameters, nullptr);
			hitLocation = parameters.HitLocation;
			info = parameters.HitInfo;
			return parameters.ReturnValue;
		}

		void LogAliceShots()
		{
			static int logsLeft = 80;
			std::vector<AActor*> pending;
			pending.swap(g_aliceShotsPending);
			AAlicePawn* const localPawn = GetLocalPawn();
			for (AActor* const shot : pending)
			{
				if (logsLeft <= 0 || !shot || !IsUsableObjectFast(shot) || shot->bDeleteMe || !localPawn)
					continue;
				--logsLeft;
				UAliceGameProjectileTrace* const trace = NpcShotTrace(shot);
				AActor* const target = trace ? trace->TargetEnemyActor : nullptr;
				std::string targetText = ObjectName(target);
				if (target && IsUsableObjectFast(target))
				{
					const FVector d = trace->DestLocation - target->Location;
					targetText += " at " + std::to_string(static_cast<int>(std::sqrt(d.SizeSquared())))
						+ " from the aim point, hidden=" + (target->bHidden ? "1" : "0");
					if (target->IsA(AAliceGameKynapsePawn::StaticClass()))
					{
						auto* const enemy = reinterpret_cast<AAliceGameKynapsePawn*>(target);
						const std::uint64_t key = SharedKeyForEnemy(enemy, SharedEnemyStableKey(enemy));
						targetText += std::string(" paused=") + (enemy->bPauseTick ? "1" : "0")
							+ " drivenHere=" + (key && LocallyDrivesSharedEnemy(key) ? "1" : "0")
							+ " health=" + std::to_string(enemy->Health);
					}
				}
				const FVector toDest = trace ? trace->DestLocation - shot->Location : FVector(0, 0, 0);
				// aliceshotdiag2: a short aim (the crosshair ray stopped on
				// something close) - which actors are at that point?
				std::string nearText;
				if (trace && toDest.SizeSquared() < 3000.0f * 3000.0f)
				{
					struct Near { float d; AActor* a; };
					std::vector<Near> nears;
					TArray<UObject*>* objects = UObject::GObjObjects();
					for (int32_t i = 0; objects && i < objects->size(); ++i)
					{
						UObject* const o = objects->at(i);
						if (!o || !o->IsA(AActor::StaticClass()) || o->IsDefaultObject())
							continue;
						AActor* const a = reinterpret_cast<AActor*>(o);
						if (a == shot || a == localPawn || a->WorldInfo != g_currentWorld)
							continue;
						const FVector d = a->Location - trace->DestLocation;
						const float dist = d.SizeSquared();
						if (dist < 500.0f * 500.0f)
							nears.push_back(Near{ dist, a });
					}
					std::sort(nears.begin(), nears.end(), [](const Near& x, const Near& y) { return x.d < y.d; });
					for (size_t i = 0; i < nears.size() && i < 4; ++i)
					{
						AActor* const a = nears[i].a;
						nearText += " | " + ObjectName(a) + " d=" + std::to_string(static_cast<int>(std::sqrt(nears[i].d)))
							+ " hidden=" + (a->bHidden ? "1" : "0") + " collide=" + (a->bCollideActors ? "1" : "0")
							+ " block=" + (a->bBlockActors ? "1" : "0")
							+ (a->bDeleteMe ? " DELETED" : "")
							+ (a->IsA(APawn::StaticClass()) ? " health=" + std::to_string(reinterpret_cast<APawn*>(a)->Health) : std::string());
					}
					if (nears.empty())
						nearText = " | nothing within 500 (world geometry?)";
					{
						const float length = std::sqrt(toDest.SizeSquared());
						const FVector dir = length > 1.0f ? toDest * (1.0f / length) : FVector(0, 0, 0);
						FVector hitLocation(0, 0, 0);
						FTraceHitInfo info{};
						AActor* const hit = NativeActorTrace(localPawn, shot->Location,
							trace->DestLocation + dir * 60.0f, hitLocation, info);
						std::string hitText = " | RAY hit=" + ObjectName(hit);
						if (hit && IsUsableObjectFast(hit))
						{
							const FVector off = hit->Location - hitLocation;
							hitText += " actorFromHit=" + std::to_string(static_cast<int>(std::sqrt(off.SizeSquared())))
								+ " actorAt=" + FormatWorldTraceVector(hit->Location);
						}
						if (info.HitComponent && IsUsableObjectFast(info.HitComponent))
						{
							hitText += " comp=" + ObjectName(info.HitComponent)
								+ " compOwner=" + ObjectName(info.HitComponent->Owner)
								+ " compCenter=" + FormatWorldTraceVector(info.HitComponent->Bounds.Origin)
								+ " bone=" + info.BoneName.ToString();
						}
						hitText += " at=" + FormatWorldTraceVector(hitLocation);
						nearText += hitText;
					}
					// aliceshotdiag5 (31.10 14:12): the ray hits nothing - the aim
					// point is not a crosshair hit but a targeting point. Which?
					if (AAlicePlayerController* const pc = LocalAliceController(localPawn))
					{
						auto npcText = [&](const char* label, const FTargetingNPCInfo& info) {
							std::string text = std::string(" | ") + label + "=" + ObjectName(info.Pawn);
							if (info.Pawn && IsUsableObjectFast(info.Pawn))
							{
								const FVector toPawn = info.LockOnSocketLocation - info.Pawn->Location;
								const FVector toAim = info.LockOnSocketLocation - trace->DestLocation;
								text += " socket=" + FormatWorldTraceVector(info.LockOnSocketLocation)
									+ " socketFromPawn=" + std::to_string(static_cast<int>(std::sqrt(toPawn.SizeSquared())))
									+ " socketFromAim=" + std::to_string(static_cast<int>(std::sqrt(toAim.SizeSquared())))
									+ " pawnAt=" + FormatWorldTraceVector(info.Pawn->Location)
									+ " health=" + std::to_string(info.Pawn->Health)
									+ " paused=" + (info.Pawn->bPauseTick ? "1" : "0");
							}
							return text;
						};
						const FVector reticuleToAim = pc->AimingReticuleLocation - trace->DestLocation;
						const FVector crossToAim = pc->CrossHairLocation - trace->DestLocation;
						nearText += " | reticule=" + ObjectName(pc->AimingReticuleTarget)
							+ " at " + FormatWorldTraceVector(pc->AimingReticuleLocation)
							+ " fromAim=" + std::to_string(static_cast<int>(std::sqrt(reticuleToAim.SizeSquared())))
							+ " cross=" + FormatWorldTraceVector(pc->CrossHairLocation)
							+ " crossFromAim=" + std::to_string(static_cast<int>(std::sqrt(crossToAim.SizeSquared())))
							+ npcText("npc", pc->TargetNPCSocket) + npcText("preNpc", pc->PreTargetNPCSocket);
						// The nearest shared enemy, wherever it is.
						float best = 1e30f;
						AAliceGameKynapsePawn* nearest = nullptr;
						for (const auto& [enemyKey, enemy] : g_sharedEnemyRegistry)
						{
							if (!enemy || !IsLiveUObject(enemy) || enemy->bDeleteMe)
								continue;
							const FVector d = enemy->Location - trace->DestLocation;
							if (d.SizeSquared() < best)
							{
								best = d.SizeSquared();
								nearest = enemy;
							}
						}
						if (nearest)
							nearText += " | nearestEnemy=" + ObjectName(nearest) + " d="
								+ std::to_string(static_cast<int>(std::sqrt(best))) + " at "
								+ FormatWorldTraceVector(nearest->Location) + " health="
								+ std::to_string(nearest->Health) + " hidden=" + (nearest->bHidden ? "1" : "0");
					}
					nearText = " aim=" + FormatWorldTraceVector(trace->DestLocation) + nearText;
				}
				Log("ALICESHOT " + ObjectName(shot->Class) + " speed="
					+ std::to_string(static_cast<int>(std::sqrt(shot->Velocity.SizeSquared())))
					+ " destDist=" + std::to_string(static_cast<int>(std::sqrt(toDest.SizeSquared())))
					+ " flight=" + (trace ? std::to_string(trace->FlightTime) : std::string("-"))
					+ " target=" + targetText + nearText + '.');
			}
		}

		void FillNpcShotState(SharedWorldEventPayload& event, AActor* actor)
		{
			event.hitLocation[0] = actor->Location.X;
			event.hitLocation[1] = actor->Location.Y;
			event.hitLocation[2] = actor->Location.Z;
			if (UAliceGameProjectileTrace* const trace = NpcShotTrace(actor))
			{
				event.flags |= kNpcShotHasTrace;
				event.momentum[0] = trace->DestLocation.X;
				event.momentum[1] = trace->DestLocation.Y;
				event.momentum[2] = trace->DestLocation.Z;
				event.healthMax = static_cast<std::int32_t>(trace->FlightTime * 1000.0f);
				event.damage = NpcShotTargetCode(trace->TargetEnemyActor);
				if (event.damage == 3)
				{
					event.entityKey = SharedKeyForEnemy(
						reinterpret_cast<AAliceGameKynapsePawn*>(trace->TargetEnemyActor),
						SharedEnemyStableKey(reinterpret_cast<AAliceGameKynapsePawn*>(
							trace->TargetEnemyActor)));
				}
			}
			else
			{
				event.momentum[0] = actor->Velocity.X;
				event.momentum[1] = actor->Velocity.Y;
				event.momentum[2] = actor->Velocity.Z;
			}
		}

		void SendNpcShotEvent(SharedWorldEventKind kind, std::int32_t id,
			std::uint64_t key, AActor* actor, const std::string& className,
			std::uint8_t flags = 0)
		{
			SharedWorldEventPayload event{};
			event.kind = kind;
			event.flags = flags;
			event.originActorId = g_config.role == Role::Host ? 1u : 2u;
			event.entityKey = key;
			event.health = id;
			if (actor && kind != kEventNpcShotHeld)
				FillNpcShotState(event, actor);
			else if (actor)
			{
				event.hitLocation[0] = actor->Location.X;
				event.hitLocation[1] = actor->Location.Y;
				event.hitLocation[2] = actor->Location.Z;
			}
			if (kind == kEventNpcShot)
			{
				// A spawn carries the shooter as entityKey.
				event.entityKey = key;
				if (event.damage == 3)
					event.damage = 0;
			}
			if (!className.empty())
				strncpy_s(event.damageType, className.c_str(), _TRUNCATE);
			// shotkey1 (31.10): the receiver drops every world event whose
			// entityKey is 0 - the throw, deflect, held and gone events of a
			// shot never arrived (13:19:40 deflected on the client, nothing
			// on the host). A pseudo key that names the shot.
			if (event.entityKey == 0)
				event.entityKey = 0x5348000000000000ull | static_cast<std::uint32_t>(id);
			QueueSharedWorldEvent(event);
		}

		// Puts a shot on the course an event describes (spawn, throw, deflect).
		std::string ApplyNpcShotState(AActor* shot, AAliceGameKynapsePawn* shooter,
			const SharedWorldEventPayload& event, std::uint64_t targetKey)
		{
			const FVector location(event.hitLocation[0], event.hitLocation[1],
				event.hitLocation[2]);
			const FVector vector(event.momentum[0], event.momentum[1], event.momentum[2]);
			NativeSetActorLocationNoCheck(shot, location);
			if ((event.flags & kNpcShotHasTrace) != 0)
			{
				AActor* const target = NpcShotTargetFromCode(event.damage, targetKey);
				const FVector toDest = vector - location;
				NativeSetActorRotation(shot, RotatorFromDirection(toDest));
				const bool initialised = RunNpcShotTraceInit(shot,
					shooter ? shooter->Weapon : nullptr, vector, target);
				// Some traces (AlignSocketInfinity) take their line from the
				// shooter's socket in init: hold them to the sender's line.
				if (UAliceGameProjectileTrace* const trace = NpcShotTrace(shot))
				{
					trace->DestLocation = vector;
					trace->TargetEnemyActor = target;
					// curveshot1 (10.11 20:4x: the Colossal Ruin's shells flew
					// crooked and broke up on the other screen): a curve-to-the-
					// spot shell (CurveToDest) was given a straight line to the
					// spot here, over the arc its own trace had set. Its trace
					// flies the arc; only its target spot is the sender's.
					if (initialised && trace->IsA(UAliceGameProjectileTrace_CurveToDest::StaticClass()))
					{
						return std::string("curve trace to ") + ObjectName(target);
					}
					const float length = std::sqrt(toDest.SizeSquared());
					const float speed = (std::max)(1.0f,
						(std::max)(std::sqrt(shot->Velocity.SizeSquared()),
							reinterpret_cast<AAliceGameProjectile*>(shot)->Speed));
					if (length > 1.0f)
					{
						shot->Velocity = FVector(toDest.X / length * speed,
							toDest.Y / length * speed, toDest.Z / length * speed);
					}
				}
				return std::string(initialised ? "trace to " : "trace (no init) to ")
					+ ObjectName(target);
			}
			const float speed = std::sqrt(vector.SizeSquared());
			if (speed > 1.0f && shot->IsA(AProjectile::StaticClass()))
			{
				reinterpret_cast<AProjectile*>(shot)->Init(FVector(
					vector.X / speed, vector.Y / speed, vector.Z / speed));
			}
			shot->Velocity = vector;
			NativeSetActorRotation(shot, RotatorFromDirection(vector));
			return "velocity";
		}

		void TickNpcShots()
		{
			if (g_npcShotWorld != g_currentWorld)
			{
				g_npcShotWorld = g_currentWorld;
				g_npcShots.clear();
				g_npcShotIdByActor.clear();
				g_npcShotsPending.clear();
			}
			if (!g_connected || !g_config.sharedEnemyTransforms
				|| g_config.localMirror || WorldTransitionActive())
			{
				g_npcShotsPending.clear();
				return;
			}
			LogAliceShots();
			// New shots (seen in PostBeginPlay; the weapon has aimed them now).
			std::vector<AActor*> pending;
			pending.swap(g_npcShotsPending);
			for (AActor* const actor : pending)
			{
				if (!actor || !IsLiveUObject(actor) || actor->bDeleteMe
					|| g_npcShotIdByActor.count(actor))
				{
					continue;
				}
				APawn* const shooter = actor->Instigator;
				if (!shooter || !IsLiveUObject(shooter)
					|| !shooter->IsA(AAliceGameKynapsePawn::StaticClass()))
				{
					continue;
				}
				auto* const enemy = reinterpret_cast<AAliceGameKynapsePawn*>(shooter);
				const std::uint64_t key = SharedKeyForEnemy(enemy, SharedEnemyStableKey(enemy));
				if (!key)
					continue;
				if (!LocallyDrivesSharedEnemy(key))
				{
					// The replayed copy's own shot: the real one comes as 44.
					RetireShotActor(actor);
					if (g_npcShotLogsLeft > 0)
					{
						--g_npcShotLogsLeft;
						Log("NPCSHOT retired the local shot of the mirrored " + ObjectName(enemy)
							+ ": " + ObjectName(actor) + '.');
					}
					continue;
				}
				const std::int32_t id = (g_config.role == Role::Host ? 0 : 0x40000000)
					| (g_nextNpcShotId++ & 0x3FFFFFFF);
				const bool heldNow = actor->Velocity.SizeSquared() < 100.0f * 100.0f;
				const bool retargeted = !heldNow && RetargetNpcShotToOtherAlice(actor, enemy);
				NpcShotTrack track{};
				track.actor = actor;
				track.lastVelocity = actor->Velocity;
				track.held = heldNow;
				track.everHeld = heldNow;
				track.since = Clock::now();
				track.born = track.since;
				g_npcShots[id] = track;
				g_npcShotIdByActor[actor] = id;
				SendNpcShotEvent(kEventNpcShot, id, key, actor, ObjectName(actor->Class),
					heldNow ? kNpcShotHeldFlag : 0u);
				if (g_npcShotLogsLeft > 0)
				{
					--g_npcShotLogsLeft;
					UAliceGameProjectileTrace* const trace = NpcShotTrace(actor);
					Log("NPCSHOT TX id=" + std::to_string(id) + " " + ObjectName(actor)
						+ " from " + ObjectName(enemy) + ", speed="
						+ std::to_string(static_cast<int>(std::sqrt(actor->Velocity.SizeSquared())))
						+ ", trace=" + ObjectName(trace)
						+ (trace ? ", target=" + ObjectName(trace->TargetEnemyActor)
							+ ", flight=" + std::to_string(trace->FlightTime) : std::string())
						+ (heldNow ? " (in its hand)" : "")
						+ (retargeted ? " -> at the other Alice" : "") + '.');
				}
			}

			// Throws, deflections and ends.
			AAlicePawn* const localPawn = GetLocalPawn();
			const auto now = Clock::now();
			for (auto it = g_npcShots.begin(); it != g_npcShots.end();)
			{
				NpcShotTrack& track = it->second;
				AActor* const actor = track.actor;
				const bool alive = actor && IsLiveUObject(actor) && !actor->bDeleteMe
					&& !(actor->IsA(AAliceGameProjectile::StaticClass())
						&& reinterpret_cast<AAliceGameProjectile*>(actor)->bShuttingDown);
				if (!alive || now - track.since > std::chrono::seconds(15))
				{
					// A held shot that never flew, or a shot deflected here:
					// the copy in the other game goes with it.
					// shotcourse1: every shot this game owned ends in the other game too.
					if (!track.mirrored && !track.visualOnly)
						SendNpcShotEvent(kEventNpcShotGone, it->first, 0, nullptr, std::string());
					if (track.mirrored && track.deflectedHere)
						SendNpcShotEvent(kEventNpcShotGone, it->first, 0, nullptr, std::string());
					if (alive && (track.visualOnly || track.mirrored))
						RetireShotActor(actor);
					g_npcShotIdByActor.erase(actor);
					it = g_npcShots.erase(it);
					continue;
				}
				const FVector velocity = actor->Velocity;
				const float speedSquared = velocity.SizeSquared();
				const float lastSquared = track.lastVelocity.SizeSquared();
				if (track.held && !track.mirrored)
				{
					if (speedSquared >= 100.0f * 100.0f)
					{
						track.held = false;
						track.since = now;
						APawn* const shooter = actor->Instigator;
						if (shooter && IsLiveUObject(shooter)
							&& shooter->IsA(AAliceGameKynapsePawn::StaticClass()))
						{
							RetargetNpcShotToOtherAlice(actor,
								reinterpret_cast<AAliceGameKynapsePawn*>(shooter));
						}
						SendNpcShotEvent(kEventNpcShotDeflect, it->first, 0, actor,
							std::string(), kNpcShotThrown);
						if (g_npcShotLogsLeft > 0)
						{
							--g_npcShotLogsLeft;
							Log("NPCSHOT thrown id=" + std::to_string(it->first) + " speed="
								+ std::to_string(static_cast<int>(std::sqrt(speedSquared))) + '.');
						}
					}
					else if (now >= track.nextHeldSend)
					{
						track.nextHeldSend = now + std::chrono::milliseconds(80);
						track.since = now; // held for as long as the Ruin holds it
						SendNpcShotEvent(kEventNpcShotHeld, it->first, 0, actor, std::string());
					}
					track.lastVelocity = actor->Velocity; // after a re-aim
					++it;
					continue;
				}
				if (!track.visualOnly && !track.deflectedHere && !track.held
					&& speedSquared > 100.0f * 100.0f && lastSquared > 100.0f * 100.0f)
				{
					const float dot = (velocity.X * track.lastVelocity.X
						+ velocity.Y * track.lastVelocity.Y
						+ velocity.Z * track.lastVelocity.Z)
						/ std::sqrt(speedSquared * lastSquared);
					const bool nearLocalAlice = localPawn
						&& (actor->Location - localPawn->Location).SizeSquared() < 600.0f * 600.0f;
					// shotdeflect2 (31.10): the Ruin's AlignSocketInfinity shot turns
					// round on its first frames by itself - 37 ms after the spawn the
					// host called it "deflected" and the other game's copy flew back
					// into the wall. A deflection needs the umbrella out and a shot
					// older than 0.25 s.
					const bool umbrellaOut = localPawn
						&& (localPawn->bInShield || localPawn->bIsDeflectSpinning);
					const bool settled = now - track.born > std::chrono::milliseconds(250);
					if (dot < -0.2f && nearLocalAlice && umbrellaOut && settled)
					{
						track.deflectedHere = true;
						track.since = now;
						SendNpcShotEvent(kEventNpcShotDeflect, it->first, 0, actor, std::string());
						if (g_npcShotLogsLeft > 0)
						{
							--g_npcShotLogsLeft;
							UAliceGameProjectileTrace* const trace = NpcShotTrace(actor);
							Log("NPCSHOT deflected here id=" + std::to_string(it->first)
								+ " " + ObjectName(actor) + " (dot " + std::to_string(dot)
								+ "), now aimed at " + ObjectName(trace ? trace->TargetEnemyActor : nullptr)
								+ '.');
						}
					}
				}
				// The owner of the shot sends its course; the other game follows.
				const bool ownsCourse = (!track.mirrored && !track.visualOnly) || track.deflectedHere;
				if (ownsCourse && !track.held && now >= track.nextCourseSend)
				{
					track.nextCourseSend = now + std::chrono::milliseconds(100);
					SharedWorldEventPayload course{};
					course.kind = kEventNpcShotCourse;
					course.originActorId = g_config.role == Role::Host ? 1u : 2u;
					course.health = it->first;
					course.entityKey = 0x5348000000000000ull | static_cast<std::uint32_t>(it->first);
					course.hitLocation[0] = actor->Location.X;
					course.hitLocation[1] = actor->Location.Y;
					course.hitLocation[2] = actor->Location.Z;
					course.momentum[0] = velocity.X;
					course.momentum[1] = velocity.Y;
					course.momentum[2] = velocity.Z;
					QueueSharedWorldEvent(course);
				}
				track.lastVelocity = velocity;
				++it;
			}
		}

		void OnRemoteNpcShot(const SharedWorldEventPayload& event)
		{
			if (!g_connected || WorldTransitionActive() || !g_currentWorld)
				return;
			const std::int32_t id = event.health;
			if (g_npcShots.count(id))
				return; // a duplicate copy of the event
			// The shooter travels as entityKey.
			AAliceGameKynapsePawn* const enemy = EnemyForSharedKey(event.entityKey);
			// Tunnelled events carry only the class name's hash ("#dt:...").
			UClass* shotClass = event.damageType[0] ? ResolveSharedDamageType(event) : nullptr;
			if (shotClass && ObjectName(shotClass).find("Projectile") == std::string::npos)
				shotClass = nullptr;
			std::string result;
			AActor* shot = nullptr;
			if (!enemy || !IsLiveUObject(enemy) || enemy->bDeleteMe)
				result = "enemy not here";
			else if (!shotClass)
				result = std::string("no class ") + event.damageType;
			else
			{
				const FVector location(event.hitLocation[0], event.hitLocation[1],
					event.hitLocation[2]);
				g_spawningMirroredNpcShot = true;
				shot = NativeSpawn(enemy, shotClass, enemy, FName("None"), location,
					enemy->Rotation, nullptr, true);
				g_spawningMirroredNpcShot = false;
				if (!shot)
					result = "spawn failed";
				else
				{
					shot->Instigator = enemy;
					// shotcourse2 (31.10): the copy follows the owner's course; on its
					// own it hit the floor/walls within 0.5 s (its first line is the
					// hand socket's). It still hits this Alice.
					shot->bCollideWorld = false;
					// shotfx1 (31.10, UE Explorer): the shot's visible part is its
					// ProjFlightEffects particle (P_NPC_Grunt_Projectile1), hung on it
					// by SpawnFlightEffects - the firing weapon calls that, PostBeginPlay
					// does not. A copy spawned here was a shot with no particle: it flew,
					// hit and hurt, but nobody saw it.
					if (shot->IsA(AAliceGameProjectile::StaticClass()))
					{
						auto* const projectile = reinterpret_cast<AAliceGameProjectile*>(shot);
						if (projectile->ProjFlightEffects && projectile->ProjFlightEffectTemplate)
							projectile->SpawnFlightEffects();
					}
					const bool held = (event.flags & kNpcShotHeldFlag) != 0;
					if (held)
					{
						// In the Ruin's hand: no own flight until the throw.
						shot->Velocity = FVector(0.0f, 0.0f, 0.0f);
						shot->Physics = EPhysics::PHYS_None;
						// No touch while held: next to this Alice it exploded on her at
						// once (02:13:57, damage before the throw).
						NativeSetActorCollision(shot, false, false);
						result = "held";
					}
					else
						result = ApplyNpcShotState(shot, enemy, event, 0);
					NpcShotTrack track{};
					track.actor = shot;
					track.lastVelocity = shot->Velocity;
					track.mirrored = true;
					track.held = held;
					track.since = Clock::now();
					g_npcShots[id] = track;
					g_npcShotIdByActor[shot] = id;
					result = "spawned " + ObjectName(shot) + ", " + result;
				}
			}
			if (g_npcShotLogsLeft > 0)
			{
				--g_npcShotLogsLeft;
				Log("NPCSHOT RX id=" + std::to_string(id) + " "
					+ std::string(event.damageType) + ": " + result + '.');
			}
		}

		void OnRemoteNpcShotDeflect(const SharedWorldEventPayload& event)
		{
			const auto found = g_npcShots.find(event.health);
			std::string result = "no such shot here";
			if (found != g_npcShots.end() && found->second.actor
				&& IsLiveUObject(found->second.actor) && !found->second.visualOnly)
			{
				NpcShotTrack& track = found->second;
				AActor* const actor = track.actor;
				APawn* const shooterPawn = actor->Instigator;
				AAliceGameKynapsePawn* const shooter = shooterPawn && IsLiveUObject(shooterPawn)
					&& shooterPawn->IsA(AAliceGameKynapsePawn::StaticClass())
					? reinterpret_cast<AAliceGameKynapsePawn*>(shooterPawn) : nullptr;
				const bool thrown = (event.flags & kNpcShotThrown) != 0;
				if (thrown && track.held)
				{
					actor->Physics = EPhysics::PHYS_Projectile;
					NativeSetActorCollision(actor, true, false);
				}
				if (!thrown)
				{
					// The deflecting machine's shot is the real one now; this
					// one only shows the new course.
					NativeSetActorCollision(actor, false, false);
					track.visualOnly = true;
				}
				result = ApplyNpcShotState(actor, shooter, event,
					event.damage == 3 ? event.entityKey : 0);
				track.lastVelocity = actor->Velocity;
				track.held = false;
				track.since = Clock::now();
				result = (thrown ? "thrown: " : "following the deflection: ") + result;
			}
			static int updateLogs = 60; // own budget: deflections must show
			if (updateLogs > 0)
			{
				--updateLogs;
				Log("NPCSHOT update RX id=" + std::to_string(event.health) + ": " + result + '.');
			}
		}

		void OnRemoteNpcShotHeld(const SharedWorldEventPayload& event)
		{
			const auto found = g_npcShots.find(event.health);
			if (found == g_npcShots.end() || !found->second.actor
				|| !IsLiveUObject(found->second.actor) || !found->second.held)
			{
				return;
			}
			AActor* const actor = found->second.actor;
			NativeSetActorLocationNoCheck(actor, FVector(event.hitLocation[0],
				event.hitLocation[1], event.hitLocation[2]));
			actor->Velocity = FVector(0.0f, 0.0f, 0.0f);
			found->second.since = Clock::now();
		}

		void OnRemoteNpcShotCourse(const SharedWorldEventPayload& event)
		{
			const auto found = g_npcShots.find(event.health);
			if (found == g_npcShots.end() || !found->second.actor
				|| !IsLiveUObject(found->second.actor) || found->second.held)
			{
				return;
			}
			NpcShotTrack& track = found->second;
			// This game owns it (its original, or deflected here): ignore.
			if ((!track.mirrored && !track.visualOnly) || track.deflectedHere)
				return;
			AActor* const actor = track.actor;
			const FVector location(event.hitLocation[0], event.hitLocation[1], event.hitLocation[2]);
			const FVector velocity(event.momentum[0], event.momentum[1], event.momentum[2]);
			// curveshot1: a curve shell keeps its own arc and target spot; it
			// is only put back on the sender's course when it has drifted off
			// by more than 150 units (no teleport every 100 ms, no moved spot).
			UAliceGameProjectileTrace* const courseTrace = NpcShotTrace(actor);
			const bool curveShot = courseTrace
				&& courseTrace->IsA(UAliceGameProjectileTrace_CurveToDest::StaticClass());
			if (curveShot)
			{
				const FVector off(location.X - actor->Location.X, location.Y - actor->Location.Y,
					location.Z - actor->Location.Z);
				if (off.SizeSquared() > 150.0f * 150.0f)
				{
					NativeSetActorLocationNoCheck(actor, location);
					actor->Velocity = velocity;
				}
			}
			else
			{
				NativeSetActorLocationNoCheck(actor, location);
				actor->Velocity = velocity;
			}
			if (!curveShot && velocity.SizeSquared() > 1.0f)
			{
				NativeSetActorRotation(actor, RotatorFromDirection(velocity));
				if (UAliceGameProjectileTrace* const trace = NpcShotTrace(actor))
				{
					trace->DestLocation = FVector(location.X + velocity.X * 2.0f,
						location.Y + velocity.Y * 2.0f, location.Z + velocity.Z * 2.0f);
				}
			}
			if (actor->Physics == EPhysics::PHYS_None && velocity.SizeSquared() > 100.0f * 100.0f)
				actor->Physics = EPhysics::PHYS_Projectile;
			// shotboom1 (10.11, UE Explorer: DoomTankProjectile - a curve to the
			// spot, then a DoomTankRigidBall that blasts 3 s later): a copy flies
			// without world collision (shotcourse2), so the Colossal Ruin's
			// shells and the rain never landed here - no blast, no doll-head
			// bomb. Once a ball-dropping shell is coming down, it hits the
			// world again and lands through the game's own code.
			if (!actor->bCollideWorld && velocity.Z < -200.0f
				&& actor->IsA(AAliceGameProjectile::StaticClass())
				&& reinterpret_cast<AAliceGameProjectile*>(actor)->RigidBallClass)
			{
				actor->bCollideWorld = true;
				static int landLogs = 20;
				if (landLogs > 0)
				{
					--landLogs;
					Log("NPCSHOT copy id=" + std::to_string(event.health) + " " + ObjectName(actor)
						+ " is coming down: it collides with the world again (shotboom1).");
				}
			}
			track.lastVelocity = velocity;
			track.since = Clock::now();
			if (track.visualOnly)
			{
				static int courseLogs = 40;
				if (courseLogs > 0)
				{
					--courseLogs;
					Log("NPCSHOT course of a deflected shot id=" + std::to_string(event.health)
						+ " at " + FormatWorldTraceVector(location) + ", speed="
						+ std::to_string(static_cast<int>(std::sqrt(velocity.SizeSquared())))
						+ ", hidden=" + (actor->bHidden ? "1" : "0") + '.');
				}
			}
		}

		void OnRemoteNpcShotGone(const SharedWorldEventPayload& event)
		{
			const auto found = g_npcShots.find(event.health);
			if (found == g_npcShots.end())
				return;
			// shotboom1: the other game's shell landed and blew up; a copy of a
			// ball-dropping shell that has not landed here yet lands where it
			// is (AliceGameProjectile.Explode, native: blast, damage to this
			// Alice, the ball) instead of just vanishing.
			AActor* const goneActor = found->second.actor;
			if (goneActor && IsLiveUObject(goneActor) && !goneActor->bDeleteMe
				&& found->second.mirrored && !found->second.held
				&& goneActor->IsA(AAliceGameProjectile::StaticClass())
				&& reinterpret_cast<AAliceGameProjectile*>(goneActor)->RigidBallClass)
			{
				static UFunction* const explode =
					FindFunctionSafe("Function AliceGame.AliceGameProjectile.Explode");
				AAliceGameProjectile_execExplode_Params params{};
				params.HitLocation = goneActor->Location;
				params.HitNormal = FVector(0.0f, 0.0f, 1.0f);
				params.TargetActor = nullptr;
				const bool exploded = explode && InvokeNativeFunction(goneActor, explode, params);
				static int boomLogs = 30;
				if (boomLogs > 0)
				{
					--boomLogs;
					Log("NPCSHOT copy id=" + std::to_string(event.health) + " " + ObjectName(goneActor)
						+ " lands with the other game's shell: explode=" + (exploded ? "yes" : "no")
						+ ", ball=" + ObjectName(reinterpret_cast<AAliceGameProjectile*>(goneActor)->RigidBall)
						+ " (shotboom1).");
				}
				if (exploded)
				{
					g_npcShotIdByActor.erase(goneActor);
					g_npcShots.erase(found);
					return;
				}
			}
			if (found->second.actor && IsLiveUObject(found->second.actor))
				RetireShotActor(found->second.actor);
			g_npcShotIdByActor.erase(found->second.actor);
			g_npcShots.erase(found);
		}

		// ---- Shield hits by the other Alice, replayed natively (kind 48) --
		// Ghidra (Steam): a weapon hit on a shield runs FUN_00ccfa40 (melee,
		// MeleeAttackActorList) or FUN_00cd0770 (radius, RadiusAttackActorList)
		// - thiscall(weapon, targetPawn, ShieldTestResult*). They register the
		// hit, knock the enemy back on its shield (GetShieldKnockBackDist/
		// TimeScale, controller +0x5dd = 3), call Pawn.ShieldDamage, play the
		// shield effect and hand the AI its reaction package (Kynapse
		// controller vtable +0x4fc - the hobby horse / teapot stun). On a copy
		// whose AI runs in the other game all of that happened to a paused
		// copy: the Ruin never staggered for the second Alice. Her shield hit
		// is sent (48) and the game that drives the enemy runs the same native
		// with her presentation weapon (same class) as the weapon.
		constexpr SharedWorldEventKind kEventShieldHit = static_cast<SharedWorldEventKind>(48);
		bool IsExecutableAddress(uintptr_t address);

		uintptr_t ShieldHitNative(bool radius)
		{
			// Ghidra addresses (image base 0x400000); EA (build 2) not known yet.
			const int build = static_cast<int>(Addresses::GetBuild());
			uintptr_t exe = 0;
			if (build == 3)
				exe = radius ? 0xcd0770 : 0xccfa40;
			// EA: wrapper FUN_00c93880 (name DAT_01505b08); its callers in the
			// same order as Steam's - melee FUN_00d3b7c0 (push ebp, called
			// from FUN_00d45cc0 like Steam's from FUN_00cd86d0), radius
			// FUN_00d3c690 (push ebx, called from FUN_00d45680 like Steam's
			// from FUN_00cd8090).
			else if (build == 2)
				exe = radius ? 0xd3c690 : 0xd3b7c0;
			if (!exe)
				return 0;
			const uintptr_t address = reinterpret_cast<uintptr_t>(GetModuleHandleW(nullptr))
				+ (exe - 0x400000);
			if (!IsExecutableAddress(address))
				return 0;
			// Prologues from the decompile: push ebp / push ebx.
			const std::uint8_t first = *reinterpret_cast<const std::uint8_t*>(address);
			if (first != (radius ? 0x53 : 0x55))
				return 0;
			return address;
		}

		// shieldreact1: the full natives above also run the Alice/camera side
		// through the instigator's controller (Steam broke, 29.10). The single
		// player recording (enemyrec, 30.10) shows what really opens a Ruin:
		// Pawn.ShieldDamage with the hobby horse / teapot (-> Grunt_Damage_H,
		// arm shield down) or with its own deflected shot (DmgType_DoomGrunt1,
		// by the Ruin itself -> Grunt_Damage_H2_ArmOff). The horse, the teapot
		// and the deflected shot never call PlayShieldPhysicsMaterialEffect, so
		// the sender now watches ShieldDamage on copies this game does not
		// drive, and the driving game runs ONLY the AI reaction - the tail of
		// FUN_00ccfa40/cd0770: Kynapse controller vtable +0x4fc(packageIndex,
		// ShieldInfo.CanBreakStrikBack), packageIndex = ShieldInfo.ReactBy<X>.
		enum ShieldReactKind : std::uint8_t
		{
			kReactNone = 0, kReactVorpal = 1, kReactHorse = 2, kReactPepper = 3,
			kReactPepperCharged = 4, kReactTeapot = 5, kReactDeflect = 6,
		};

		std::uint8_t ShieldReactKindFor(const std::string& typeName, bool byPlayer)
		{
			if (!byPlayer)
				return kReactDeflect;
			if (typeName.find("HobbyHorse") != std::string::npos)
				return kReactHorse;
			if (typeName.find("Teapot") != std::string::npos)
				return kReactTeapot;
			if (typeName.find("PepperGrinder") != std::string::npos)
				return typeName.find("Charge") != std::string::npos ? kReactPepperCharged : kReactPepper;
			if (typeName.find("Vorpal") != std::string::npos)
				return kReactVorpal;
			return kReactNone;
		}

		const char* ShieldReactName(std::uint8_t kind)
		{
			switch (kind)
			{
			case kReactVorpal: return "vorpal";
			case kReactHorse: return "horse";
			case kReactPepper: return "pepper";
			case kReactPepperCharged: return "pepper-charged";
			case kReactTeapot: return "teapot";
			case kReactDeflect: return "deflect";
			default: return "none";
			}
		}

		int32_t ShieldReactPackage(const FShieldComponentInfo& info, std::uint8_t kind)
		{
			switch (kind)
			{
			case kReactVorpal: return info.ReactByVorpalBladePackageIndex;
			case kReactHorse: return info.ReactByHobbyHorsePackageIndex;
			case kReactPepper: return info.ReactByPepperGrinderPackageIndex;
			case kReactPepperCharged: return info.ReactByPepperGrinderChargedPackageIndex;
			case kReactTeapot: return info.ReactByTeaCannonPackageIndex;
			case kReactDeflect: return info.ReactByDeflectProjectilePackageIndex;
			default: return -1;
			}
		}

		// ProcessEvent hook (before): Pawn.ShieldDamage on an enemy copy.
		void ObserveLocalShieldHit(UObject* object, UFunction* function, const void* parameters)
		{
			if (!g_connected || !g_config.sharedEnemyTransforms || g_config.localMirror
				|| !parameters || !object || !function)
			{
				return;
			}
			static std::unordered_map<const UFunction*, bool> isShieldDamage;
			auto cached = isShieldDamage.find(function);
			if (cached == isShieldDamage.end())
				cached = isShieldDamage.emplace(function,
					function->GetName() == "ShieldDamage").first;
			if (!cached->second || !object->IsA(AAliceGameKynapsePawn::StaticClass()))
				return;
			auto* const enemy = reinterpret_cast<AAliceGameKynapsePawn*>(object);
			if (enemy->ShieldComponentsArray.size() <= 0)
				return;
			const auto* const value = reinterpret_cast<const APawn_eventShieldDamage_Params*>(parameters);
			AAlicePawn* const localPawn = GetLocalPawn();
			if (!localPawn)
				return;
			const bool byPlayer = value->InstigatedBy && value->InstigatedBy == localPawn->Controller;
			// Something else than this Alice or a shot: not ours to send.
			bool byEnemyShot = false;
			if (!byPlayer && value->InstigatedBy && value->InstigatedBy->Pawn
				&& value->InstigatedBy->Pawn->IsA(AAliceGameKynapsePawn::StaticClass()))
			{
				byEnemyShot = true;
			}
			if (!byPlayer && !byEnemyShot)
				return;
			const std::string typeName = value->DamageType ? ObjectName(value->DamageType) : std::string();
			const std::uint8_t kind = ShieldReactKindFor(typeName, byPlayer);
			if (kind == kReactNone)
				return;
			const std::uint64_t key = SharedKeyForEnemy(enemy, SharedEnemyStableKey(enemy));
			// The host's Alice attacking a shield counts as an attack on it.
			if (key && byPlayer && g_config.role == Role::Host)
				RegisterHostEnemyAggroDamage(key, 1, 1);
			if (!key || LocallyDrivesSharedEnemy(key))
				return;
			// One swing / one shot = one reaction.
			static std::unordered_map<std::uint64_t, Clock::time_point> lastSent;
			const auto now = Clock::now();
			auto& last = lastSent[key];
			if (last.time_since_epoch().count() != 0 && now - last < std::chrono::milliseconds(300))
				return;
			last = now;
			SharedWorldEventPayload event{};
			event.kind = kEventShieldHit;
			event.originActorId = g_config.role == Role::Host ? 1u : 2u;
			event.entityKey = key;
			event.health = -1;
			event.flags = kind;
			// The shields this game saw raised when the hit landed.
			std::int32_t seenRaised = 0;
			for (int32_t i = 0; i < enemy->ShieldComponentsArray.size() && i < 31; ++i)
			{
				if (enemy->ShieldComponentsArray.at(i).bInShield)
					seenRaised |= 1 << i;
			}
			event.healthMax = seenRaised;
			event.hitLocation[0] = value->HitLocation.X;
			event.hitLocation[1] = value->HitLocation.Y;
			event.hitLocation[2] = value->HitLocation.Z;
			strncpy_s(event.damageType, typeName.c_str(), _TRUNCATE);
			QueueSharedWorldEvent(event);
			static int logsLeft = 60;
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("SHIELDHIT TX " + ObjectName(enemy) + ' ' + ShieldReactName(kind)
					+ " by " + typeName + '.');
			}
		}

		void OnRemoteShieldHit(const SharedWorldEventPayload& event)
		{
			if (WorldTransitionActive())
				return;
			const std::uint8_t kind = event.flags;
			AAliceGameKynapsePawn* const enemy = EnemyForSharedKey(event.entityKey);
			// The client attacking a shield counts as an attack on it (focus).
			if (g_config.role == Role::Host && event.originActorId == 2 && kind != kReactDeflect)
				RegisterHostEnemyAggroDamage(event.entityKey, 2, 1);
			std::string result;
			if (!enemy || !IsLiveUObject(enemy) || enemy->bDeleteMe || enemy->Health <= 0)
				result = "enemy not here";
			else if (!LocallyDrivesSharedEnemy(event.entityKey))
				result = "this game does not drive it";
			else if (kind == kReactNone || kind > kReactDeflect)
				result = "unknown reaction";
			else if (!enemy->Controller || !IsLiveUObject(enemy->Controller)
				|| !enemy->Controller->IsA(AAliceGameKynapseAIController::StaticClass()))
			{
				result = "no Kynapse controller";
			}
			else
			{
				// The shield: the one the hit named, else a raised one that has a
				// reaction for this weapon, else any that has one.
				const int32_t count = enemy->ShieldComponentsArray.size();
				int32_t chosen = -1;
				if (event.health >= 0 && event.health < count
					&& ShieldReactPackage(enemy->ShieldComponentsArray.at(event.health).ShieldInfo, kind) >= 0)
				{
					chosen = event.health;
				}
				// shieldreact2: only a RAISED shield reacts (as in single player:
				// the horse stuns only when the melee arm shield is up, and that
				// shield drops). A reaction played for a lowered one (shieldreact1
				// fallback) showed the stun anim but left the front shield up -
				// no damage got through. Raised = here, or in the sender's game.
				for (int pass = 0; chosen < 0 && pass < 1; ++pass)
				{
					for (int32_t i = 0; i < count; ++i)
					{
						const FShieldPara& para = enemy->ShieldComponentsArray.at(i);
						const bool seenRaised = i < 31 && (event.healthMax & (1 << i)) != 0;
						if (!para.bInShield && !seenRaised)
							continue;
						if (ShieldReactPackage(para.ShieldInfo, kind) >= 0)
						{
							chosen = i;
							break;
						}
					}
				}
				if (chosen < 0)
					result = "no shield reacts to it";
				else
				{
					const FShieldPara& para = enemy->ShieldComponentsArray.at(chosen);
					const int32_t package = ShieldReactPackage(para.ShieldInfo, kind);
					const int32_t flag = para.ShieldInfo.CanBreakStrikBack ? 1 : 0;
					void* const controller = enemy->Controller;
					void** const vtable = *reinterpret_cast<void***>(controller);
					void* const react = vtable ? vtable[0x4fc / 4] : nullptr;
					if (!react || !IsExecutableAddress(reinterpret_cast<uintptr_t>(react)))
						result = "reaction slot not executable";
					else
					{
						using ReactFn = void(__fastcall*)(void* controller, void* edx,
							int32_t package, int32_t flag);
						DiagBegin("shieldreact", enemy, react, ShieldReactName(kind));
						reinterpret_cast<ReactFn>(react)(controller, nullptr, package, flag);
						DiagEnd("shieldreact", enemy);
						result = "reacted shield " + std::to_string(chosen) + " package "
							+ std::to_string(package) + " flag " + std::to_string(flag);
					}
				}
			}
			static int logsLeft = 60;
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("SHIELDHIT RX key=" + SharedWorldKeyText(event.entityKey) + ' '
					+ ShieldReactName(kind) + ": " + result + '.');
			}
		}

		// ---- Enemy effects run by the AI (kind 49) -----------------------
		// The co-op recording (30.10): the driving game's Ruin calls
		// ToggleLoopParticle / ToggleLoopSound (the shot glowing in its hand
		// before the throw), PlayParticleEffectFromSphinxSequence and
		// ToggleSkeletalControl from its Kynapse/Sphinx sequences; the other
		// game's copy (AI paused) never did - no shot in the hand, missing
		// effects, skeletal controls left in their start state. Sent from the
		// driven copy, replayed on the copy the other game shows.
		constexpr SharedWorldEventKind kEventEnemyFx = static_cast<SharedWorldEventKind>(49);
		enum EnemyFxOp : std::uint8_t
		{
			kFxLoopParticle = 1, kFxLoopSound = 2, kFxSphinxParticle = 3, kFxSkelControl = 4,
			kFxDeathHide = 5, kFxBranch = 6,
		};
		bool g_applyingRemoteEnemyFx = false;
		// deathfx1 (31.10 13:32:56): the dead Mini Grunt dissolves through its
		// Sphinx death sequence (particle, then SetHidden) on the game that
		// drove it. The host forgets a dead enemy's aggro, so it believed it
		// drove every dead enemy: it threw the client's death particle away
		// ("this game drives it") and its paused copy never hid - the idle
		// body left behind. For a dead enemy the driver is the game that
		// drove it while it lived; the driver's hide is sent too.
		bool DrivesEnemyFx(std::uint64_t key, AAliceGameKynapsePawn* enemy)
		{
			if (enemy && enemy->Health <= 0)
				return g_drivenWhileAlive[enemy];
			return LocallyDrivesSharedEnemy(key);
		}
		struct DeathHideSend
		{
			int sent = 0;
			Clock::time_point last{};
		};
		std::unordered_map<AAliceGameKynapsePawn*, DeathHideSend> g_deathHideSent;
		std::unordered_set<AAliceGameKynapsePawn*> g_deathHidden;

		void HideDeadEnemyCopy(AAliceGameKynapsePawn* enemy)
		{
			if (!enemy || enemy->Health > 0 || g_deathHidden.count(enemy))
				return;
			g_deathHidden.insert(enemy);
			StopReplayedLoopsFor(enemy, true);
			NativeSetActorHidden(enemy, true);
			NativeSetActorCollision(enemy, false, false);
			static int logsLeft = 40;
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("DEATHHIDE RX " + ObjectName(enemy) + ": the driver hid its dead body, hidden here too.");
			}
		}

		// branch1 (31.10 16:16, shield Madcap): the weapon-stuck pose is not
		// a config animation - the Sphinx sequence sets the pawn's
		// SphinxEventAnimTreeBranchIndex and the AnimTree (BlendByBlendingBranch)
		// switches to Branch3 (MadCap_Shield_Attack_C looping) until it is set
		// back. The copy never got it (no stuck pose there), and a copy taken
		// over while on Branch3 kept looping it with its AI waiting (broken).
		// The driver sends the index on each change and once a second; a game
		// that starts driving puts the enemy back on its usual branch (the one
		// it spent most time on).
		struct EnemyBranchState
		{
			int sent = -1;
			Clock::time_point sentAt{};
			bool wasDriven = false;
			int current = -1;
			Clock::time_point currentSince{};
			std::unordered_map<int, float> seconds;
			Clock::time_point lastSample{};
			// branchhold1 (copy): a received switch back to the resting
			// branch, waiting for the recovery animation to start here.
			int pending = -1;
			Clock::time_point pendingUntil{};
		};
		std::unordered_map<AAliceGameKynapsePawn*, EnemyBranchState> g_enemyBranch;
		UAnimNodeSequence* FindDominantOneShotSequence(USkeletalMeshComponent* component);

		void TickEnemyBranch(std::uint64_t key, AAliceGameKynapsePawn* enemy, bool driven, Clock::time_point now)
		{
			if (!key || enemy->Health <= 0)
				return;
			EnemyBranchState& state = g_enemyBranch[enemy];
			const int branch = enemy->SphinxEventAnimTreeBranchIndex;
			if (branch != state.current)
			{
				state.current = branch;
				state.currentSince = now;
			}
			if (state.lastSample != Clock::time_point{})
				state.seconds[branch] += std::chrono::duration<float>(now - state.lastSample).count();
			state.lastSample = now;
			// branch2 (31.10 18:47, Ice Snark): its "usual" branch is 1
			// (under the ground, where it waits); taken over above ground on
			// branch 0, it was put back under - and the client crashed 3 s
			// later. Only a branch held for more than 4 s (stuck) is reset.
			if (driven && !state.wasDriven && !state.seconds.empty()
				&& now - state.currentSince > std::chrono::seconds(4))
			{
				// Taken over: back to its resting branch.
				int usual = branch;
				float best = -1.0f;
				for (const auto& [index, time] : state.seconds)
					if (time > best)
					{
						best = time;
						usual = index;
					}
				if (usual != branch)
				{
					enemy->SphinxEventAnimTreeBranchIndex = usual;
					Log("BRANCH " + ObjectName(enemy) + " taken over on branch " + std::to_string(branch)
						+ ": back to its usual branch " + std::to_string(usual) + '.');
				}
			}
			state.wasDriven = driven;
			if (driven)
				state.pending = -1;
			else if (state.pending >= 0)
			{
				// branchhold1: apply once the driver's recovery animation
				// plays here (or after 0.4 s at most).
				UAnimNodeSequence* const oneShot = enemy->Mesh && IsUsableObjectFast(enemy->Mesh)
					? FindDominantOneShotSequence(enemy->Mesh) : nullptr;
				if (oneShot || now >= state.pendingUntil)
				{
					enemy->SphinxEventAnimTreeBranchIndex = state.pending;
					static int logsLeft = 30;
					if (logsLeft > 0)
					{
						--logsLeft;
						Log("BRANCH " + ObjectName(enemy) + " back to branch " + std::to_string(state.pending)
							+ (oneShot ? " with its one-shot animation (branchhold2)." : " after the wait (branchhold2)."));
					}
					state.pending = -1;
				}
			}
			if (!driven)
				return;
			const int now_branch = enemy->SphinxEventAnimTreeBranchIndex;
			if (now_branch == state.sent && now - state.sentAt < std::chrono::seconds(1))
				return;
			const bool changed = now_branch != state.sent;
			state.sent = now_branch;
			state.sentAt = now;
			SharedWorldEventPayload event{};
			event.kind = kEventEnemyFx;
			event.originActorId = g_config.role == Role::Host ? 1u : 2u;
			event.entityKey = key;
			event.flags = kFxBranch;
			event.health = now_branch;
			QueueSharedWorldEvent(event);
			static int logsLeft = 60;
			if (changed && logsLeft > 0)
			{
				--logsLeft;
				Log("BRANCH TX " + ObjectName(enemy) + " anim branch " + std::to_string(now_branch) + '.');
			}
		}

		int UsualEnemyBranch(AAliceGameKynapsePawn* enemy)
		{
			const auto found = g_enemyBranch.find(enemy);
			if (found == g_enemyBranch.end() || found->second.seconds.empty())
				return enemy->SphinxEventAnimTreeBranchIndex;
			int usual = enemy->SphinxEventAnimTreeBranchIndex;
			float best = -1.0f;
			for (const auto& [index, time] : found->second.seconds)
				if (time > best)
				{
					best = time;
					usual = index;
				}
			return usual;
		}

		bool EnemyMidAction(AAliceGameKynapsePawn* enemy)
		{
			if (!enemy || enemy->Health <= 0)
				return false;
			if (enemy->SphinxEventAnimTreeBranchIndex != UsualEnemyBranch(enemy))
				return true;
			// stunfly1 (08.11, Drifting Ruin): knocked out of the air it falls,
			// lands and should lie stunned - but 3 s after landing (19:59:01)
			// the host's aggro nudge (a fake damage stimulus) told it it had
			// been hit, and it played Aglie_Landing again instead of its stun,
			// on both games. A flyer that is not flying (falling or down on
			// the ground) and anything falling counts as busy: no nudge and
			// no target switch until it is back up.
			{
				const auto physics = enemy->Physics;
				if (physics == EPhysics::PHYS_Falling)
					return true;
				static UClass* const flyerClass = AAliceGameKynapseFlyPawn::StaticClass();
				if (flyerClass && enemy->IsA(flyerClass) && physics != EPhysics::PHYS_Flying
					&& physics != EPhysics::PHYS_None)
				{
					return true;
				}
			}
			if (enemy->AnimBlendNodes.size() > 0)
			{
				UAliceGameAnimNode_BlendBase* const node = enemy->AnimBlendNodes.at(0);
				if (node && IsUsableObjectFast(node) && node->bIsPlayingCustomAnim)
					return true;
			}
			return false;
		}

		// frozen1 (31.10 18:35, Ice Snark): its freezing attack locks this
		// Alice in ice (AlicePawn.bIsFrozen, FrozenLoopPS) - only in her own
		// game; the other player saw her stand there without the ice. The
		// frozen state is sent (kind 52, on change and every second) and the
		// other game shows the same effect on its copy of her.
		constexpr std::uint64_t kAliceFrozenKey = 0x46524F5A454E0001ull;
		bool g_localFrozenSent = false;
		Clock::time_point g_localFrozenSentAt{};
		bool g_remoteFrozenShown = false;

		// hairsync1 (31.10 22:00, single-player HAIRREC): the playable Alice's
		// hair settings are not fixed - her own script changes them all the
		// time: running/turning raise PerturbAmplitude (0 -> 3260), a wind
		// volume gives Force (200,500,-980) + damping 8, floating gives Force
		// (0,0,1020) + damping 2, falling/dodging Force 0, amplitude 1000,
		// period 5, damping 0. On the proxy that script never runs (no
		// controller, no movement), so her hair kept one setting and fell
		// differently. Each game now sends its own Alice's live values (kind
		// 53, ~10 times a second while they change) and the other game puts
		// them on the proxy's hair right before its hair step.
		constexpr std::uint64_t kAliceHairKey = 0x4841495253594E31ull; // "HAIRSYN1"
		struct HairWire
		{
			float force[3];
			float amplitude[3];
			float period[3];
			float spatial[3];
			float phase[3];
			float damping;
		};
		static_assert(sizeof(HairWire) <= sizeof(SharedWorldEventPayload::damageType),
			"hair values must fit the event");
		struct RemoteHairParams
		{
			bool valid = false;
			HairWire wire{};
			std::int32_t iteration = 1;
			Clock::time_point receivedAt{};
		} g_remoteHairParams;

		void TickHairParamRelay(Clock::time_point now)
		{
			AAlicePawn* const alice = GetLocalPawn();
			if (!alice || !IsUsableObjectFast(alice) || !alice->HairComponent
				|| !IsUsableObjectFast(alice->HairComponent))
			{
				return;
			}
			const UHairComponent* const h = alice->HairComponent;
			HairWire wire{};
			auto put = [](float* out, const FVector& v) { out[0] = v.X; out[1] = v.Y; out[2] = v.Z; };
			put(wire.force, h->Force);
			put(wire.amplitude, h->PerturbAmplitude);
			put(wire.period, h->PerturbTemporalPeriod);
			put(wire.spatial, h->PerturbSpatialPeriod);
			put(wire.phase, h->PerturbPhaseShift);
			wire.damping = h->Damping;
			static HairWire lastSent{};
			static std::int32_t lastIteration = -1;
			static Clock::time_point lastSentAt{};
			bool changed = h->Iteration != lastIteration;
			const float* const a = reinterpret_cast<const float*>(&wire);
			const float* const b = reinterpret_cast<const float*>(&lastSent);
			for (std::size_t i = 0; i < sizeof(HairWire) / sizeof(float) && !changed; ++i)
				changed = std::fabs(a[i] - b[i]) > 0.5f;
			if (changed ? now - lastSentAt < std::chrono::milliseconds(100)
				: now - lastSentAt < std::chrono::seconds(1))
			{
				return;
			}
			lastSent = wire;
			lastIteration = h->Iteration;
			lastSentAt = now;
			SharedWorldEventPayload event{};
			event.kind = static_cast<SharedWorldEventKind>(53);
			event.entityKey = kAliceHairKey;
			event.originActorId = g_config.role == Role::Host ? 1u : 2u;
			// hairsync2: numeric fields only - the text field (damageType)
			// arrived empty (all zeros: no gravity, no damping, the proxy's
			// hair floated, 22:16:52). Force in hitLocation, amplitude in
			// momentum, damping x1000 in health, period X/Y x100 in
			// healthMax (16 bits each), iteration + period Z x100 in damage.
			auto centi = [](float v)
			{
				const float c = std::round(v * 100.0f);
				return static_cast<std::uint32_t>((std::max)(0.0f, (std::min)(65535.0f, c)));
			};
			event.hitLocation[0] = wire.force[0];
			event.hitLocation[1] = wire.force[1];
			event.hitLocation[2] = wire.force[2];
			event.momentum[0] = wire.amplitude[0];
			event.momentum[1] = wire.amplitude[1];
			event.momentum[2] = wire.amplitude[2];
			event.health = static_cast<std::int32_t>(std::round(wire.damping * 1000.0f));
			event.healthMax = static_cast<std::int32_t>(centi(wire.period[0])
				| (centi(wire.period[1]) << 16));
			event.damage = static_cast<std::int32_t>((static_cast<std::uint32_t>(h->Iteration) & 0xFFu)
				| (centi(wire.period[2]) << 8));
			QueueSharedWorldEvent(event);
		}

		void OnRemoteHairParams(const SharedWorldEventPayload& event)
		{
			const bool first = !g_remoteHairParams.valid;
			HairWire& w = g_remoteHairParams.wire;
			w.force[0] = event.hitLocation[0];
			w.force[1] = event.hitLocation[1];
			w.force[2] = event.hitLocation[2];
			w.amplitude[0] = event.momentum[0];
			w.amplitude[1] = event.momentum[1];
			w.amplitude[2] = event.momentum[2];
			w.damping = static_cast<float>(event.health) / 1000.0f;
			const std::uint32_t xy = static_cast<std::uint32_t>(event.healthMax);
			const std::uint32_t packed = static_cast<std::uint32_t>(event.damage);
			w.period[0] = static_cast<float>(xy & 0xFFFFu) / 100.0f;
			w.period[1] = static_cast<float>(xy >> 16) / 100.0f;
			w.period[2] = static_cast<float>(packed >> 8) / 100.0f;
			const std::int32_t iteration = static_cast<std::int32_t>(packed & 0xFFu);
			g_remoteHairParams.iteration = iteration > 0 && iteration < 64 ? iteration : 1;
			static int rxLogs = 3;
			if (rxLogs > 0)
			{
				--rxLogs;
				Log("HAIRSYNC RX force=(" + std::to_string(w.force[0]) + ',' + std::to_string(w.force[1])
					+ ',' + std::to_string(w.force[2]) + ") damping=" + std::to_string(w.damping)
					+ " period=(" + std::to_string(w.period[0]) + ',' + std::to_string(w.period[1])
					+ ',' + std::to_string(w.period[2]) + ") iteration=" + std::to_string(iteration) + '.');
			}
			g_remoteHairParams.receivedAt = Clock::now();
			g_remoteHairParams.valid = true;
			if (first)
				Log("HAIRSYNC the other player's live hair values arrive: the proxy's hair follows them.");
		}

		// Right before the proxy's hair step (after the preset and base sync,
		// which still set template, length and physics for her dress).
		void ApplyRemoteHairParams(AAlicePawn* remote)
		{
			if (!remote || !g_remoteHairParams.valid
				|| Clock::now() - g_remoteHairParams.receivedAt > std::chrono::seconds(3))
			{
				return;
			}
			UHairComponent* const hair = remote->HairComponent;
			if (!hair || !IsUsableObjectFast(hair))
				return;
			const HairWire& w = g_remoteHairParams.wire;
			auto vec = [](const float* v) { return FVector(v[0], v[1], v[2]); };
			for (const float f : { w.force[0], w.force[1], w.force[2], w.amplitude[0],
				w.amplitude[1], w.amplitude[2], w.damping })
			{
				if (!std::isfinite(f) || std::fabs(f) > 100000.0f)
					return;
			}
			hair->Force = vec(w.force);
			hair->PerturbAmplitude = vec(w.amplitude);
			if (w.period[0] <= 0.0f && w.period[1] <= 0.0f && w.period[2] <= 0.0f)
				return; // not real values (an empty event)
			hair->PerturbTemporalPeriod = vec(w.period);
			hair->Damping = w.damping;
			hair->Iteration = g_remoteHairParams.iteration;
		}

		void TickAliceFrozenRelay(Clock::time_point now)
		{
			AAlicePawn* const alice = GetLocalPawn();
			if (!alice || !IsUsableObjectFast(alice))
				return;
			const bool frozen = alice->bIsFrozen != 0;
			if (frozen == g_localFrozenSent && (!frozen || now - g_localFrozenSentAt < std::chrono::seconds(1)))
				return;
			const bool changed = frozen != g_localFrozenSent;
			g_localFrozenSent = frozen;
			g_localFrozenSentAt = now;
			SharedWorldEventPayload event{};
			event.kind = static_cast<SharedWorldEventKind>(52);
			event.entityKey = kAliceFrozenKey;
			event.originActorId = g_config.role == Role::Host ? 1u : 2u;
			event.flags = frozen ? 1u : 0u;
			QueueSharedWorldEvent(event);
			if (changed)
				Log(std::string("FROZEN TX this Alice is ") + (frozen ? "frozen." : "free again."));
		}

		// binkskip1 (01.11 17:21, request): the animated cutscenes (Bink
		// movies, SeqAct_PlayBinkMovie - e.g. Chapter1_L1_Cin_115) are skipped
		// with Space like a Matinee but are not one, so CUTSCENESKIP never saw
		// them: one player skipped, the other watched on and the games came
		// apart. When this game's movie ends early (skipped) the other game
		// stops the same movie through its Stop input; one that has not
		// started there yet is stopped as soon as it starts (20 s).
		bool g_applyingRemoteBinkStop = false;
		std::unordered_map<std::uint64_t, Clock::time_point> g_localBinkStartedAt;
		std::unordered_map<std::uint64_t, Clock::time_point> g_pendingBinkStops;
		std::unordered_set<std::uint64_t> g_remoteStoppedBinks;
		int g_binkEpochSeen = 0;

		USequenceOp* FindBinkMovieAction(std::uint64_t key)
		{
			if (key == 0)
				return nullptr;
			TArray<UObject*>* objects = UObject::GObjObjects();
			if (!objects)
				return nullptr;
			for (int32_t index = 0; index < objects->size(); ++index)
			{
				UObject* object = objects->at(index);
				if (!object || !object->IsA(USeqAct_PlayBinkMovie::StaticClass())
					|| !IsLiveUObject(object) || SequenceActionStableKey(object) != key)
				{
					continue;
				}
				return reinterpret_cast<USequenceOp*>(object);
			}
			return nullptr;
		}

		void StopLocalBinkMovie(USequenceOp* op, std::uint64_t key, const char* why)
		{
			g_remoteStoppedBinks.insert(key);
			g_applyingRemoteBinkStop = true;
			const bool stopped = NativeForceActivateSequenceInput(op, 1); // "Stop"
			g_applyingRemoteBinkStop = false;
			Log(std::string("BINKSKIP stopped ") + ObjectName(op) + " (" + why + "), key="
				+ SharedWorldKeyText(key) + (stopped ? "." : ": the Stop input refused."));
		}

		void DropStaleBinkState()
		{
			if (g_binkEpochSeen == g_skipEpoch.load())
				return;
			g_binkEpochSeen = g_skipEpoch.load();
			g_pendingBinkStops.clear();
			g_localBinkStartedAt.clear();
			g_remoteStoppedBinks.clear();
		}

		void OnRemoteBinkStop(const SharedWorldEventPayload& event)
		{
			DropStaleBinkState();
			const std::uint64_t key = event.entityKey;
			USequenceOp* const op = FindBinkMovieAction(key);
			if (op && op->bActive)
			{
				StopLocalBinkMovie(op, key, "the other player skipped it");
				return;
			}
			g_pendingBinkStops[key] = Clock::now() + std::chrono::seconds(20);
			Log("BINKSKIP RX key=" + SharedWorldKeyText(key)
				+ ": not playing here yet, stopped when it starts.");
		}

		// From the SequenceOp Activated / Deactivated hook.
		void NoteLocalBinkMovie(USequenceOp* op, bool activated)
		{
			if (!op || !op->IsA(USeqAct_PlayBinkMovie::StaticClass()) || g_config.localMirror)
				return;
			DropStaleBinkState();
			const std::uint64_t key = SequenceActionStableKey(op);
			if (key == 0)
				return;
			const auto now = Clock::now();
			if (activated)
			{
				g_localBinkStartedAt[key] = now;
				g_remoteStoppedBinks.erase(key);
				const auto pending = g_pendingBinkStops.find(key);
				if (pending != g_pendingBinkStops.end())
				{
					const bool fresh = now < pending->second;
					g_pendingBinkStops.erase(pending);
					if (fresh)
						StopLocalBinkMovie(op, key, "skipped by the other player before it started here");
				}
				return;
			}
			const auto started = g_localBinkStartedAt.find(key);
			const bool knownStart = started != g_localBinkStartedAt.end();
			const auto playedFor = knownStart ? now - started->second : Clock::duration{};
			if (knownStart)
				g_localBinkStartedAt.erase(started);
			if (g_applyingRemoteBinkStop || g_remoteStoppedBinks.erase(key) > 0
				|| !knownStart || playedFor < std::chrono::milliseconds(300) || !g_connected)
			{
				return;
			}
			SharedWorldEventPayload event{};
			event.kind = static_cast<SharedWorldEventKind>(54);
			event.entityKey = key;
			event.originActorId = g_config.role == Role::Host ? 1u : 2u;
			QueueSharedWorldEvent(event);
			Log("BINKSKIP TX " + ObjectName(op) + " ended here after "
				+ std::to_string(std::chrono::duration_cast<std::chrono::milliseconds>(playedFor).count())
				+ " ms, key=" + SharedWorldKeyText(key) + '.');
		}

		void OnRemoteAliceFrozen(const SharedWorldEventPayload& event)
		{
			AAlicePawn* const proxy = g_remotePawn;
			const bool frozen = (event.flags & 1u) != 0;
			if (!proxy || !IsUsableObjectFast(proxy) || frozen == g_remoteFrozenShown)
				return;
			g_remoteFrozenShown = frozen;
			static UFunction* playFrozen = FindFunctionSafe("Function AliceGame.AlicePawn.PlayFrozenParticle");
			static UFunction* playBreak = FindFunctionSafe("Function AliceGame.AlicePawn.PlayFrozenBreakParticle");
			static UFunction* deactivate = FindFunctionSafe("Function Engine.ParticleSystemComponent.DeactivateSystem");
			std::uint8_t parameters[16]{};
			proxy->bIsFrozen = frozen ? 1u : 0u;
			if (frozen)
			{
				if (playFrozen)
					proxy->ProcessEvent(playFrozen, parameters, nullptr);
				if (proxy->FrozenLoopPS && IsUsableObjectFast(proxy->FrozenLoopPS))
					MakePresentationParticleVisible(proxy->FrozenLoopPS);
			}
			else
			{
				if (proxy->FrozenLoopPS && IsUsableObjectFast(proxy->FrozenLoopPS) && deactivate)
					proxy->FrozenLoopPS->ProcessEvent(deactivate, parameters, nullptr);
				if (playBreak)
					proxy->ProcessEvent(playBreak, parameters, nullptr);
			}
			Log(std::string("FROZEN RX the other Alice is ") + (frozen ? "frozen: ice shown on her." : "free: ice broken.")
				+ " loopPS=" + ObjectName(proxy->FrozenLoopPS));
		}

		void ForgetDeathHide(AAliceGameKynapsePawn* enemy)
		{
			g_deathHideSent.erase(enemy);
			g_deathHidden.erase(enemy);
		}

		void SendDeathHide(std::uint64_t key, AAliceGameKynapsePawn* enemy, Clock::time_point now)
		{
			DeathHideSend& state = g_deathHideSent[enemy];
			if (state.sent >= 3 || now - state.last < std::chrono::milliseconds(400))
				return;
			++state.sent;
			state.last = now;
			SharedWorldEventPayload event{};
			event.kind = kEventEnemyFx;
			event.originActorId = g_config.role == Role::Host ? 1u : 2u;
			event.entityKey = key;
			event.flags = kFxDeathHide;
			QueueSharedWorldEvent(event);
			if (state.sent == 1)
				Log("DEATHHIDE TX " + ObjectName(enemy) + ": dead body hidden here.");
		}
		// loopfx1 (31.10): a looping effect turned on by a replay (the shot
		// glowing in the Ruin's hand) whose "off" never came - a stun or a
		// hand-over in between - stayed on: the Ruin fought with a shot in its
		// hand. Replayed loops are tracked and switched off when this copy
		// starts driving, or after 6 s.
		struct ReplayedLoop
		{
			bool sound = false;
			int id = 0;
			Clock::time_point since{};
		};
		std::unordered_map<AAliceGameKynapsePawn*, std::vector<ReplayedLoop>> g_replayedLoops;

		void NoteReplayedLoop(AAliceGameKynapsePawn* enemy, bool sound, int id, bool on)
		{
			auto& loops = g_replayedLoops[enemy];
			for (auto it = loops.begin(); it != loops.end(); ++it)
			{
				if (it->sound == sound && it->id == id)
				{
					loops.erase(it);
					break;
				}
			}
			if (on)
				loops.push_back(ReplayedLoop{ sound, id, Clock::now() });
		}

		void StopReplayedLoops(AAliceGameKynapsePawn* enemy, bool all, const char* why)
		{
			const auto found = g_replayedLoops.find(enemy);
			if (found == g_replayedLoops.end())
				return;
			const auto now = Clock::now();
			auto& loops = found->second;
			for (auto it = loops.begin(); it != loops.end();)
			{
				if (!all && now - it->since < std::chrono::seconds(6))
				{
					++it;
					continue;
				}
				if (enemy && IsUsableObjectFast(enemy) && !enemy->bDeleteMe)
				{
					g_applyingRemoteEnemyFx = true;
					if (it->sound)
						enemy->eventToggleLoopSound(false, it->id, 0.2f);
					else
						enemy->eventToggleLoopParticle(false, it->id);
					g_applyingRemoteEnemyFx = false;
					static int logsLeft = 30;
					if (logsLeft > 0)
					{
						--logsLeft;
						Log(std::string("ENEMYFX switched off a replayed loop ")
							+ (it->sound ? "sound " : "particle ") + std::to_string(it->id)
							+ " of " + ObjectName(enemy) + " (" + why + ").");
					}
				}
				it = loops.erase(it);
			}
			if (loops.empty())
				g_replayedLoops.erase(found);
		}

		void StopReplayedLoopsFor(AAliceGameKynapsePawn* enemy, bool driven)
		{
			if (g_replayedLoops.empty())
				return;
			StopReplayedLoops(enemy, driven, driven ? "this game drives it now" : "no off for 6 s");
		}

		void SetHashedName(SharedWorldEventPayload& event, const std::string& name)
		{
			if (name.size() < sizeof(event.damageType))
				strncpy_s(event.damageType, name.c_str(), _TRUNCATE);
			else
				sprintf_s(event.damageType, "#dt:%08x", TunnelNameHash(name.c_str(), name.size()));
		}

		std::uint32_t EventNameHash(const SharedWorldEventPayload& event, std::string* plain)
		{
			const std::string name(event.damageType, strnlen_s(event.damageType, sizeof(event.damageType)));
			if (name.rfind("#dt:", 0) == 0)
				return static_cast<std::uint32_t>(std::strtoul(name.c_str() + 4, nullptr, 16));
			if (plain)
				*plain = name;
			return name.empty() ? 0u : TunnelNameHash(name.c_str(), name.size());
		}

		UObject* ResolveSphinxParticle(const SharedWorldEventPayload& event)
		{
			const std::uint32_t wanted = static_cast<std::uint32_t>(event.healthMax);
			if (!wanted)
				return nullptr;
			static std::unordered_map<std::uint32_t, UObject*> cache;
			auto cached = cache.find(wanted);
			if (cached != cache.end() && (!cached->second || IsLiveUObject(cached->second)))
				return cached->second;
			UObject* found = nullptr;
			TArray<UObject*>* objects = UObject::GObjObjects();
			for (int32_t index = 0; objects && index < objects->size(); ++index)
			{
				UObject* const object = objects->at(index);
				if (!object || !object->Class || object->Class->GetName() != "SphinxSequenceEventPlayParticle")
					continue;
				const std::string full = object->GetFullName();
				if (TunnelNameHash(full.c_str(), full.size()) == wanted)
				{
					found = object;
					break;
				}
			}
			cache[wanted] = found;
			return found;
		}

		bool ResolveEventFName(const SharedWorldEventPayload& event, FName& out)
		{
			std::string plain;
			const std::uint32_t wanted = EventNameHash(event, &plain);
			if (!plain.empty())
			{
				out = FName(plain.c_str());
				return true;
			}
			if (!wanted || !GNames)
				return false;
			static std::unordered_map<std::uint32_t, int32_t> cache;
			auto cached = cache.find(wanted);
			if (cached == cache.end())
			{
				int32_t found = -1;
				for (int32_t i = 0; i < GNames->size(); ++i)
				{
					FNameEntry* const entry = GNames->at(i);
					if (!entry)
						continue;
					const char* const text = entry->GetAnsiName();
					if (text && TunnelNameHash(text, std::strlen(text)) == wanted)
					{
						found = i;
						break;
					}
				}
				cached = cache.emplace(wanted, found).first;
			}
			if (cached->second < 0)
				return false;
			out = FName(cached->second);
			return true;
		}

		// ProcessEvent hook (before).
		void ObserveEnemyFx(UObject* object, UFunction* function, const void* parameters)
		{
			if (!g_connected || !g_config.sharedEnemyTransforms || g_config.localMirror
				|| g_applyingRemoteEnemyFx || !object || !function || !parameters)
			{
				return;
			}
			static std::unordered_map<const UFunction*, std::uint8_t> opByFunction;
			auto cached = opByFunction.find(function);
			if (cached == opByFunction.end())
			{
				const std::string name = function->GetName();
				std::uint8_t op = 0;
				if (name == "ToggleLoopParticle") op = kFxLoopParticle;
				else if (name == "ToggleLoopSound") op = kFxLoopSound;
				else if (name == "PlayParticleEffectFromSphinxSequence") op = kFxSphinxParticle;
				else if (name == "ToggleSkeletalControl") op = kFxSkelControl;
				cached = opByFunction.emplace(function, op).first;
			}
			if (!cached->second || !object->IsA(AAliceGameKynapsePawn::StaticClass()))
				return;
			auto* const enemy = reinterpret_cast<AAliceGameKynapsePawn*>(object);
			const std::uint64_t key = SharedKeyForEnemy(enemy, SharedEnemyStableKey(enemy));
			if (!key || !DrivesEnemyFx(key, enemy))
				return;
			SharedWorldEventPayload event{};
			event.kind = kEventEnemyFx;
			event.originActorId = g_config.role == Role::Host ? 1u : 2u;
			event.entityKey = key;
			event.flags = cached->second;
			std::string what;
			switch (cached->second)
			{
			case kFxLoopParticle:
			{
				const auto* value = reinterpret_cast<const AAliceGameKynapsePawn_eventToggleLoopParticle_Params*>(parameters);
				event.damage = value->bEnable ? 1 : 0;
				event.health = value->ParticleID;
				what = "loop particle " + std::to_string(value->ParticleID) + (value->bEnable ? " on" : " off");
				break;
			}
			case kFxLoopSound:
			{
				const auto* value = reinterpret_cast<const AAliceGameKynapsePawn_eventToggleLoopSound_Params*>(parameters);
				event.damage = value->bEnable ? 1 : 0;
				event.health = value->SoundID;
				event.momentum[0] = value->FadeTime;
				what = "loop sound " + std::to_string(value->SoundID) + (value->bEnable ? " on" : " off");
				break;
			}
			case kFxSphinxParticle:
			{
				const auto* value = reinterpret_cast<const AAliceGameKynapsePawn_eventPlayParticleEffectFromSphinxSequence_Params*>(parameters);
				if (!value->SequenceData)
					return;
				const std::string full = reinterpret_cast<UObject*>(value->SequenceData)->GetFullName();
				// The hash goes in a number: a "#dt:" text would be hashed again
				// by the tunnel (all 40 lookups failed, 30.10 00:41).
				event.healthMax = static_cast<std::int32_t>(TunnelNameHash(full.c_str(), full.size()));
				what = "sphinx particle " + full;
				break;
			}
			case kFxSkelControl:
			{
				const auto* value = reinterpret_cast<const AAliceGameKynapsePawn_eventToggleSkeletalControl_Params*>(parameters);
				const std::string control = value->ControlName.ToString();
				SetHashedName(event, control);
				event.damage = value->bSetActived ? 1 : 0;
				what = "skel control " + control + (value->bSetActived ? " on" : " off");
				break;
			}
			default:
				return;
			}
			QueueSharedWorldEvent(event);
			static int logsLeft = 80;
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("ENEMYFX TX " + ObjectName(enemy) + ": " + what + '.');
			}
		}

		// fxguard2 (10.11 19:11:55, client crash: OnRemoteEnemyFx ->
		// ProcessEvent -> exe+0x7744CF, read at 0xB5BC, right after the host
		// sent sphinx-particle / head-look events for a Menacing Ruin the
		// client had just been handed). Each replayed effect runs under SEH
		// and leaves a crumb naming the op and enemy; an enemy whose effect
		// faulted gets no more replayed effects in this world.
		// No objects with destructors in these, which is what makes __try legal.
		bool SehToggleLoopParticle(AAliceGameKynapsePawn* enemy, bool on, int32_t index)
		{
			__try { enemy->eventToggleLoopParticle(on, index); return true; }
			__except (EXCEPTION_EXECUTE_HANDLER) { return false; }
		}
		bool SehToggleLoopSound(AAliceGameKynapsePawn* enemy, bool on, int32_t index, float volume)
		{
			__try { enemy->eventToggleLoopSound(on, index, volume); return true; }
			__except (EXCEPTION_EXECUTE_HANDLER) { return false; }
		}
		bool SehPlaySphinxParticle(AAliceGameKynapsePawn* enemy, USphinxSequenceEventPlayParticle* data)
		{
			__try { enemy->eventPlayParticleEffectFromSphinxSequence(data); return true; }
			__except (EXCEPTION_EXECUTE_HANDLER) { return false; }
		}
		bool SehToggleSkelControl(AAliceGameKynapsePawn* enemy, const FName& control, bool on)
		{
			__try { enemy->eventToggleSkeletalControl(control, on); return true; }
			__except (EXCEPTION_EXECUTE_HANDLER) { return false; }
		}
		std::unordered_set<std::uint64_t> g_enemyFxFaulted;
		void* g_enemyFxFaultedWorld = nullptr;

		// fxguard3 (11.11 01:01:31 client crash, chapter 2 freezing fish:
		// OnRemoteEnemyFx -> PlayParticleEffectFromSphinxSequence -> exe+0x7744CF,
		// read at 0xB547 - the same address as 10.11 19:11:55). The SEH guard
		// never got it: the game's own handler inside ProcessEvent takes the
		// fault first and ends the game. So the replay is checked beforehand,
		// the way the script will use it (AliceGameKynapsePawn.uc): the
		// particle, the attachment component at ComponentIndex, its mesh, and
		// the bone / socket it is attached to must all be there on THIS copy.
		bool SphinxParticleSafeHere(AAliceGameKynapsePawn* enemy, USphinxSequenceEventPlayParticle* data,
			std::string& why)
		{
			if (!data || !IsLiveUObject(data))
				return why = "no particle data", false;
			if (!data->Particle || !IsLiveUObject(data->Particle))
				return why = "no particle template", false;
			if (!enemy->WorldInfo || !IsUsableObjectFast(enemy->WorldInfo)
				|| !enemy->WorldInfo->MyEmitterPool || !IsLiveUObject(enemy->WorldInfo->MyEmitterPool))
			{
				return why = "no emitter pool", false;
			}
			const int index = data->ComponentIndex;
			const auto& components = enemy->NPCAttachmentComponentsArray;
			if (index < 0 || index >= components.size())
				return true; // the script does nothing then
			const FNPCAttachmentComponent& component = components.at(index);
			USkeletalMeshComponent* skel = nullptr;
			if (component.CurrentAttachmentMeshComponent)
			{
				if (!IsLiveUObject(component.CurrentAttachmentMeshComponent))
					return why = "attachment mesh component gone", false;
				skel = component.CurrentAttachmentMeshComponent;
			}
			else if (component.CurrentDropActor)
			{
				if (!IsLiveUObject(component.CurrentDropActor))
					return why = "drop actor gone", false;
				if (component.CurrentDropActor->SkelComp)
				{
					if (!IsLiveUObject(component.CurrentDropActor->SkelComp))
						return why = "drop actor mesh gone", false;
					skel = component.CurrentDropActor->SkelComp;
				}
			}
			if (!skel)
				return true; // the script does nothing then
			if (!skel->SkeletalMesh || !IsLiveUObject(skel->SkeletalMesh))
				return why = "attachment has no skeletal mesh", false;
			const std::string bone = data->Bone.ToString();
			const std::string socket = data->Socket.ToString();
			if (!bone.empty() && bone != "None")
			{
				static UFunction* matchBone = FindFunctionSafe("Function Engine.SkeletalMeshComponent.MatchRefBone");
				USkeletalMeshComponent_execMatchRefBone_Params parameters{};
				parameters.BoneName = data->Bone;
				parameters.ReturnValue = -1;
				if (!matchBone || !InvokeNativeFunction(skel, matchBone, parameters) || parameters.ReturnValue < 0)
					return why = "bone " + bone + " not on this mesh", false;
			}
			else if (!socket.empty() && socket != "None")
			{
				static UFunction* getSocket = FindFunctionSafe("Function Engine.SkeletalMeshComponent.GetSocketByName");
				USkeletalMeshComponent_execGetSocketByName_Params parameters{};
				parameters.InSocketName = data->Socket;
				if (!getSocket || !InvokeNativeFunction(skel, getSocket, parameters) || !parameters.ReturnValue)
					return why = "socket " + socket + " not on this mesh", false;
			}
			else if (data->bAttach)
			{
				return why = "attached with neither bone nor socket", false;
			}
			return true;
		}

		void OnRemoteEnemyFx(const SharedWorldEventPayload& event)
		{
			if (WorldTransitionActive())
				return;
			if (g_enemyFxFaultedWorld != g_currentWorld)
			{
				g_enemyFxFaultedWorld = g_currentWorld;
				g_enemyFxFaulted.clear();
			}
			if (g_enemyFxFaulted.count(event.entityKey))
				return;
			AAliceGameKynapsePawn* const enemy = EnemyForSharedKey(event.entityKey);
			std::string result;
			if (!enemy || !IsLiveUObject(enemy) || enemy->bDeleteMe)
				result = "enemy not here";
			else if (DrivesEnemyFx(event.entityKey, enemy))
				result = "this game drives it";
			else
			{
				g_applyingRemoteEnemyFx = true;
				switch (event.flags)
				{
				case kFxBranch:
				{
					const int before = enemy->SphinxEventAnimTreeBranchIndex;
					// branchhold1 (11.11 01:55:30.449, Cannon Crab): the driver
					// went from the flipped branch (2) back to 0 just before
					// its recovery animation (KnockBack2C_Crack); on the copy
					// the branch came first and the recovery a moment later,
					// so the crab stood upright for ~0.2 s and then flipped
					// again - the flicker. A switch from a held branch back
					// to branch 0 now waits for the recovery animation here.
					static UClass* const crabClass = AAliceGameCannonCrabPawn::StaticClass();
					EnemyBranchState& branchState = g_enemyBranch[enemy];
					// branchhold2 (11.11 20:57:43.915, client): the switch to the
					// flipped branch (2) came 50 ms before KnockBack2A, so the
					// copy lay on its back (KnockBack2B) first, stood up again
					// and only then flipped - first and second animation by
					// turns. Every switch of the crab's branch waits the same
					// way for its one-shot (flip, attack, recovery) here.
					if (crabClass && enemy->IsA(crabClass) && before != event.health)
					{
						if (branchState.pending != event.health)
						{
							branchState.pending = event.health;
							branchState.pendingUntil = Clock::now() + std::chrono::milliseconds(400);
						}
						result = "anim branch " + std::to_string(before) + "->" + std::to_string(event.health)
							+ " held for its one-shot animation";
						break;
					}
					branchState.pending = -1;
					enemy->SphinxEventAnimTreeBranchIndex = event.health;
					result = "anim branch " + std::to_string(before) + "->" + std::to_string(event.health);
					break;
				}
				case kFxDeathHide:
					HideDeadEnemyCopy(enemy);
					result = "dead body hidden";
					break;
				case kFxLoopParticle:
					DiagBegin("enemyfx.loop", enemy);
					if (!SehToggleLoopParticle(enemy, event.damage != 0, event.health))
						g_enemyFxFaulted.insert(event.entityKey);
					DiagEnd("enemyfx.loop", enemy);
					NoteReplayedLoop(enemy, false, event.health, event.damage != 0);
					result = "loop particle " + std::to_string(event.health) + (event.damage ? " on" : " off");
					break;
				case kFxLoopSound:
					DiagBegin("enemyfx.sound", enemy);
					if (!SehToggleLoopSound(enemy, event.damage != 0, event.health, event.momentum[0]))
						g_enemyFxFaulted.insert(event.entityKey);
					DiagEnd("enemyfx.sound", enemy);
					NoteReplayedLoop(enemy, true, event.health, event.damage != 0);
					result = "loop sound " + std::to_string(event.health) + (event.damage ? " on" : " off");
					break;
				case kFxSphinxParticle:
					if (UObject* const data = ResolveSphinxParticle(event))
					{
						std::string unsafe;
						if (!SphinxParticleSafeHere(enemy,
							reinterpret_cast<USphinxSequenceEventPlayParticle*>(data), unsafe))
						{
							result = "sphinx particle skipped: " + unsafe + " (fxguard3)";
							break;
						}
						DiagBegin("enemyfx.sphinx", enemy, data);
						const bool ok = SehPlaySphinxParticle(enemy,
							reinterpret_cast<USphinxSequenceEventPlayParticle*>(data));
						DiagEnd("enemyfx.sphinx", enemy);
						if (!ok)
							g_enemyFxFaulted.insert(event.entityKey);
						result = ok ? "sphinx particle played" : "sphinx particle FAULTED (enemy's effects stop here)";
					}
					else
						result = "sphinx particle not found";
					break;
				case kFxSkelControl:
				{
					FName control;
					if (ResolveEventFName(event, control))
					{
						DiagBegin("enemyfx.skel", enemy);
						const bool ok = SehToggleSkelControl(enemy, control, event.damage != 0);
						DiagEnd("enemyfx.skel", enemy);
						if (!ok)
							g_enemyFxFaulted.insert(event.entityKey);
						result = "skel control " + control.ToString() + (event.damage ? " on" : " off")
							+ (ok ? std::string() : std::string(" FAULTED (enemy's effects stop here)"));
					}
					else
						result = "skel control name not found";
					break;
				}
				default:
					result = "unknown op";
					break;
				}
				g_applyingRemoteEnemyFx = false;
			}
			static int logsLeft = 80;
			if (g_enemyFxFaulted.count(event.entityKey))
			{
				Log("ENEMYFX RX key=" + SharedWorldKeyText(event.entityKey) + ": " + result
					+ " - an access fault was caught (fxguard2).");
			}
			else if (logsLeft > 0)
			{
				--logsLeft;
				Log("ENEMYFX RX key=" + SharedWorldKeyText(event.entityKey) + ": " + result + '.');
			}
		}

		// ---- Armour plate hits, replayed (kind 43) ---------------------
		// A hit on a plate (AliceGameNPCAttachedActor.TakeDamage) is sent
		// with its damage, type and place, and the other game runs the same
		// TakeDamage on its copy of that plate - so the plate breaks there
		// through the game's own code (its HP, its death, OnAttachedActorDie,
		// the AI's NotifyAttachedActorDamage/Dead and the animation).
		constexpr SharedWorldEventKind kEventPlateHit =
			static_cast<SharedWorldEventKind>(43);
		bool g_applyingRemotePlateDamage = false;

		void SendPlateHit(AAliceGameNPCAttachedActor* plate,
			const AAliceGameNPCAttachedActor_eventTakeDamage_Params& hit)
		{
			AAliceGameKynapsePawn* const owner = plate->HostActor;
			if (!owner || !IsLiveUObject(owner) || hit.DamageValue <= 0)
				return;
			int index = -1;
			for (int32_t i = 0; i < owner->NPCAttachedActors.size(); ++i)
			{
				if (owner->NPCAttachedActors.at(i).AttachedActor == plate)
				{
					index = i;
					break;
				}
			}
			if (index < 0)
				return;
			const std::uint64_t key = SharedKeyForEnemy(owner, SharedEnemyStableKey(owner));
			if (!key)
				return;
			SharedWorldEventPayload event{};
			event.kind = kEventPlateHit;
			event.entityKey = key;
			event.originActorId = g_config.role == Role::Host ? 1u : 2u;
			event.damage = hit.DamageValue;
			event.health = index;
			event.healthMax = plate->HP;
			event.hitLocation[0] = hit.HitLocation.X;
			event.hitLocation[1] = hit.HitLocation.Y;
			event.hitLocation[2] = hit.HitLocation.Z;
			event.momentum[0] = hit.Momentum.X;
			event.momentum[1] = hit.Momentum.Y;
			event.momentum[2] = hit.Momentum.Z;
			strncpy_s(event.damageType, ObjectName(hit.DamageType).c_str(), _TRUNCATE);
			QueueSharedWorldEvent(event);
			static int logsLeft = 60;
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("PLATEHIT TX " + ObjectName(owner) + " plate " + std::to_string(index)
					+ ": damage=" + std::to_string(hit.DamageValue) + " type="
					+ ObjectName(hit.DamageType) + " hpBefore=" + std::to_string(plate->HP)
					+ " instigator=" + ObjectName(hit.EventInstigator) + '.');
			}
		}

		void OnRemotePlateHit(const SharedWorldEventPayload& event)
		{
			if (!g_config.sharedEnemyHealth || WorldTransitionActive())
				return;
			AAliceGameKynapsePawn* const enemy = EnemyForSharedKey(event.entityKey);
			const int index = event.health;
			std::string result;
			AAliceGameNPCAttachedActor* plate = nullptr;
			if (!enemy || !IsLiveUObject(enemy) || enemy->bDeleteMe)
				result = "enemy not here";
			else if (index < 0 || index >= enemy->NPCAttachedActors.size())
				result = "no such plate here";
			else
			{
				plate = enemy->NPCAttachedActors.at(index).AttachedActor;
				if (!plate || !IsLiveUObject(plate))
					result = "plate gone here";
			}
			if (plate && result.empty())
			{
				static UFunction* takeDamage = FindFunctionSafe(
					"Function AliceGame.AliceGameNPCAttachedActor.TakeDamage");
				UClass* damageType = event.damageType[0]
					? UObject::FindClass(event.damageType) : nullptr;
				if (!damageType)
					damageType = UDamageType::StaticClass();
				// AliceGameNPCAttachedActor.uc TakeDamage: HP -= damage; above 0
				// -> Damage state + AI NotifyAttachedActorDamage, else AI
				// NotifyAttachedActorDead + Dying (-> OnAttachedActorDie ->
				// WakeUpNPCAttachedActor(false)). HP is -1 until the AI wakes
				// the plate (PostBeginPlay), so:
				//  - a plate not awake here is left alone (any hit would kill
				//    it on the spot);
				//  - a plate that died at the sender dies here too, whatever
				//    HP it has left here, so both brains get the same death.
				const bool senderKilled = event.healthMax - event.damage <= 0;
				AAliceGameNPCAttachedActor_eventTakeDamage_Params hit{};
				hit.DamageValue = senderKilled
					? (std::max)(event.damage, plate->HP)
					: (std::min)(event.damage, (std::max)(plate->HP - 1, 0));
				hit.EventInstigator = g_State.AlicePlayerController;
				hit.HitLocation = FVector(event.hitLocation[0], event.hitLocation[1],
					event.hitLocation[2]);
				hit.Momentum = FVector(event.momentum[0], event.momentum[1], event.momentum[2]);
				hit.DamageType = damageType;
				hit.DamageCauser = nullptr;
				const int before = plate->HP;
				const bool awake = plate->HP > 0
					&& plate->ActorState != ENPCAttachedActorState::ENPCAAS_Die;
				if (!awake || hit.DamageValue <= 0)
				{
					result = std::string("skipped: plate ") + (awake ? "has 1 HP left" : "not awake/dead")
						+ " here (hp " + std::to_string(before) + ", state "
						+ std::to_string(static_cast<int>(plate->ActorState)) + ")";
				}
				else if (takeDamage)
				{
					g_applyingRemotePlateDamage = true;
					plate->ProcessEvent(takeDamage, &hit, nullptr);
					g_applyingRemotePlateDamage = false;
				}
				if (result.empty())
					result = std::string(takeDamage ? "replayed" : "TakeDamage missing")
					+ ": hp " + std::to_string(before) + "->" + std::to_string(plate->HP)
					+ ", state " + std::to_string(static_cast<int>(plate->ActorState))
					+ ", type " + ObjectName(damageType);
			}
			static int logsLeft = 60;
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("PLATEHIT RX key=" + SharedWorldKeyText(event.entityKey) + " plate "
					+ std::to_string(index) + " damage=" + std::to_string(event.damage)
					+ " (sender hp " + std::to_string(event.healthMax) + "): " + result + '.');
			}
		}

		void OnRemotePlateAnim(const SharedWorldEventPayload& event)
		{
			if (WorldTransitionActive() || LocallyDrivesSharedEnemy(event.entityKey))
				return;
			AAliceGameKynapsePawn* const enemy = EnemyForSharedKey(event.entityKey);
			const int index = event.damage;
			if (!enemy || !IsLiveUObject(enemy) || enemy->bDeleteMe
				|| index < 0 || index >= enemy->NPCAttachedActors.size())
			{
				return;
			}
			AAliceGameNPCAttachedActor* const plate = enemy->NPCAttachedActors.at(index).AttachedActor;
			if (!plate || !IsLiveUObject(plate) || !plate->SkeletalMeshComponent
				|| !IsUsableObjectFast(plate->SkeletalMeshComponent))
			{
				return;
			}
			// the clip by its name hash among the plate mesh's sets
			const std::uint32_t hash = static_cast<std::uint32_t>(event.health);
			FName animName;
			bool found = false;
			const auto& sets = plate->SkeletalMeshComponent->AnimSets;
			for (int32_t s = 0; s < sets.size() && !found; ++s)
			{
				UAnimSet* const set = sets.at(s);
				if (!set || !IsUsableObjectFast(set))
					continue;
				for (int32_t q = 0; q < set->Sequences.size(); ++q)
				{
					UAnimSequence* const clip = set->Sequences.at(q);
					if (!clip)
						continue;
					const std::string name = clip->SequenceName.ToString();
					if (TunnelNameHash(name.c_str(), name.size()) == hash)
					{
						animName = clip->SequenceName;
						found = true;
						break;
					}
				}
			}
			static int logsLeft = 40;
			if (!found)
			{
				if (logsLeft > 0)
				{
					--logsLeft;
					Log("PLATEANIM clip not found on " + ObjectName(plate) + " (plate "
						+ std::to_string(index) + ").");
				}
				return;
			}
			// plateanim2 (10.11 22:04:38, the head hit on the host): the
			// host's hit made its head play Tank_Head_Big_Damage, then the
			// driver's older Tank_Head_Big_Idle came in and replaced it, then
			// the driver's Damage - the head flickered. The same clip is only
			// moved to the driver's time when far off; an idle never cuts a
			// hit / death reaction still playing here.
			if (plate->AnimBlendNodes.size() > 0)
			{
				UAliceGameAnimNode_BlendBase* const node = plate->AnimBlendNodes.at(0);
				UAnimNodeSequence* const current = node && IsUsableObjectFast(node) && node->bIsPlayingCustomAnim
					? CustomSequenceOf(node) : nullptr;
				if (current && current->AnimSeq)
				{
					const std::string currentName = current->AnimSeqName.ToString();
					const std::string incoming = animName.ToString();
					if (currentName == incoming)
					{
						if (std::fabs(current->CurrentTime - event.hitLocation[0]) > 0.3f)
							NativeSetPosition(current, event.hitLocation[0]);
						return;
					}
					const bool reacting = currentName.find("Damage") != std::string::npos
						|| currentName.find("Death") != std::string::npos
						|| currentName.find("Die") != std::string::npos;
					const float rate = current->Rate > 0.01f ? current->Rate : 1.0f;
					const bool stillRunning = current->bPlaying
						&& current->CurrentTime < current->AnimSeq->SequenceLength - 0.05f * rate;
					if (reacting && stillRunning && incoming.find("Idle") != std::string::npos)
						return;
				}
			}
			static UFunction* const playFn =
				FindFunctionSafe("Function AliceGame.AliceGameNPCAttachedActor.PlayConfigAnim");
			FAnimationParaConfig config{};
			reinterpret_cast<RawGameArray&>(config.AnimationNames) = RawGameArray{ &animName, 1, 1 };
			reinterpret_cast<RawGameArray&>(config.AnimationDescName) = RawGameArray{ nullptr, 0, 0 };
			config.BlendNodeIndex = 0;
			config.AnimType = static_cast<int32_t>(EAnimConfigType::EACT_Arbitrary);
			config.BlendInTime = 0.1f;
			config.BlendOutTime = 0.2f;
			config.PlayRate = std::clamp(event.healthMax / 1000.0f, 0.05f, 10.0f);
			config.bLoop = (event.flags & 1u) != 0;
			config.bCauseActorAnimEnd = false;
			config.bTriggerFakeRootMotion = false;
			config.bNotExtendAnimTimeForFakeRootMotion = true;
			config.AnimPlayType = static_cast<std::uint8_t>(EConfigAnimPlayType::ECAPT_OneByOne);
			AAliceGameNPCAttachedActor_execPlayConfigAnim_Params params{};
			bool invoked = false;
			if (playFn && PrepareGameAnimConfig(config, params.AnimConfig))
			{
				params.configtype = static_cast<int32_t>(EAnimConfigType::EACT_Arbitrary);
				invoked = InvokeNativeFunction(plate, playFn, params);
				ReleaseGameAnimConfig(params.AnimConfig);
			}
			reinterpret_cast<RawGameArray&>(config.AnimationNames) = RawGameArray{ nullptr, 0, 0 };
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("PLATEANIM " + ObjectName(plate) + " (plate " + std::to_string(index) + ") plays "
					+ animName.ToString() + " like the driver: native=" + (invoked ? "yes" : "no")
					+ " (plateanim1).");
			}
		}

		void EnforceDeadPlates(std::uint64_t key, AAliceGameKynapsePawn* enemy)
		{
			const auto found = g_deadPlates.find(key);
			if (found == g_deadPlates.end() || found->second.enemy != enemy || !found->second.mask
				|| !enemy || enemy->Health <= 0)
			{
				return;
			}
			DeadPlates& dead = found->second;
			const auto now = Clock::now();
			const int32_t count = (std::min)(enemy->NPCAttachedActors.size(), 16);
			static UFunction* const takeDamage =
				FindFunctionSafe("Function AliceGame.AliceGameNPCAttachedActor.TakeDamage");
			static UFunction* const hideFn =
				FindFunctionSafe("Function AliceGame.AliceGameKynapsePawn.HideNPCAttachedActor");
			static int logsLeft = 40;
			for (int32_t index = 0; index < count; ++index)
			{
				if (!(dead.mask & (1u << index)))
					continue;
				// its own death animation runs out first
				if (now - dead.at[index] < std::chrono::seconds(3)
					|| now - dead.lastFix[index] < std::chrono::seconds(1))
				{
					continue;
				}
				AAliceGameNPCAttachedActor* const plate = enemy->NPCAttachedActors.at(index).AttachedActor;
				if (!plate || !IsLiveUObject(plate) || plate->bDeleteMe)
					continue;
				const bool alive = plate->HP > 0 && plate->ActorState != ENPCAttachedActorState::ENPCAAS_Die;
				USkeletalMeshComponent* const mesh = plate->SkeletalMeshComponent;
				const bool shown = !plate->bHidden
					&& !(mesh && IsUsableObjectFast(mesh) && mesh->HiddenGame);
				if (alive && takeDamage)
				{
					dead.lastFix[index] = now;
					AAliceGameNPCAttachedActor_eventTakeDamage_Params hit{};
					hit.DamageValue = plate->HP + 1;
					hit.EventInstigator = g_State.AlicePlayerController;
					hit.HitLocation = plate->Location;
					hit.DamageType = UDamageType::StaticClass();
					hit.DamageCauser = nullptr;
					const int before = plate->HP;
					g_applyingRemotePlateDamage = true;
					plate->ProcessEvent(takeDamage, &hit, nullptr);
					g_applyingRemotePlateDamage = false;
					dead.at[index] = now; // its death animation runs out again
					if (logsLeft > 0)
					{
						--logsLeft;
						Log("PLATEDEAD " + ObjectName(enemy) + " plate " + std::to_string(index)
							+ " came back (hp " + std::to_string(before) + ") - killed again: hp now "
							+ std::to_string(plate->HP) + ", state "
							+ std::to_string(static_cast<int>(plate->ActorState)) + " (platedead1).");
					}
				}
				else if (!alive && (shown || plate->bIsAwake))
				{
					dead.lastFix[index] = now;
					if (plate->bIsAwake)
					{
						static UFunction* const wakeFn =
							FindFunctionSafe("Function AliceGame.AliceGameKynapsePawn.WakeUpNPCAttachedActor");
						AAliceGameKynapsePawn_execWakeUpNPCAttachedActor_Params params{};
						params.bActive = 0u;
						params.ActorIndex = index;
						params.HP = -1; // as OnAttachedActorDie does
						if (wakeFn)
							InvokeNativeFunction(enemy, wakeFn, params);
					}
					if (shown)
					{
						AAliceGameKynapsePawn_execHideNPCAttachedActor_Params params{};
						params.bSetHidden = 1u;
						params.ActorIndex = index;
						if (hideFn)
							InvokeNativeFunction(enemy, hideFn, params);
						if (!plate->bHidden)
							NativeSetActorHidden(plate, true);
					}
					if (logsLeft > 0)
					{
						--logsLeft;
						Log("PLATEDEAD " + ObjectName(enemy) + " plate " + std::to_string(index)
							+ " is dead but " + (shown ? "showed" : "was awake") + " - put away and hidden (platedead1).");
					}
				}
			}
		}

		void OnRemoteLockTargets(const SharedWorldEventPayload& event)
		{
			if (!g_config.sharedEnemyHealth || WorldTransitionActive()
				|| LocallyDrivesSharedEnemy(event.entityKey))
			{
				return;
			}
			AAliceGameKynapsePawn* const enemy = EnemyForSharedKey(event.entityKey);
			if (!enemy || !IsLiveUObject(enemy) || enemy->bDeleteMe || enemy->Health <= 0)
				return;
			auto& sockets = enemy->LockOnInfo.TargetSockets;
			const int32_t count = (std::min)((std::min)(sockets.size(), 31), (std::max)(event.healthMax, 0));
			int changed = 0;
			for (int32_t i = 0; i < count; ++i)
			{
				FTargetableSocketInfo& info = sockets.at(i);
				const bool enable = (event.damage & (1 << i)) != 0;
				const bool critical = (event.health & (1 << i)) != 0;
				if (static_cast<bool>(info.bEnable) != enable)
				{
					info.bEnable = enable ? 1u : 0u;
					++changed;
				}
				if (static_cast<bool>(info.bCriticalUI) != critical)
				{
					info.bCriticalUI = critical ? 1u : 0u;
					++changed;
				}
			}
			static int logsLeft = 40;
			if (changed > 0 && logsLeft > 0)
			{
				--logsLeft;
				char text[96];
				sprintf_s(text, "enabled=0x%X critical=0x%X of %d", static_cast<unsigned>(event.damage),
					static_cast<unsigned>(event.health), count);
				Log("LOCKTARGET " + ObjectName(enemy) + " sockets like the driver: " + text
					+ " (" + std::to_string(changed) + " changed) (locktarget1).");
			}
		}

		// headwake1: a plate the driver shows (out and not hidden) is shown
		// here too - native HideNPCAttachedActor(false), then the actor and its
		// mesh directly if they are still hidden.
		void SyncPlateVisibility(AAliceGameKynapsePawn* enemy, AAliceGameNPCAttachedActor* plate,
			int index, const SharedWorldEventPayload& event, const char* why)
		{
			if (!enemy || !plate || !IsLiveUObject(plate) || (event.flags & 8u) == 0)
				return;
			const bool wantHidden = (event.flags & 4u) != 0;
			USkeletalMeshComponent* const mesh = plate->SkeletalMeshComponent;
			const bool meshHidden = mesh && IsUsableObjectFast(mesh) && mesh->HiddenGame;
			const bool hiddenHere = plate->bHidden || meshHidden;
			if (hiddenHere == wantHidden)
				return;
			static UFunction* const hideFn =
				FindFunctionSafe("Function AliceGame.AliceGameKynapsePawn.HideNPCAttachedActor");
			AAliceGameKynapsePawn_execHideNPCAttachedActor_Params params{};
			params.bSetHidden = wantHidden ? 1u : 0u;
			params.ActorIndex = index;
			const bool ok = hideFn && InvokeNativeFunction(enemy, hideFn, params);
			if (!wantHidden)
			{
				if (plate->bHidden)
					NativeSetActorHidden(plate, false);
				if (mesh && IsUsableObjectFast(mesh) && mesh->HiddenGame)
					NativeSetComponentHidden(mesh, false);
			}
			static int logsLeft = 40;
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("HEADWAKE " + ObjectName(plate) + " (plate " + std::to_string(index) + ", " + why
					+ ") " + (wantHidden ? "hidden" : "shown") + " like the driver: native=" + (ok ? "yes" : "no")
					+ ", was actor=" + std::to_string(plate->bHidden ? 1 : 0) + " mesh=" + (meshHidden ? "1" : "0")
					+ " (headwake1).");
			}
		}

		void OnRemotePlateWake(const SharedWorldEventPayload& event)
		{
			if (!g_config.sharedEnemyHealth || WorldTransitionActive())
				return;
			if (LocallyDrivesSharedEnemy(event.entityKey))
				return;
			AAliceGameKynapsePawn* const enemy = EnemyForSharedKey(event.entityKey);
			const int index = event.damage;
			if (!enemy || !IsLiveUObject(enemy) || enemy->bDeleteMe || enemy->Health <= 0
				|| index < 0 || index >= enemy->NPCAttachedActors.size())
			{
				return;
			}
			AAliceGameNPCAttachedActor* const plate = enemy->NPCAttachedActors.at(index).AttachedActor;
			const bool localOut = plate && IsLiveUObject(plate) && plate->bIsAwake
				&& plate->ActorState != ENPCAttachedActorState::ENPCAAS_Die;
			const bool remoteOut = (event.flags & 1u) != 0;
			const bool remoteDied = (event.flags & 2u) != 0;
			if (localOut == remoteOut)
			{
				if (remoteOut)
					SyncPlateVisibility(enemy, plate, index, event, "already out");
				return;
			}
			// platewake2 (10.11 20:4x: plates 1-5 "brought out" up to 9 times):
			// a plate that died here is never woken again (that revived it),
			// and a plate that died at the driver is left to its replayed hits
			// (PLATEHIT) instead of being put away whole.
			const bool localDead = plate && IsLiveUObject(plate)
				&& plate->ActorState == ENPCAttachedActorState::ENPCAAS_Die;
			if (remoteDied && plate && IsLiveUObject(plate) && plate->FullHP > 0 && plate->FullHP <= 100)
				MarkPlateDead(event.entityKey, enemy, index, "died in the other game"); // platedead1
			const auto deadIt = g_deadPlates.find(event.entityKey);
			const bool knownDead = deadIt != g_deadPlates.end() && deadIt->second.enemy == enemy
				&& index < 16 && (deadIt->second.mask & (1u << index)) != 0;
			if (localDead || knownDead || (!remoteOut && remoteDied))
				return;
			static UFunction* const wakeFn =
				FindFunctionSafe("Function AliceGame.AliceGameKynapsePawn.WakeUpNPCAttachedActor");
			AAliceGameKynapsePawn_execWakeUpNPCAttachedActor_Params params{};
			params.bActive = remoteOut ? 1u : 0u;
			params.ActorIndex = index;
			params.HP = remoteOut ? (std::max)(1, event.health) : 0;
			const bool ok = wakeFn && InvokeNativeFunction(enemy, wakeFn, params);
			AAliceGameNPCAttachedActor* const after = enemy->NPCAttachedActors.at(index).AttachedActor;
			if (remoteOut)
				SyncPlateVisibility(enemy, after, index, event, "brought out");
			static int logsLeft = 60;
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("PLATEWAKE " + ObjectName(enemy) + " plate " + std::to_string(index)
					+ (remoteOut ? " brought out" : " put away") + " like the driver (hp "
					+ std::to_string(event.health) + "/" + std::to_string(event.healthMax)
					+ "): native=" + (ok ? "yes" : "no") + ", plate now " + ObjectName(after)
					+ (after && IsLiveUObject(after) ? std::string(after->bIsAwake ? " awake" : " asleep") : std::string())
					+ " (platewake1).");
			}
		}

		void OnRemoteEnemyArmour(const SharedWorldEventPayload& event)
		{
			if (!g_config.sharedEnemyHealth || WorldTransitionActive())
				return;
			AAliceGameKynapsePawn* const enemy = EnemyForSharedKey(event.entityKey);
			std::string result;
			const int index = event.damage;
			if (!enemy || !IsLiveUObject(enemy) || enemy->bDeleteMe)
				result = "enemy not here";
			else if (index < 0 || index >= enemy->NPCAttachedActors.size())
				result = "no such plate here";
			else
			{
				AAliceGameNPCAttachedActor* const plate =
					enemy->NPCAttachedActors.at(index).AttachedActor;
				if (!plate || !IsLiveUObject(plate))
					result = "plate gone here";
				else
				{
					const bool remoteDead = event.flags
						== static_cast<std::uint8_t>(ENPCAttachedActorState::ENPCAAS_Die);
					const bool localDead = plate->ActorState == ENPCAttachedActorState::ENPCAAS_Die;
					auto& seen = g_armourSeen[event.entityKey];
					if (static_cast<int>(seen.size()) <= index)
						seen.resize(index + 1);
					if (remoteDead && !localDead)
					{
						plate->HP = 0;
						// Native: the SDK wrapper clears FUNC_Native and
						// would turn this into a silent no-op.
						static UFunction* kill = FindFunctionSafe(
							"Function AliceGame.AliceGameKynapsePawn.KillNPCAttachedActor");
						AAliceGameKynapsePawn_execKillNPCAttachedActor_Params parameters{};
						parameters.ActorIndex = index;
						if (!kill || !InvokeNativeFunction(enemy, kill, parameters))
							plate->ActorState = ENPCAttachedActorState::ENPCAAS_Die;
						result = std::string("killed here (state now ")
							+ std::to_string(static_cast<int>(plate->ActorState)) + ')';
					}
					else if (event.health < plate->HP)
					{
						plate->HP = (std::max)(event.health, remoteDead ? 0 : 1);
						result = "hp now " + std::to_string(plate->HP);
					}
					else
						result = "already so here";
					// What we just did is not news to send back.
					seen[index].hp = plate->HP;
					seen[index].state = static_cast<int>(plate->ActorState);
				}
			}
			static int logsLeft = 60;
			if (logsLeft > 0)
			{
				--logsLeft;
				Log("ENEMYARMOUR RX key=" + SharedWorldKeyText(event.entityKey) + " plate "
					+ std::to_string(index) + " hp=" + std::to_string(event.health)
					+ " state=" + std::to_string(event.flags) + ": " + result + '.');
			}
		}

		void TickSharedEnemyPresentation()
		{
			if (!g_config.enabled || !g_config.sharedEnemyTransforms
				|| g_config.localMirror || !g_connected)
			{
				return;
			}
			const auto now = Clock::now();
			if (now < g_nextEnemyPresentationTick)
				return;
			g_nextEnemyPresentationTick = now + std::chrono::milliseconds(50);
			// enemyfree1: nothing is touched while a world is torn down or
			// reloaded (death restart, travel) - the enemies are going away.
			if (WorldTransitionActive() || LeavingWorld())
				return;
			AAlicePawn* const localPawn = GetLocalPawn();
			if (!localPawn)
				return;
			std::unordered_set<AAliceGameKynapsePawn*> seen;
			auto visit = [&](std::uint64_t key, AAliceGameKynapsePawn* enemy)
			{
				// enemyfree1 (12.11 15:53:08 host crash here, read at
				// 0x0D3D0C04 half a second after "Continue" on the death
				// screen of the Executioner): the restart freed the enemies
				// of the old checkpoint while the registry still held them.
				// IsLiveUObject trusts a one-second cache of readable memory
				// regions, and the region had just been released - so the
				// memory is asked about directly first.
				if (!enemy || !IsReadableRange(enemy, 0x40)
					|| !IsLiveUObject(enemy) || enemy->bDeleteMe
					|| !seen.insert(enemy).second)
				{
					return;
				}
				// deathanim1 (31.10): the death animation (Grunt_Attack_Death)
				// is played after health reaches 0 - it was never sent, and the
				// other game's copy stood in its last pose until it vanished
				// 27 s later ("the model stays"). A dying driven enemy is still
				// captured.
				// deathanim2 (31.10 12:54): after the death "who drives it" is
				// no longer known (the host forgets the aggro of a dead enemy,
				// so it thought it drove every dead one): BOTH games sent the
				// animations of their dead copy, and the killer's death
				// animation was overwritten by the other's last hit reaction -
				// frozen bodies on both screens. The game that drove it while it
				// was alive sends its death; the other only receives.
				if (enemy->Health <= 0)
				{
					if (g_drivenWhileAlive[enemy])
						CaptureDrivenEnemyAnims(key, enemy);
					return;
				}
				const bool driven = LocallyDrivesSharedEnemy(key);
				g_drivenWhileAlive[enemy] = driven;
				ApplyEnemyLookTarget(enemy, SharedEnemyLookTarget(key, localPawn),
					driven);
				if (driven)
					CaptureDrivenEnemyAnims(key, enemy);
			};
			if (g_config.role == Role::Host)
			{
				for (const auto& [key, enemy] : g_sharedEnemyRegistry)
					visit(key, enemy);
			}
			else
			{
				for (const auto& [key, binding] : g_clientSharedEnemyBindings)
					if (binding.authorized)
						visit(key, binding.enemy);
			}
			for (auto it = g_enemyAnimTracks.begin(); it != g_enemyAnimTracks.end();)
				it = seen.count(it->first) ? std::next(it) : g_enemyAnimTracks.erase(it);
			for (auto it = g_enemyAnimStopSent.begin(); it != g_enemyAnimStopSent.end();)
				it = seen.count(it->first) ? std::next(it) : g_enemyAnimStopSent.erase(it);
			for (auto it = g_enemyAnimPlayRx.begin(); it != g_enemyAnimPlayRx.end();)
				it = g_sharedEnemyRegistry.empty() ? g_enemyAnimPlayRx.erase(it) : std::next(it);
			for (auto it = g_enemyLookTargets.begin(); it != g_enemyLookTargets.end();)
				it = seen.count(it->first) ? std::next(it) : g_enemyLookTargets.erase(it);
			if (g_config.role == Role::Host)
				TickChaseHostHits(); // chasehit2
		}

		// ---- Shared pickups (SHAREDPICKUP) -------------------------------
		// Teeth (AliceXPPickupFactory: placed teeth and the teeth enemies
		// drop): whoever takes them first keeps them - the other game hides
		// that pickup without giving anything ("found it, it's mine").
		// Memories (MemoryFragmentNormal and its subclasses, taken with the
		// interact key): shared - when one Alice takes a memory, the other
		// game runs the memory's own GiveTo for its Alice, so both have it.
		constexpr SharedWorldEventKind kEventTeethTaken =
			static_cast<SharedWorldEventKind>(18);
		constexpr SharedWorldEventKind kEventMemoryTaken =
			static_cast<SharedWorldEventKind>(19);

		struct PickupWatch
		{
			bool memory = false;
			bool lastTaken = false;
			bool suppressed = false; // taken by the other Alice
			std::uint64_t key = 0;
			FVector origin;           // where it first appeared (teeth fly)
			std::int32_t classHash = 0;
			Clock::time_point firstSeen{};
		};
		// Claims for dropped teeth that this game had not spawned yet.
		struct PendingTeethClaim
		{
			SharedWorldEventPayload event;
			Clock::time_point until;
		};
		std::vector<PendingTeethClaim> g_pendingTeethClaims;
		// The two games drop a different number of teeth for the same enemy
		// (18:38-18:45: the claims matched, yet the host still had a few of
		// the pile left over and took them as "his"). After a claim for a
		// dropped tooth, the rest of that pile here goes to the other Alice
		// too: whoever collected the pile there owns all of it.
		struct TeethPileSweep
		{
			FVector where;
			Clock::time_point due;
		};
		std::vector<TeethPileSweep> g_teethPileSweeps;
		void OnRemotePickupTakenImpl(const SharedWorldEventPayload& event,
			Clock::time_point pendingUntil);
		std::unordered_map<AAliceItemPickupFactory*, PickupWatch> g_pickupWatch;
		std::string g_pickupWatchMap;
		Clock::time_point g_nextPickupScan{};
		Clock::time_point g_nextPickupPoll{};

		bool PickupTaken(AAliceItemPickupFactory* pickup, bool memory)
		{
			if (memory)
				return reinterpret_cast<AMemoryFragmentNormal*>(pickup)->bPickUped != 0;
			return reinterpret_cast<AAliceXPPickupFactory*>(pickup)->bPicked != 0
				|| pickup->bFlyingToAlice != 0;
		}

		bool CallPickupFunction(UObject* object, const char* shortName,
			void* parameters)
		{
			// FindFunction walks all of GObjects: resolve once per class and
			// name (picking up a pile of teeth used to stall the frame).
			static std::unordered_map<std::string, UFunction*> cache;
			const std::string cacheKey =
				object->Class->GetName() + "." + shortName;
			auto found = cache.find(cacheKey);
			if (found == cache.end())
			{
				UFunction* resolved = nullptr;
				// Most-derived implementation first (e.g. MemoryFragment_Pris).
				for (UClass* type = object->Class; type && !resolved;
					type = reinterpret_cast<UClass*>(type->SuperField))
				{
					const std::string className = type->GetName();
					resolved = FindFunctionSafe(
						"Function AliceGame." + className + "." + shortName);
					if (className == "AlicePickupFactory")
						break;
				}
				found = cache.emplace(cacheKey, resolved).first;
			}
			if (!found->second)
				return false;
			object->ProcessEvent(found->second, parameters, nullptr);
			return true;
		}

		bool NativeSetActorPhysics(AActor* actor, std::uint8_t physics)
		{
			static UFunction* function = nullptr;
			if (!function)
				function = FindFunctionSafe(
					"Function Engine.Actor.SetPhysics");
			AActor_execSetPhysics_Params parameters{};
			parameters.newPhysics = physics;
			return InvokeNativeFunction(actor, function, parameters);
		}

		bool NativeSetActorCollision(AActor* actor, bool collide, bool block)
		{
			static UFunction* function = nullptr;
			if (!function)
				function = FindFunctionSafe(
					"Function Engine.Actor.SetCollision");
			AActor_execSetCollision_Params parameters{};
			parameters.bNewColActors = collide;
			parameters.bNewBlockActors = block;
			parameters.bNewIgnoreEncroachers = true;
			return InvokeNativeFunction(actor, function, parameters);
		}

		// Teeth (AliceXPPickupFactory / AliceItemPickupFactory script):
		//   Tick: if (!bPicked && IsValidPick()) fly to the LOCAL player pawn
		//   (LineTrail) and GiveTo it at < 50 units. IsValidPick only checks
		//   bEnablePick and the distance to GetLocalPlayerPawn() - not
		//   visibility, not collision - and the DelayTimeOver timer sets
		//   bEnablePick back to true.
		//   SetPickupHidden: IdleParticle off, PickupParticle on (THE collect
		//   effect, played where the tooth is), Disable('Tick').
		//   ShutDown -> DisablePickup: bIsDisabled, state 'Disabled'.
		// A tooth the other Alice took now flies to her proxy the way it flew
		// to her, bursts with its own PickupParticle there, is shut down for
		// good and - when an enemy dropped it (not placed in the map) -
		// destroyed once the burst has played.
		struct RemoteTeethFlight
		{
			AAliceItemPickupFactory* pickup = nullptr;
			Clock::time_point started;
			Clock::time_point last;
			float flyTime = 0.0f;
			bool finished = false;
			Clock::time_point destroyAt{};
		};
		std::vector<RemoteTeethFlight> g_remoteTeethFlights;

		void DisableTakenPickup(AAliceItemPickupFactory* pickup)
		{
			pickup->bEnablePick = false;
			if (pickup->IsA(AAliceXPPickupFactory::StaticClass()))
				reinterpret_cast<AAliceXPPickupFactory*>(pickup)->bPicked = true;
			NativeSetActorCollision(pickup, false, false);
		}

		void FinishRemoteTeethCollect(RemoteTeethFlight& flight)
		{
			AAliceItemPickupFactory* const pickup = flight.pickup;
			flight.finished = true;
			DisableTakenPickup(pickup);
			CallPickupFunction(pickup, "ShutDown", nullptr);
			if (!pickup->bPickupHidden)
				CallPickupFunction(pickup, "SetPickupHidden", nullptr);
			DisableTakenPickup(pickup);
			const bool placed =
				pickup->IsA(AAliceXPPickupFactory::StaticClass())
				&& reinterpret_cast<AAliceXPPickupFactory*>(pickup)
					->bStaticPutInMap;
			// Placed teeth stay (disabled, bPicked) for the checkpoint
			// record; dropped ones go once the burst has played.
			flight.destroyAt = placed ? Clock::time_point{}
				: Clock::now() + std::chrono::milliseconds(2500);
		}

		void StartRemoteTeethCollect(AAliceItemPickupFactory* pickup)
		{
			for (const RemoteTeethFlight& flight : g_remoteTeethFlights)
				if (flight.pickup == pickup)
					return;
			DisableTakenPickup(pickup);
			NativeSetActorPhysics(pickup, 0); // PHYS_None: the mod moves it
			RemoteTeethFlight flight{};
			flight.pickup = pickup;
			flight.started = flight.last = Clock::now();
			g_remoteTeethFlights.push_back(flight);
		}

		void TickRemoteTeethFlights()
		{
			if (g_remoteTeethFlights.empty())
				return;
			const auto now = Clock::now();
			AActor* const proxy = g_remotePawn && IsLiveUObject(g_remotePawn)
				&& !g_remotePawn->bDeleteMe
				&& g_remotePawn->WorldInfo == g_currentWorld
				? static_cast<AActor*>(g_remotePawn) : nullptr;
			for (auto it = g_remoteTeethFlights.begin();
				it != g_remoteTeethFlights.end();)
			{
				RemoteTeethFlight& flight = *it;
				AAliceItemPickupFactory* const pickup = flight.pickup;
				if (!IsLiveUObject(pickup) || pickup->bDeleteMe
					|| pickup->bPendingDelete)
				{
					it = g_remoteTeethFlights.erase(it);
					continue;
				}
				if (flight.finished)
				{
					if (flight.destroyAt == Clock::time_point{})
					{
						it = g_remoteTeethFlights.erase(it);
						continue;
					}
					if (now >= flight.destroyAt)
					{
						NativeDestroyActor(pickup);
						it = g_remoteTeethFlights.erase(it);
						continue;
					}
					++it;
					continue;
				}
				// Keep the game's own flight (to this Alice) from taking over.
				DisableTakenPickup(pickup);
				const float delta = (std::min)(0.1f,
					std::chrono::duration<float>(now - flight.last).count());
				flight.last = now;
				flight.flyTime += delta;
				bool arrived = !proxy
					|| now - flight.started > std::chrono::milliseconds(1500);
				if (!arrived)
				{
					const FVector target = proxy->Location;
					const FVector direction = target - pickup->Location;
					const float distance = std::sqrt(direction.SizeSquared());
					if (distance < 50.0f)
						arrived = true;
					else
					{
						// LineTrail: Move((Speed * flyTime) * Dir) every tick,
						// scaled here to a 60 fps tick.
						const float speed = pickup->Speed > 0.0f
							? pickup->Speed : 400.0f;
						const float step = (std::min)(distance,
							speed * flight.flyTime * delta * 60.0f);
						const float scale = step / distance;
						FVector next = pickup->Location;
						next.X += direction.X * scale;
						next.Y += direction.Y * scale;
						next.Z += direction.Z * scale;
						NativeSetActorLocationNoCheck(pickup, next);
					}
				}
				if (arrived)
					FinishRemoteTeethCollect(flight);
				++it;
			}
		}

		// ---- Shrink flowers (kind 26) -----------------------------------
		// AliceGame.u ShrinkFlowerInteractive: Idle -> Actived -> FlowerClose
		// (closes on a shrunk Alice) -> Eating -> Shooting (Alice shot out,
		// mesh hidden, petals, DropPickup HP + teeth) -> Finished. It only
		// ever looks at WorldInfo.GetLocalPlayerPawn(), so on the other
		// game it never saw the proxy: it stayed open and kept its teeth.
		// The game whose Alice it caught sends stage 1 (FlowerClose) and
		// stage 2 (Shooting); the other game plays the close animation and
		// then puts the same flower into its own Shooting state - it hides,
		// shoots its petals and drops the teeth there too.
		// No UObject pointer is kept across ticks: the flowers are looked up
		// again (every 2 s, and by name for each event).
		constexpr SharedWorldEventKind kEventShrinkFlower =
			static_cast<SharedWorldEventKind>(26);
		std::unordered_map<std::uint64_t, int> g_shrinkFlowerStages; // key -> last stage sent
		std::unordered_map<std::uint64_t, int> g_shrinkFlowerApplied; // key -> stage applied here
		// Flowers animated here for the OTHER Alice: their animation is not
		// this game's own flower state (25.10: the close animation played for
		// the host's Alice was read back on the client as "this flower caught
		// my Alice", which then refused the host's Shooting stage).
		// key -> when the eating loop follows the close animation.
		std::unordered_map<std::uint64_t, Clock::time_point> g_shrinkFlowerRemoteVisual;
		std::string g_shrinkFlowerWorld;
		Clock::time_point g_nextShrinkFlowerPoll{};

		template <typename Visitor>
		void ForEachShrinkFlower(Visitor visit)
		{
			UClass* const flowerClass = AShrinkFlowerInteractive::StaticClass();
			TArray<UObject*>* objects = UObject::GObjObjects();
			if (!flowerClass || !objects)
				return;
			// perf4: the flowers of this world are looked up every 3 s; in
			// between the list is used (each one checked live).
			static std::vector<UObject*> flowers;
			static std::string flowersWorld;
			static Clock::time_point flowersAt{};
			const auto flowerNow = Clock::now();
			if (flowersWorld != CurrentWorldTag() || flowerNow - flowersAt > std::chrono::seconds(3))
			{
				flowersWorld = CurrentWorldTag();
				flowersAt = flowerNow;
				flowers.clear();
				for (int32_t index = 0; index < objects->size(); ++index)
				{
					UObject* const object = objects->at(index);
					if (object && object->IsA(flowerClass) && !object->IsDefaultObject())
						flowers.push_back(object);
				}
			}
			for (UObject* const object : flowers)
			{
				if (!IsLiveUObject(object) || !IsUsableObjectFast(object))
					continue;
				auto* const flower = reinterpret_cast<AShrinkFlowerInteractive*>(object);
				if (flower->bDeleteMe || flower->WorldInfo != g_currentWorld)
					continue;
				if (!visit(flower))
					return;
			}
		}

		// The flower's state, read from what it shows: every state of
		// ShrinkFlowerInteractive starts its own animation on the single
		// AnimNodeSequence (IdleAnim, ActivedAnim, CloseAnim, EatAliceAnim,
		// ShootingAnim) and Shooting hides the mesh. The 25.10 logs had
		// GetStateName answer "UnknownName" for every flower, so the state
		// machine was never seen leaving Idle and nothing was ever sent.
		bool NativeSetComponentHidden(UPrimitiveComponent* component, bool hidden);

		std::string ShrinkFlowerStateFromAnim(AShrinkFlowerInteractive* flower)
		{
			USkeletalMeshComponent* const mesh = flower->SkeletalMeshComponent;
			if (!mesh)
				return {};
			if (mesh->HiddenGame)
				return "Shooting";
			if (!mesh->Animations || !mesh->Animations->IsA(UAnimNodeSequence::StaticClass()))
				return {};
			const FName playing = reinterpret_cast<UAnimNodeSequence*>(mesh->Animations)->AnimSeqName;
			if (playing == flower->CloseAnim) return "FlowerClose";
			if (playing == flower->EatAliceAnim) return "Eating";
			if (playing == flower->ShootingAnim) return "Shooting";
			if (playing == flower->ActivedAnim) return "Actived";
			if (playing == flower->IdleAnim) return "Idle";
			return {};
		}

		std::string ShrinkFlowerState(AShrinkFlowerInteractive* flower)
		{
			if (std::string fromAnim = ShrinkFlowerStateFromAnim(flower); !fromAnim.empty())
				return fromAnim;
			static UFunction* getState = FindFunctionSafe(
				"Function Core.Object.GetStateName");
			if (!getState)
				return {};
			UObject_execGetStateName_Params parameters{};
			flower->ProcessEvent(getState, &parameters, nullptr);
			return parameters.ReturnValue.ToString();
		}

		void PlayShrinkFlowerAnim(AShrinkFlowerInteractive* flower, const FName& anim,
			bool loop)
		{
			USkeletalMeshComponent* const mesh = flower->SkeletalMeshComponent;
			if (!mesh || !mesh->Animations
				|| !mesh->Animations->IsA(UAnimNodeSequence::StaticClass()))
			{
				return;
			}
			auto* const sequence = reinterpret_cast<UAnimNodeSequence*>(mesh->Animations);
			// Through the real native metadata (the SDK wrappers turn these
			// animation intrinsics into silent no-ops).
			static UFunction* setAnim = FindFunctionSafe(
				"Function Engine.AnimNodeSequence.SetAnim");
			static UFunction* playAnim = FindFunctionSafe(
				"Function Engine.AnimNodeSequence.PlayAnim");
			UAnimNodeSequence_execSetAnim_Params setParameters{};
			setParameters.Sequence = anim;
			InvokeNativeFunction(sequence, setAnim, setParameters);
			UAnimNodeSequence_execPlayAnim_Params playParameters{};
			playParameters.bLoop = loop ? 1u : 0u;
			playParameters.InRate = sequence->Rate > 0.0f ? sequence->Rate : 1.0f;
			playParameters.StartTime = 0.0f;
			InvokeNativeFunction(sequence, playAnim, playParameters);
		}

		void TickShrinkFlowers()
		{
			if (g_shrinkFlowerWorld != CurrentWorldTag())
			{
				g_shrinkFlowerWorld = CurrentWorldTag();
				g_shrinkFlowerStages.clear();
				g_shrinkFlowerApplied.clear();
				g_shrinkFlowerRemoteVisual.clear();
			}
			if (WorldTransitionActive() || LeavingWorld() || g_soloMinigameActive)
				return;
			const auto now = Clock::now();
			if (now < g_nextShrinkFlowerPoll)
				return;
			// The other Alice's flower: after its close animation, the
			// "progress" loop (EatAliceAnim) while she is inside.
			for (auto& [visualKey, eatAt] : g_shrinkFlowerRemoteVisual)
			{
				if (eatAt == Clock::time_point{} || now < eatAt)
					continue;
				eatAt = {};
				const std::uint64_t wanted = visualKey;
				ForEachShrinkFlower([&](AShrinkFlowerInteractive* flower)
				{
					if (WorldTraceHash(ObjectName(flower)) != wanted)
						return true;
					if (ShrinkFlowerStateFromAnim(flower) == "FlowerClose")
						PlayShrinkFlowerAnim(flower, flower->EatAliceAnim, true);
					return false;
				});
			}
			g_nextShrinkFlowerPoll = now + std::chrono::milliseconds(400); // perf3: was 150
			AAlicePawn* const localPawn = GetLocalPawn();
			if (!localPawn)
				return;
			static std::unordered_map<std::uint64_t, std::string> seenStates;
			static int seenLogsLeft = 60;
			ForEachShrinkFlower([&](AShrinkFlowerInteractive* flower)
			{
				const float dx = flower->Location.X - localPawn->Location.X;
				const float dy = flower->Location.Y - localPawn->Location.Y;
				const float dz = flower->Location.Z - localPawn->Location.Z;
				const float distance = std::sqrt(dx * dx + dy * dy + dz * dz);
				if (distance > 1500.0f)
					return true;
				const std::string state = ShrinkFlowerState(flower);
				const std::uint64_t seenKey = WorldTraceHash(ObjectName(flower));
				if (seenStates[seenKey] != state && seenLogsLeft > 0)
				{
					--seenLogsLeft;
					seenStates[seenKey] = state;
					Log("SHRINKFLOWER seen " + ObjectName(flower) + " state="
						+ (state.empty() ? std::string("<unknown>") : state)
						+ ", alice=" + ObjectName(flower->Alice)
						+ ", mine=" + (flower->Alice == localPawn ? "yes" : "no")
						+ ", distance=" + std::to_string(distance)
						+ ", interactive=" + std::to_string(flower->InteractiveRadius)
						+ ", shrunk=" + (localPawn->bShrinkingModeActive ? "1" : "0") + '.');
				}
				// Only a flower that caught this game's own Alice: its Alice
				// field, or (should that not match) her standing in it.
				// Only a flower that caught this game's own Alice. Its Alice
				// field is set as soon as she walks near (Actived), so she must
				// also be in it: FlowerClose puts her on the flower's spot.
				const bool inside = distance < (std::max)(flower->InteractiveRadius * 2.0f, 150.0f);
				const bool mine = inside
					&& (flower->Alice == localPawn || localPawn->bShrinkingModeActive
						|| localPawn->bShrinkFlowerEating || state == "Shooting");
				if (!mine)
					return true;
				const int stage = (state == "FlowerClose" || state == "Eating") ? 1
					: (state == "Shooting" || state == "Finished") ? 2 : 0;
				if (stage == 0)
					return true;
				const std::uint64_t key = WorldTraceHash(ObjectName(flower));
				int& sent = g_shrinkFlowerStages[key];
				if (stage <= sent)
					return true;
				sent = stage;
				SharedWorldEventPayload event{};
				event.kind = kEventShrinkFlower;
				event.entityKey = key;
				event.originActorId = g_config.role == Role::Host ? 1u : 2u;
				event.flags = static_cast<std::uint32_t>(stage);
				QueueSharedWorldEvent(event);
				Log("SHRINKFLOWER TX " + ObjectName(flower) + " stage="
					+ std::to_string(stage) + " (" + state + ").");
				return true;
			});
		}

		// ---- SEQEVENT: which level events fire on one game only ----------
		// Every Kismet event bumps its TriggerCount when it fires, by any
		// path (native touch, script, Used, pads, shrink morph...). The
		// counts are compared every 500 ms, keyed by name (no pointers kept
		// across ticks). Each firing is logged with who caused it, so the two
		// players' logs show which events fire for one game only.
		std::unordered_map<std::uint64_t, std::int32_t> g_seqEventCounts;
		std::string g_seqEventWorld;
		Clock::time_point g_nextSeqEventScan{};
		bool g_seqEventPrimed = false;

		void TickSeqEventTrace()
		{
			if (g_seqEventWorld != CurrentWorldTag())
			{
				g_seqEventWorld = CurrentWorldTag();
				g_seqEventCounts.clear();
				g_seqEventPrimed = false;
			}
			if (WorldTransitionActive() || LeavingWorld())
				return;
			const auto now = Clock::now();
			if (now < g_nextSeqEventScan)
				return;
			g_nextSeqEventScan = now + std::chrono::milliseconds(1000); // perf3: was 500
			static int logsLeft = 1200;
			UClass* const eventClass = USequenceEvent::StaticClass();
			TArray<UObject*>* objects = UObject::GObjObjects();
			if (!eventClass || !objects)
				return;
			AAlicePawn* const localPawn = GetLocalPawn();
			const AActor* const localController = g_State.AlicePlayerController;
			for (int32_t index = 0; index < objects->size(); ++index)
			{
				UObject* const object = objects->at(index);
				if (!object || !object->IsA(eventClass) || object->IsDefaultObject()
					|| !IsUsableObjectFast(object)) // perf3: the class test first
				{
					continue;
				}
				auto* const event = reinterpret_cast<USequenceEvent*>(object);
				const std::string name = ObjectName(event);
				const std::uint64_t key = WorldTraceHash(name);
				auto found = g_seqEventCounts.find(key);
				if (found == g_seqEventCounts.end())
				{
					g_seqEventCounts.emplace(key, event->TriggerCount);
					continue;
				}
				if (event->TriggerCount == found->second)
					continue;
				const std::int32_t before = found->second;
				found->second = event->TriggerCount;
				if (!g_seqEventPrimed)
					continue;
				// joinlatest1: the 1200-line log budget used to end the
				// checkpoint sharing below too (long sessions stopped sharing
				// checkpoints); only the log line is limited now.
				const bool logIt = logsLeft > 0;
				if (logIt)
					--logsLeft;
				const AActor* const instigator = event->Instigator;
				const char* who = !instigator ? "none"
					: (instigator == localPawn || instigator == localController) ? "LOCAL-ALICE"
					: (g_remotePawn && instigator == g_remotePawn) ? "proxy"
					: "other";
				std::string extra;
				if (event->IsA(USeqEvent_AliceContext::StaticClass()))
				{
					extra += ", contextItem=" + std::to_string(static_cast<int>(
						reinterpret_cast<USeqEvent_AliceContext*>(event)->ContextItem));
				}
				// What it starts: the ops on its outputs (first few).
				{
					std::string ops;
					int shown = 0;
					const int32_t outputs = std::min<int32_t>(event->OutputLinks.size(), 4);
					for (int32_t o = 0; o < outputs && shown < 4; ++o)
					{
						const FSeqOpOutputLink& link = event->OutputLinks.at(o);
						const int32_t links = std::min<int32_t>(link.Links.size(), 4);
						for (int32_t l = 0; l < links && shown < 4; ++l)
						{
							USequenceOp* const op = link.Links.at(l).LinkedOp;
							if (!op || !IsUsableObjectFast(op))
								continue;
							ops += (shown ? " " : "") + std::to_string(o) + ':'
								+ op->Class->GetName();
							++shown;
						}
					}
					if (!ops.empty())
						extra += ", starts=[" + ops + ']';
				}
				if (logIt)
				{
					Log("SEQEVENT " + event->Class->GetName() + " fired "
						+ std::to_string(before) + "->" + std::to_string(event->TriggerCount)
						+ ": " + name + ", originator=" + ObjectName(event->Originator)
						+ ", instigator=" + ObjectName(instigator) + " (" + who + ")"
						+ extra + '.');
				}
				if (before == 0 && !event->IsA(USeqEvent_SequenceActivated::StaticClass())
					&& name.find(".Checkpoints.") != std::string::npos)
				{
					const std::uint64_t lastKey = SequenceActionStableKey(event);
					if (lastKey)
					{
						g_lastCheckpointEventKey = lastKey; // joinlatest1
						g_lastCheckpointEventMap = g_currentMap;
						g_lastCheckpointEventName = name;
					}
				}
				// checkpointshare1 (10.11 20:13:23, chapter 4 Colossal Ruin
				// arena): the host's Checkpoints.SeqEvent_RemoteEvent_4 saved
				// the arena checkpoint; the client's never fired, and the
				// restart at 20:15:23 put the client back at the old checkpoint
				// (34415,-30387: before the teapot and its cutscene) while the
				// host stood in the arena. A level checkpoint event that fires
				// in one game is sent; the other fires it too if it has not.
				if (g_connected && !g_config.localMirror && before == 0
					&& !event->IsA(USeqEvent_SequenceActivated::StaticClass())
					&& name.find(".Checkpoints.") != std::string::npos)
				{
					const std::uint64_t shareKey = SequenceActionStableKey(event);
					const auto replay = g_sharedSeqReplayUntil.find(shareKey);
					if (shareKey && (replay == g_sharedSeqReplayUntil.end()
						|| Clock::now() >= replay->second))
					{
						SharedWorldEventPayload share{};
						share.kind = static_cast<SharedWorldEventKind>(27);
						share.entityKey = shareKey;
						share.flags = 1u; // a checkpoint event
						share.originActorId = g_config.role == Role::Host ? 1u : 2u;
						QueueSharedWorldEvent(share);
						Log("CHECKPOINTSHARE TX " + name + '.');
					}
				}
			}
			g_seqEventPrimed = true;
		}

		// ---- Shared level events beyond touches (kind 27) ----------------
		// SeqEvent_LOS (look at something -> its Matinee/sound; the 24.10
		// test: VoT_03_S.SeqEvent_LOS_1 fired on each game on its own,
		// 9 s apart). The game whose Alice fired it sends its stable key;
		// the other game fires the same event with its own Alice as the
		// instigator, through the engine's CheckActivate.
		bool IsSharedSeqEventClass(UObject* op)
		{
			return op && op->IsA(USeqEvent_LOS::StaticClass());
		}

		void OnRemoteSharedSeqEvent(const SharedWorldEventPayload& payload)
		{
			if (WorldTransitionActive() || LeavingWorld() || g_soloMinigameActive)
				return;
			AAlicePawn* const localPawn = GetLocalPawn();
			if (!localPawn)
				return;
			USequenceEvent* found = nullptr;
			TArray<UObject*>* objects = UObject::GObjObjects();
			for (int32_t index = 0; objects && index < objects->size(); ++index)
			{
				UObject* const object = objects->at(index);
				const bool checkpointShare = (payload.flags & 1u) != 0; // checkpointshare1
				if (!object || object->IsDefaultObject() || !IsUsableObjectFast(object)
					|| (checkpointShare ? !object->IsA(USequenceEvent::StaticClass())
						: !IsSharedSeqEventClass(object)))
				{
					continue;
				}
				if (SequenceActionStableKey(object) == payload.entityKey)
				{
					found = reinterpret_cast<USequenceEvent*>(object);
					break;
				}
			}
			std::string result;
			if (!found)
				result = "not found here";
			else if ((payload.flags & 1u) != 0 && found->TriggerCount > 0)
				result = "checkpoint already saved here";
			else if ((payload.flags & 1u) == 0 && found->MaxTriggerCount <= 0)
				result = "repeatable look-at event, not shared";
			else if (found->MaxTriggerCount > 0
				&& found->TriggerCount >= found->MaxTriggerCount)
			{
				result = "already fired here";
			}
			else
			{
				g_sharedSeqReplayUntil[payload.entityKey] =
					Clock::now() + std::chrono::seconds(3);
				TArray<int32_t> activateIndices;
				bool activated = NativeCheckSequenceEvent(found,
					found->Originator, localPawn, false, false, activateIndices);
				std::string how;
				// checkpointshare2 (10.11 23:16:02, Colossal Ruin arena): the
				// host's arena checkpoint (Checkpoints.SeqEvent_RemoteEvent_4)
				// reached the client but did not fire there ("fired=no"): a
				// remote event fires with the WorldInfo as originator and
				// instigator (as at the host), and may still be switched off
				// in a game whose Kismet has not got that far. The restart put
				// the client back at the old checkpoint, away from the arena.
				if (!activated && (payload.flags & 1u) != 0 && g_currentWorld)
				{
					TArray<int32_t> retryIndices;
					activated = NativeCheckSequenceEvent(found, g_currentWorld, g_currentWorld,
						false, false, retryIndices);
					how = activated ? ", as the world" : "";
					if (!activated && !found->bEnabled)
					{
						found->bEnabled = 1u;
						TArray<int32_t> enabledIndices;
						activated = NativeCheckSequenceEvent(found, g_currentWorld, g_currentWorld,
							false, false, enabledIndices);
						if (!activated)
							found->bEnabled = 0u;
						how = activated ? ", switched on first" : ", disabled here";
					}
				}
				result = std::string("fired=") + (activated ? "yes" : "no")
					+ ", count=" + std::to_string(found->TriggerCount) + how + " (checkpointshare2)";
			}
			Log("SHAREDSEQ RX " + (found ? ObjectName(found) : SharedWorldKeyText(payload.entityKey))
				+ ": " + result + '.');
			// joinlatest1: the host's latest checkpoint, sent when this client
			// came into its map - saved here now, the checkpoint restart takes
			// this Alice to it (instead of the chapter start the join loads).
			if ((payload.flags & 2u) != 0 && g_config.role == Role::Client && found
				&& result.rfind("fired=yes", 0) == 0
				&& g_joinLoadedAt != Clock::time_point{}
				&& Clock::now() - g_joinLoadedAt < std::chrono::seconds(60))
			{
				g_joinRestartPending = true;
				g_joinRestartArmedAt = Clock::now();
				Log("JOINLATEST the host's latest checkpoint is saved here: both games restart from"
					" their checkpoint in 4 s, so this Alice comes in where the host is (joinlatest1).");
			}
		}

		void OnRemoteShrinkFlower(const SharedWorldEventPayload& event)
		{
			if (WorldTransitionActive() || LeavingWorld())
				return;
			const int stage = static_cast<int>(event.flags & 3u);
			int& applied = g_shrinkFlowerApplied[event.entityKey];
			if (stage <= applied)
				return;
			AAlicePawn* const localPawn = GetLocalPawn();
			bool found = false;
			std::string result = "not found here";
			ForEachShrinkFlower([&](AShrinkFlowerInteractive* flower)
			{
				if (WorldTraceHash(ObjectName(flower)) != event.entityKey)
					return true;
				found = true;
				const std::string state = ShrinkFlowerState(flower);
				const float bx = flower->Location.X - (localPawn ? localPawn->Location.X : 0.0f);
				const float by = flower->Location.Y - (localPawn ? localPawn->Location.Y : 0.0f);
				const bool localInside = localPawn
					&& std::sqrt(bx * bx + by * by)
						< (std::max)(flower->InteractiveRadius * 2.0f, 150.0f)
					&& (localPawn->bShrinkFlowerEating || localPawn->bShrinkingModeActive);
				if (localInside && flower->Alice == localPawn
					&& (state == "FlowerClose" || state == "Eating"))
				{
					result = "busy with this game's own Alice (" + state + ")";
					return false;
				}
				if (state == "Shooting" || state == "Finished")
				{
					applied = 2;
					result = "already " + state;
					return false;
				}
				applied = stage;
				if (stage == 1)
				{
					// Visual only: FlowerClose.BeginState would move and
					// freeze this game's own Alice.
					PlayShrinkFlowerAnim(flower, flower->CloseAnim, false);
					float closeLength = 1.0f;
					if (USkeletalMeshComponent* const mesh = flower->SkeletalMeshComponent;
						mesh && mesh->Animations
						&& mesh->Animations->IsA(UAnimNodeSequence::StaticClass()))
					{
						auto* const sequence = reinterpret_cast<UAnimNodeSequence*>(mesh->Animations);
						if (sequence->AnimSeq && sequence->AnimSeq->SequenceLength > 0.05f)
							closeLength = sequence->AnimSeq->SequenceLength
								/ (sequence->Rate > 0.0f ? sequence->Rate : 1.0f);
					}
					g_shrinkFlowerRemoteVisual[event.entityKey] = Clock::now()
						+ std::chrono::milliseconds(static_cast<int>(closeLength * 1000.0f));
					result = "close animation, then the eating loop";
				}
				else
				{
					static UFunction* gotoState = FindFunctionSafe(
						"Function Core.Object.GotoState");
					if (gotoState)
					{
						UObject_execGotoState_Params parameters{};
						parameters.NewState = FName("Shooting");
						flower->ProcessEvent(gotoState, &parameters, nullptr);
					}
					std::string now = ShrinkFlowerState(flower);
					if (now != "Shooting" && now != "Finished")
					{
						// GotoState did not take: show its result by hand -
						// the flower disappears in a burst of petals.
						// SetHidden only re-registers the mesh when the flag
						// CHANGES - setting HiddenGame first (as before) made it
						// a no-op and the flower stayed visible (25.10).
						if (USkeletalMeshComponent* const mesh = flower->SkeletalMeshComponent)
						{
							NativeSetComponentHidden(mesh, true);
							if (!mesh->HiddenGame)
								mesh->HiddenGame = true;
						}
						// Spent: it must not catch this game's Alice again
						// (its Idle/Actived tick would close a hidden flower on her).
						flower->bTickIsDisabled = true;
						// flowerspent1 (31.10 17:09): hidden but still usable -
						// the other Alice could walk in and use the invisible
						// flower. No collision, no interaction radius, no Alice.
						NativeSetActorHidden(flower, true);
						NativeSetActorCollision(flower, false, false);
						flower->InteractiveRadius = 0.0f;
						flower->Alice = nullptr;
						if (flower->ShootingPetalsParticle && flower->WorldInfo
							&& flower->WorldInfo->MyEmitterPool)
						{
							UParticleSystemComponent* const petals =
								flower->WorldInfo->MyEmitterPool->SpawnEmitter(
									flower->ShootingPetalsParticle, flower->Location,
									flower->Rotation, nullptr, false);
							MakePresentationParticleVisible(petals);
						}
						now += " (shown by hand)";
					}
					result = std::string("Shooting (petals, teeth) -> now ") + now;
				}
				return false;
			});
			Log("SHRINKFLOWER RX stage=" + std::to_string(stage) + ": "
				+ (found ? result : std::string("not found here")) + '.');
		}

		// pickupname1 (30.10 00:53 client crash): a teeth pickup just dropped
		// by a dying enemy was named while its name/outer were not set up yet
		// (GetFullName -> FName::ToString read 0x78). Named under SEH now.
		void FullNameInto(UObject* object, std::string* out)
		{
			*out = object->GetFullName();
		}

		__declspec(noinline) bool GuardedFullName(UObject* object, std::string* out)
		{
			__try
			{
				FullNameInto(object, out);
				return true;
			}
			__except (EXCEPTION_EXECUTE_HANDLER)
			{
				return false;
			}
		}

		void TickSharedPickups()
		{
			if (LeavingWorld())
			{
				TickSharedPause(); // resets itself on the next world
				TickSharedBoards();
				return;
			}
			// Hints also on a host playing alone (it remembers which ones it
			// had, for a client joining later).
			if (g_config.enabled && !g_config.localMirror && !g_connected
				&& g_config.role == Role::Host)
			{
				TickSharedHints();
			}
			if (g_config.enabled && !g_config.localMirror && g_connected)
			{
				{ PerfScope perfScope_("Pickups.Breakables"); TickSharedBreakables(); TickBreakableResync(); }
				{ PerfScope perfScope_("Pickups.Hints"); TickSharedHints(); }
				{ PerfScope perfScope_("Pickups.Pause"); TickSharedPause(); }
				{ PerfScope perfScope_("Pickups.Boards"); TickSharedBoards(); }
				{ PerfScope perfScope_("Pickups.ShrinkFlowers"); TickShrinkFlowers(); }
				{ PerfScope perfScope_("Pickups.SeqEventTrace"); TickSeqEventTrace(); }
			}
			if (!g_config.enabled || g_config.localMirror || !g_connected
				|| !g_config.sharedPickups || g_soloMinigameActive)
			{
				return;
			}
			const auto now = Clock::now();
			if (g_pickupWatchMap != CurrentWorldTag())
			{
				g_pickupWatch.clear();
				g_remoteTeethFlights.clear();
				g_pendingTeethClaims.clear();
				g_teethPileSweeps.clear();
				g_pickupWatchMap = CurrentWorldTag();
			}
			{ PerfScope perfScope_("Pickups.TeethFlights"); TickRemoteTeethFlights(); }
			if (now < g_nextPickupPoll)
				return;
			g_nextPickupPoll = now + std::chrono::milliseconds(50);
			if (now >= g_nextPickupScan)
			{
				g_nextPickupScan = now + std::chrono::milliseconds(1000); // perf3: was 500
				TArray<UObject*>* objects = UObject::GObjObjects();
				for (int32_t index = 0; objects && index < objects->size(); ++index)
				{
					UObject* object = objects->at(index);
					if (!object || object->IsDefaultObject())
						continue;
					const bool teeth = object->IsA(AAliceXPPickupFactory::StaticClass());
					const bool memory = !teeth
						&& object->IsA(AMemoryFragmentNormal::StaticClass());
					if (!teeth && !memory)
						continue;
					auto* pickup = reinterpret_cast<AAliceItemPickupFactory*>(object);
					if (pickup->bDeleteMe || pickup->WorldInfo != g_currentWorld
						|| g_pickupWatch.count(pickup)
						|| (object->ObjectFlags & (RF_PendingKill | RF_Unreachable
							| RF_BeginDestroyed | RF_FinishDestroyed)) != 0)
					{
						continue;
					}
					std::string pickupName;
					std::string className;
					if (!pickup->Class || !GuardedFullName(pickup, &pickupName)
						|| !GuardedFullName(pickup->Class, &className))
					{
						continue; // not set up yet: next scan
					}
					PickupWatch watch{};
					watch.memory = memory;
					watch.lastTaken = PickupTaken(pickup, memory);
					watch.key = WorldTraceHash(pickupName);
					watch.origin = pickup->Location;
					watch.firstSeen = Clock::now();
					watch.classHash = static_cast<std::int32_t>(
						WorldTraceHash(className) & 0x7FFFFFFF);
					g_pickupWatch.emplace(pickup, watch);
				}
			}
			for (auto it = g_pickupWatch.begin(); it != g_pickupWatch.end();)
			{
				AAliceItemPickupFactory* const pickup = it->first;
				PickupWatch& watch = it->second;
				if (!IsLiveUObject(pickup) || pickup->bDeleteMe)
				{
					it = g_pickupWatch.erase(it);
					continue;
				}
				const bool taken = PickupTaken(pickup, watch.memory);
				if (taken && !watch.lastTaken && !watch.suppressed)
				{
					SharedWorldEventPayload event{};
					event.kind = watch.memory ? kEventMemoryTaken : kEventTeethTaken;
					event.entityKey = watch.key;
					event.originActorId = g_config.role == Role::Host ? 1u : 2u;
					event.health = watch.classHash;
					// bit0: placed in the map (same object name on both
					// games); otherwise dropped by an enemy, named in spawn
					// order, which differs between the two games.
					event.flags = (!watch.memory
						&& reinterpret_cast<AAliceXPPickupFactory*>(pickup)
							->bStaticPutInMap) ? 1u : 0u;
					event.hitLocation[0] = watch.origin.X;
					event.hitLocation[1] = watch.origin.Y;
					event.hitLocation[2] = watch.origin.Z;
					QueueSharedWorldEvent(event);
					static int logsLeft = 40;
					if (logsLeft > 0)
					{
						--logsLeft;
						Log(std::string("SHAREDPICKUP TX ")
							+ (watch.memory ? "memory " : "teeth ")
							+ ObjectName(pickup) + ", origin="
							+ FormatWorldTraceVector(watch.origin) + ", now="
							+ FormatWorldTraceVector(pickup->Location)
							+ (event.flags & 1u ? ", placed" : ", dropped") + '.');
					}
				}
				watch.lastTaken = taken;
				++it;
			}
			// Hand the rest of a claimed pile to the other Alice as well.
			if (!g_teethPileSweeps.empty())
			{
				std::vector<TeethPileSweep> sweeps;
				sweeps.swap(g_teethPileSweeps);
				for (const TeethPileSweep& sweep : sweeps)
				{
					if (now < sweep.due)
					{
						g_teethPileSweeps.push_back(sweep);
						continue;
					}
					int swept = 0;
					for (auto& [pickup, watch] : g_pickupWatch)
					{
						if (watch.memory || watch.lastTaken || watch.suppressed
							|| !IsLiveUObject(pickup) || pickup->bDeleteMe
							|| reinterpret_cast<AAliceXPPickupFactory*>(pickup)
								->bStaticPutInMap
							|| PickupTaken(pickup, false)
							|| now - watch.firstSeen > std::chrono::seconds(20))
						{
							continue;
						}
						constexpr float PileRadius = 450.0f;
						const bool nearOrigin = (watch.origin - sweep.where)
							.SizeSquared() < PileRadius * PileRadius;
						const bool nearNow = (pickup->Location - sweep.where)
							.SizeSquared() < PileRadius * PileRadius;
						if (!nearOrigin && !nearNow)
							continue;
						watch.suppressed = true;
						watch.lastTaken = true;
						StartRemoteTeethCollect(pickup);
						++swept;
					}
					if (swept > 0)
					{
						Log("SHAREDPICKUP pile sweep at "
							+ FormatWorldTraceVector(sweep.where) + ": "
							+ std::to_string(swept)
							+ " leftover tooth/teeth went to the other Alice.");
					}
				}
			}
			// Retry claims for teeth that had not appeared here yet.
			if (!g_pendingTeethClaims.empty())
			{
				std::vector<PendingTeethClaim> pending;
				pending.swap(g_pendingTeethClaims);
				for (PendingTeethClaim& claim : pending)
				{
					// Expired claims run once more: they log "not found" and
					// still hand the rest of that pile over.
					OnRemotePickupTakenImpl(claim.event, claim.until);
				}
			}
		}

		void OnRemotePickupTaken(const SharedWorldEventPayload& event)
		{
			OnRemotePickupTakenImpl(event, Clock::time_point{});
		}

		void OnRemotePickupTakenImpl(const SharedWorldEventPayload& event,
			Clock::time_point pendingUntil)
		{
			if (!g_config.sharedPickups)
				return;
			const bool memory = event.kind == kEventMemoryTaken;
			const FVector where(event.hitLocation[0], event.hitLocation[1],
				event.hitLocation[2]);
			AAliceItemPickupFactory* match = nullptr;
			float bestDistance = 500.0f * 500.0f;
			for (auto& [pickup, watch] : g_pickupWatch)
			{
				if (!IsLiveUObject(pickup) || pickup->bDeleteMe
					|| watch.memory != memory)
				{
					continue;
				}
				const bool placed = memory || (event.flags & 1u) != 0;
				if (placed && watch.key == event.entityKey)
				{
					match = pickup;
					break;
				}
				// Teeth dropped by an enemy get a name in spawn order, and
				// the two games spawn in a different order (00:27:17: the
				// client's XPPickup_25 was another tooth, already taken, on
				// the host). Match the nearest untaken one of the same class.
				if (!placed && !watch.lastTaken && !watch.suppressed
					&& watch.classHash == event.health)
				{
					const float distance = (watch.origin - where).SizeSquared();
					if (distance < bestDistance)
					{
						bestDistance = distance;
						match = pickup;
					}
				}
			}
			std::string result;
			if (!match && !memory)
			{
				// The enemy that dropped them may not have died here yet:
				// keep the claim for a few seconds and retry.
				const auto now = Clock::now();
				const auto until = pendingUntil == Clock::time_point{}
					? now + std::chrono::seconds(6) : pendingUntil;
				if (now < until)
				{
					g_pendingTeethClaims.push_back(PendingTeethClaim{ event, until });
					return;
				}
				result = "not found here";
			}
			else if (!match)
				result = "not found here";
			else if (PickupTaken(match, memory))
				result = "already taken here";
			else
			{
				PickupWatch& watch = g_pickupWatch[match];
				watch.suppressed = true;
				if (memory)
				{
					AAlicePawn* const localPawn = GetLocalPawn();
					AMemoryFragmentNormal_execGiveTo_Params give{};
					give.P = localPawn;
					const bool given = localPawn
						&& CallPickupFunction(match, "GiveTo", &give);
					result = given ? "given to this Alice" : "GiveTo missing";
				}
				else
				{
					StartRemoteTeethCollect(match);
					result = "flying to the other Alice";
				}
				watch.lastTaken = true;
			}
			if (!memory && (event.flags & 1u) == 0)
			{
				// Let the rest of the pile land first (teeth scatter and
				// the claims of one pile arrive within ~1 s).
				const auto due = Clock::now() + std::chrono::milliseconds(1500);
				bool merged = false;
				for (TeethPileSweep& sweep : g_teethPileSweeps)
				{
					if ((sweep.where - where).SizeSquared() < 300.0f * 300.0f)
					{
						sweep.due = due;
						merged = true;
						break;
					}
				}
				if (!merged)
					g_teethPileSweeps.push_back(TeethPileSweep{ where, due });
			}
			static int rxLogsLeft = 60;
			if (rxLogsLeft > 0 || memory)
			{
				--rxLogsLeft;
				std::string where_text = ", peerOrigin=" + FormatWorldTraceVector(where);
				if (match)
				{
					const FVector mine = g_pickupWatch.count(match)
						? g_pickupWatch[match].origin : match->Location;
					where_text += ", localOrigin=" + FormatWorldTraceVector(mine)
						+ ", gap=" + std::to_string(static_cast<int>(
							std::sqrt((mine - where).SizeSquared())));
				}
				Log(std::string("SHAREDPICKUP RX ") + (memory ? "memory " : "teeth ")
					+ ObjectName(match) + where_text + ": " + result + '.');
			}
		}




		// ---- Shared pause (SHAREDPAUSE) ---------------------------------
		// v3. The game's in-game menu (AliceGfxMovie_inGameMenu, bIsOpen) is
		// the only truth. v2 decided "open/closed" from Escape presses and
		// answered the peer with injected Escapes; with both players pressing
		// Escape (20:17:34-40) the injected keys crossed the real ones, the
		// menus ended closed while the world stayed paused, and nothing could
		// open or close the menu any more.
		// Now: the open state is polled from the menu itself; only a real
		// change is sent. The peer opens its menu with one Escape (only if it
		// is closed), and closes it directly (continueGame + GFxMovie.Close),
		// never with a key. After any shared pause activity, a world that is
		// still paused with no menu open is unpaused by force.
		constexpr SharedWorldEventKind kEventPause =
			static_cast<SharedWorldEventKind>(21);
		bool g_pauseLastOpen = false;
		// Set from the menu's own calls (UITRACE 20:53-20:56): opening calls
		// inGameMenu.CanPressRestartGame, resuming calls continueGame.
		bool g_inGameMenuOpenSignal = false;
		// The pause movie is being restarted by the mod (see
		// RestartMenusFresh): its Flash re-initialises and may call back
		// into the script; that is not the player opening the menu.
		Clock::time_point g_menuRestartQuietUntil{}; // (v13, unused)
		// v14: only the calls made while the restart itself runs are
		// ignored. v13 ignored 1.5 s after it, which swallowed the menu's
		// real opening by the next Escape (21:04:35.711): it was pressed
		// again, closed the menu and a third press opened it - the double
		// pause. The restart itself calls nothing back (21:04:34 log).
		bool g_menuRestarting = false;
		Clock::time_point g_pauseGuardUntil{};    // changes we caused
		Clock::time_point g_inGameMenuSignalChangedAt{};
		// A setting was changed in this pause menu (its set*/Change*/Invert*
		// calls from the menu's ActionScript), not necessarily applied.
		bool g_pauseSettingsTouched = false;
		int g_pauseExpect = -1;                   // the state we caused
		Clock::time_point g_pauseActivityUntil{}; // stuck-pause watchdog window
		Clock::time_point g_pauseNoMenuSince{};
		Clock::time_point g_nextPausePoll{};

		bool SharedPauseAvailable()
		{
			return g_config.enabled && g_config.sharedPause
				&& !g_config.localMirror && g_connected
				&& (!g_soloMinigameActive // shootpause1: the ship game pauses together
					|| ContainsCaseInsensitive(g_soloMinigameLevel, "Ride"))
				&& !g_currentMap.empty()
				&& _stricmp(g_currentMap.c_str(), "AliceEntry") != 0;
		}

		// Kept for the callers (menu events, Escape fallback): v3 sends from
		// the polled menu state instead, so these only log.
		void SendLocalPauseState(bool open)
		{
			(void)open;
		}

		template <typename Visitor>
		void ForEachOpenInGameMenu(Visitor visit)
		{
			TArray<UObject*>* objects = UObject::GObjObjects();
			for (int32_t index = 0; objects && index < objects->size(); ++index)
			{
				UObject* object = objects->at(index);
				if (!object || object->IsDefaultObject()
					|| !IsUsableObjectFast(object)
					|| !object->IsA(UAliceGfxMovie_inGameMenu::StaticClass()))
				{
					continue;
				}
				auto* menu = reinterpret_cast<UAliceGfxMovie_inGameMenu*>(object);
				if (menu->bIsOpen)
					visit(menu);
			}
		}

		int CountOpenInGameMenus()
		{
			int count = 0;
			ForEachOpenInGameMenu([&count](UAliceGfxMovie_inGameMenu*) { ++count; });
			return count;
		}

		// continueGame only (v3 also called GFxMovie.Close, which can leave the
		// menu movie unusable afterwards).
		int ContinueOpenInGameMenus()
		{
			static UFunction* continueGame = nullptr;
			if (!continueGame)
				continueGame = FindFunctionSafe(
					"Function AliceGame.AliceGfxMovie_inGameMenu.continueGame");
			int count = 0;
			ForEachOpenInGameMenu([&](UAliceGfxMovie_inGameMenu* menu)
			{
				if (continueGame)
				{
					std::uint8_t parameters[16]{};
					menu->ProcessEvent(continueGame, parameters, nullptr);
				}
				++count;
			});
			return count;
		}

		bool WorldPaused()
		{
			return g_currentWorld && IsUsableObjectFast(g_currentWorld)
				&& g_currentWorld->Pauser != nullptr;
		}

		void ForceUnpauseWorld(const char* reason)
		{
			if (!WorldPaused())
				return;
			g_currentWorld->Pauser = nullptr;
			AGameInfo* const game = g_currentWorld->Game;
			if (game && IsUsableObjectFast(game))
				reinterpret_cast<RawGameArray&>(game->Pausers).num = 0;
			Log(std::string("SHAREDPAUSE world was still paused (") + reason
				+ "): unpaused.");
		}

		bool StopMemoryVideo();
		int MenusToMainPage();

		std::string ResumeMenusDirectly(bool revertSettings)
		{
			static UFunction* leaveControl = FindFunctionSafe(
				"Function AliceGame.AliceGfxMovie_inGameMenu.leaveControl");
			static UFunction* loadConfig = FindFunctionSafe(
				"Function AliceGame.AliceGFXMovie.interface_LoadConfigData");
			static UFunction* continueGame = FindFunctionSafe(
				"Function AliceGame.AliceGfxMovie_inGameMenu.continueGame");
			static UFunction* close = FindFunctionSafe(
				"Function GFxUI.GFxMovie.Close");
			const bool bink = StopMemoryVideo();
			int menus = 0;
			bool reverted = false;
			ForEachOpenInGameMenu([&](UAliceGfxMovie_inGameMenu* menu)
			{
				++menus;
				std::uint8_t none[16]{};
				if (menu->APC)
				{
					if (leaveControl)
						menu->ProcessEvent(leaveControl, none, nullptr);
					if (revertSettings && loadConfig && !reverted)
					{
						menu->ProcessEvent(loadConfig, none, nullptr);
						reverted = true;
					}
					if (continueGame)
						menu->ProcessEvent(continueGame, none, nullptr);
				}
				// v12: no Close. The game never closes this movie: it is made
				// once (AliceGameInfo.inGameMenu) and only hidden on resume.
				// Close ran OnClose, which sets APC = none, and that menu never
				// opened again: Escape paused the world with nothing on screen
				// and the client could not pause any more (19:39:47 report).
				(void)close;
			});
			return std::string(bink ? "memory video stopped, " : "")
				+ (reverted ? "unapplied settings reverted, " : "")
				+ "continueGame on " + std::to_string(menus) + " menu(s)";
		}

		// v13 (24.10 20:44 report: resumed by the other player while in the
		// settings, the menu stayed on screen with its "apply?" box, the
		// game ran underneath and a click re-paused it). AliceGame.u:
		//   PostBeginPlay:  inGameMenu.Start(); inGameMenu.SetFocus(false)
		//   ShowJournalMenu: SetFocus(true,true); apc = self; openMenu(); SetPause(true)
		//   ContinueToGame: SetPause(false); apc = none; SetFocus(false,false)
		// - ContinueToGame hides nothing: the Flash plays its own close and
		// cannot from the settings page. So the menu is put back exactly as
		// the level starts it: resumed (continueGame), closed and unloaded,
		// started again and unfocused. Fresh and hidden, ready for the next
		// Escape; settings changed but not applied simply vanish with it.
		// (v11 closed it without the restart - the menu was dead after.)
		std::string RestartMenusFresh()
		{
			static UFunction* leaveControl = FindFunctionSafe(
				"Function AliceGame.AliceGfxMovie_inGameMenu.leaveControl");
			static UFunction* continueGame = FindFunctionSafe(
				"Function AliceGame.AliceGfxMovie_inGameMenu.continueGame");
			static UFunction* close = FindFunctionSafe(
				"Function GFxUI.GFxMovie.Close");
			static UFunction* start = FindFunctionSafe(
				"Function AliceGame.AliceGFXMovie.Start");
			static UFunction* setFocus = FindFunctionSafe(
				"Function GFxUI.GFxMovie.SetFocus");
			if (!close || !start || !setFocus)
				return "restart functions missing";
			const bool bink = StopMemoryVideo();
			std::vector<UAliceGfxMovie_inGameMenu*> menus;
			ForEachOpenInGameMenu([&](UAliceGfxMovie_inGameMenu* menu)
			{
				menus.push_back(menu);
			});
			int restarted = 0;
			for (UAliceGfxMovie_inGameMenu* menu : menus)
			{
				std::uint8_t none[16]{};
				g_menuRestarting = true;
				if (menu->APC)
				{
					if (leaveControl)
						menu->ProcessEvent(leaveControl, none, nullptr);
					if (continueGame)
						menu->ProcessEvent(continueGame, none, nullptr);
				}
				UGFxMovie_execClose_Params closeParameters{};
				closeParameters.Unload = 1u;
				menu->ProcessEvent(close, &closeParameters, nullptr);
				UAliceGFXMovie_execStart_Params startParameters{};
				startParameters.StartPaused = 0;
				menu->ProcessEvent(start, &startParameters, nullptr);
				UGFxMovie_execSetFocus_Params focusParameters{};
				focusParameters.captureInput = 0;
				focusParameters.Focus = 0;
				menu->ProcessEvent(setFocus, &focusParameters, nullptr);
				g_menuRestarting = false;
				++restarted;
			}
			g_inGameMenuOpenSignal = false;
			return std::string(bink ? "memory video stopped, " : "")
				+ "pause menu restarted fresh (" + std::to_string(restarted)
				+ " menu(s): continueGame, Close, Start, SetFocus off)";
		}

		// A memory (bink) opened from the pause menu: AliceGFXMovie.StopMemory
		// is AlicePlayerController.StopBinkFile().
		bool StopMemoryVideo()
		{
			AAlicePlayerController* const controller = g_State.AlicePlayerController;
			static UFunction* stop = FindFunctionSafe(
				"Function AliceGame.AlicePlayerController.StopBinkFile");
			if (!controller || !stop)
				return false;
			std::uint8_t parameters[16]{};
			controller->ProcessEvent(stop, parameters, nullptr);
			return true;
		}

		// Last resort before the world is unpaused by force: the menu's own
		// ActionScript close (openMenu has "_root.openMenu"; the closing
		// counterpart is tried by name - a missing one does nothing).
		int AskMenusToClose()
		{
			static UFunction* asVoid = FindFunctionSafe(
				"Function GFxUI.GFxMovie.ActionScriptVoid");
			if (!asVoid)
				return -1;
			int count = 0;
			ForEachOpenInGameMenu([&](UAliceGfxMovie_inGameMenu* menu)
			{
				struct { FString Path; } parameters;
				parameters.Path = FString(L"_root.closeMenu");
				menu->ProcessEvent(asVoid, &parameters, nullptr);
				++count;
			});
			return count;
		}

		// AliceGfxMovie_inGameMenu.uc: gotoPage(n) is ActionScript
		// "_root.gotoPage"; the controls page disables the player's input
		// (SetGFXMovie: PlayerInput.EnableInputCommands(false)) until
		// leaveControl() - leaving the menu from there by force must call it,
		// or the resumed player could not move.
		int MenusToMainPage()
		{
			static UFunction* gotoPage = FindFunctionSafe(
				"Function AliceGame.AliceGfxMovie_inGameMenu.gotoPage");
			static UFunction* leaveControl = FindFunctionSafe(
				"Function AliceGame.AliceGfxMovie_inGameMenu.leaveControl");
			int count = 0;
			if (!gotoPage)
				return -1;
			ForEachOpenInGameMenu([&](UAliceGfxMovie_inGameMenu* menu)
			{
				if (leaveControl && menu->APC)
				{
					std::uint8_t none[8]{};
					menu->ProcessEvent(leaveControl, none, nullptr);
				}
				UAliceGfxMovie_inGameMenu_execgotoPage_Params parameters{};
				parameters.pageNum = 0;
				menu->ProcessEvent(gotoPage, &parameters, nullptr);
				++count;
			});
			return count;
		}

		void PostEscapeToGame()
		{
			PostMessageW(AchievementOverlay::g_hWnd, WM_KEYDOWN, VK_ESCAPE, 0x00010001);
			PostMessageW(AchievementOverlay::g_hWnd, WM_KEYUP, VK_ESCAPE, 0xC0010001);
		}

		// v6 (01:01:08-01:01:56: a quick series of pauses broke it). v5 answered
		// every message at once with one Escape. During the menu's open/close
		// animation an Escape lands in the wrong place (01:01:34.904 "pause
		// menu opened here" closed it instead, 01:01:40/41 opened nothing),
		// so one game ended paused, the other running, and the worlds (a
		// moving platform) drifted apart.
		// Now the peer's latest wish is a TARGET, reached step by step:
		//  - one action at a time, never while this menu is still opening or
		//    closing (500 ms after its last change), 700 ms between actions;
		//  - pause: Escape, checked; one retry;
		//  - resume: Escape, then continueGame on the menu, then the world
		//    unpaused by force;
		//  - a newer wish replaces an older one, so a burst ends in the state
		//    of its last press on both games.
		// And a watchdog: a world paused with no pause menu and no board on
		// screen for 1.5 s (time stopped after a resume) is unpaused.
		Clock::time_point g_pauseResumeCheckAt{}; // (v4, unused)
		Clock::time_point g_pauseForceCheckAt{};  // (v4, unused)
		int g_pauseTarget = -1;                    // -1 none, 0 run, 1 paused
		int g_pauseTargetSteps = 0;
		Clock::time_point g_pauseTargetSince{};
		Clock::time_point g_pauseNextStep{};
		Clock::time_point g_pauseStrayPauseSince{};

		bool PauseCinematicHere()
		{
			const AAlicePlayerController* controller =
				g_State.AlicePlayerController;
			return !controller || controller->bCinematicMode
				|| controller->bCancelMatineeHintExisting
				|| g_waitingCutsceneAction;
		}

		void SendPauseState(bool paused)
		{
			SharedWorldEventPayload event{};
			event.kind = kEventPause;
			event.originActorId = g_config.role == Role::Host ? 1u : 2u;
			event.entityKey = 0x50415553u; // "PAUS"
			event.flags = paused ? 1u : 0u;
			QueueSharedWorldEvent(event);
			Log(std::string("SHAREDPAUSE TX ") + (paused ? "pause." : "resume."));
		}

		void TickSharedPause()
		{
			static std::string pauseWorld;
			if (pauseWorld != CurrentWorldTag())
			{
				// A new world starts unpaused; a menu signal from the old one
				// (closed by the level change) must not carry over.
				pauseWorld = CurrentWorldTag();
				g_pauseHardPaused = false;
				g_inGameMenuOpenSignal = false;
				g_pauseLastOpen = false;
				g_pauseExpect = -1;
				g_pauseTarget = -1;
				g_pauseStrayPauseSince = {};
			}
			if (!SharedPauseAvailable() || LeavingWorld())
				return;
			const auto now = Clock::now();
			if (now < g_nextPausePoll)
				return;
			g_nextPausePoll = now + std::chrono::milliseconds(50);
			const bool paused = g_inGameMenuOpenSignal;
			g_pauseMenuEventOpen.store(paused, std::memory_order_release);
			g_pauseMenuFallbackOpen = false;
			if (paused != g_pauseLastOpen)
			{
				g_pauseLastOpen = paused;
				g_inGameMenuSignalChangedAt = now;
				if (!paused)
				{
					// Back from the pause: both Alices' hair once more.
					g_localHairResetAt = now + std::chrono::milliseconds(300);
					g_localHairResetReason = "pause";
					g_proxyHairRestoreReason = "pause";
					g_proxyHairSettleResetAt = now + std::chrono::milliseconds(700);
				}
				const bool ours = g_pauseExpect == (paused ? 1 : 0)
					&& now < g_pauseGuardUntil;
				if (ours)
					g_pauseExpect = -1;
				else
				{
					// The player here changed it: that is the newest state,
					// the other game is asked to follow it.
					g_pauseExpect = -1;
					g_pauseTarget = paused ? 1 : 0;
					g_pauseTargetSteps = 0;
					g_pauseTargetSince = now;
					g_pauseActivityUntil = now + std::chrono::seconds(20);
					SendPauseState(paused);
				}
			}

			// v8: the peer's last known state is kept (not dropped once
			// reached) and this game is reconciled to it continuously. v7
			// dropped it when the states matched for a moment: 21:31:39.146
			// an Escape to resume was already posted, the next "pause"
			// arrived at .217 and counted as reached because the Escape had
			// not landed yet; the Escape then resumed this game while the
			// other stayed paused. Now an action in flight is waited for
			// (its menu change, or 600 ms), then the states are compared
			// again, until they are equal.
			const bool actionInFlight = g_pauseExpect >= 0 && now < g_pauseGuardUntil;
			if (g_pauseTarget >= 0)
			{
				const bool want = g_pauseTarget == 1;
				// pausehold1: resumed while the world was held without a menu.
				if (!want && g_pauseHardPaused)
				{
					g_pauseHardPaused = false;
					ForceUnpauseWorld("the other player resumed (held pause)");
				}
				if (paused == want && !actionInFlight)
				{
					if (g_pauseTargetSteps > 0)
					{
						Log(std::string("SHAREDPAUSE in step: both ")
							+ (want ? "paused" : "running") + " after "
							+ std::to_string(g_pauseTargetSteps) + " step(s).");
					}
					g_pauseTargetSteps = 0;
					g_pauseTargetSince = now;
				}
				else if (want && paused != want && !actionInFlight && !g_pauseHardPaused
					&& now - g_pauseTargetSince > std::chrono::seconds(5))
				{
					// Cannot get there: make the OTHER game follow this one
					// instead, so the two never stay apart.
					Log(std::string("SHAREDPAUSE could not ")
						+ (want ? "pause" : "resume") + " here; asking the other "
						"game to follow this one (" + (paused ? "paused" : "running")
						+ ").");
					g_pauseTarget = paused ? 1 : 0;
					g_pauseTargetSteps = 0;
					g_pauseTargetSince = now;
					SendPauseState(paused);
				}
				else if (paused != want && !actionInFlight
					&& now >= g_pauseNextStep
					&& now - g_inGameMenuSignalChangedAt
						>= std::chrono::milliseconds(200))
				{
					g_pauseNextStep = now + std::chrono::milliseconds(350);
					g_pauseExpect = want ? 1 : 0;
					g_pauseGuardUntil = now + std::chrono::milliseconds(600);
					const int step = g_pauseTargetSteps++;
					std::string action;
					if (want)
					{
						// shootpause2 (12.11 01:32:28: "paused, but no menu" - the
						// ship game counts as a cutscene / board here): in the
						// ride the menu is opened directly (ShowJournalMenu
						// handles the ship's own movie itself)
						AAlicePlayerController* const ridePc = g_State.AlicePlayerController;
						const bool inRide = g_soloMinigameActive && ContainsCaseInsensitive(g_soloMinigameLevel, "Ride")
							&& ridePc && IsUsableObjectFast(ridePc) && ridePc->bInRailRideMode;
						static UFunction* rideJournal = nullptr;
						if (inRide && !rideJournal)
							rideJournal = FindFunctionSafe("Function AliceGame.AlicePlayerController.ShowJournalMenu");
						if (inRide && rideJournal && step <= 2)
						{
							// shootpause3 (12.11 03:15: "paused, no menu" on the other
							// game): ShowJournalMenu shrinks the controller's FocusedMovie
							// to 1x1 in the ride - there it was not the ship's own
							// movie; the ship's movie is put there, the menu kept full size
							if (UObject* const shipMovie = ShooterMovieObject())
								ridePc->FocusedMovie = reinterpret_cast<UAliceGFXMovie*>(shipMovie);
							std::uint8_t none[16]{};
							ridePc->ProcessEvent(rideJournal, none, nullptr);
							static UFunction* viewport = FindFunctionSafe("Function GFxUI.GFxMovie.SetViewport");
							RECT client{};
							if (viewport && AchievementOverlay::g_hWnd && GetClientRect(AchievementOverlay::g_hWnd, &client)
								&& client.right > 1 && client.bottom > 1)
							{
								ForEachOpenInGameMenu([&](UAliceGfxMovie_inGameMenu* menu)
								{
									UGFxMovie_execSetViewport_Params size{};
									size.X = 0;
									size.Y = 0;
									size.Width = client.right;
									size.Height = client.bottom;
									menu->ProcessEvent(viewport, &size, nullptr);
								});
							}
							action = std::string("ship game: ShowJournalMenu called (paused now=")
								+ (g_inGameMenuOpenSignal || WorldPaused() ? "yes" : "no") + ")";
						}
						else if (!inRide && (PauseCinematicHere() || BoardInputBlockedHere()
							|| !AchievementOverlay::g_hWnd))
						{
							action = "not now (cutscene/board), waiting";
							g_pauseExpect = -1;
						}
						else if (g_pauseHardPaused)
						{
							action = "world held";
							g_pauseExpect = -1;
						}
						else if (step >= 2)
						{
							// pausehold1 (31.10 23:30, London after a cutscene):
							// two Escapes opened no menu here and the client
							// played on while the host was paused. The world is
							// then simply held (no menu) until the other player
							// resumes.
							AAlicePlayerController* const holder = g_State.AlicePlayerController;
							if (holder && holder->PlayerReplicationInfo && g_currentWorld
								&& IsUsableObjectFast(g_currentWorld))
							{
								g_currentWorld->Pauser = holder->PlayerReplicationInfo;
								g_pauseHardPaused = true;
								action = "no menu opened: world held paused";
							}
							else
								action = "no menu opened, cannot hold";
							g_pauseExpect = -1;
						}
						else
						{
							// pausefocus1 (04.11 17:11, client after a manual
							// join from the main menu: two Escapes opened no
							// menu until a restart). Escape is ShowJournalMenu,
							// which returns at once while the controller's
							// FocusedMovie is some other movie - here one left
							// from the menu/board, no longer open. Such a stale
							// focus is dropped first.
							AAlicePlayerController* const pc = g_State.AlicePlayerController;
							std::string dropped;
							if (pc && IsUsableObjectFast(pc) && pc->FocusedMovie)
							{
								UAliceGFXMovie* const focused = pc->FocusedMovie;
								const bool usable = IsUsableObjectFast(focused);
								const bool isMenu = usable
									&& focused->IsA(UAliceGfxMovie_inGameMenu::StaticClass());
								if (!isMenu && (!usable || !focused->bIsOpen || step >= 1))
								{
									dropped = ", stale focus " + (usable ? ObjectName(focused)
										: std::string("<freed>")) + " (open="
										+ (usable && focused->bIsOpen ? "yes" : "no") + ") dropped";
									pc->FocusedMovie = nullptr;
								}
								else if (!isMenu)
									dropped = ", focus on " + ObjectName(focused) + " (open) kept";
							}
							// pausefocus2 (04.11 17:36:50 and 17:37:39: no stale
							// focus, two Escapes still opened nothing - both
							// right after a cutscene on the client). The second
							// step calls the game's own ShowJournalMenu (what
							// Escape is bound to) directly, and says what it
							// found when it opened nothing.
							static UFunction* journal = FindFunctionSafe(
								"Function AliceGame.AlicePlayerController.ShowJournalMenu");
							if (step <= 1 && journal && pc && IsUsableObjectFast(pc)) // pausefast1: at once
							{
								std::uint8_t none[16]{};
								pc->ProcessEvent(journal, none, nullptr);
								const bool opened = g_inGameMenuOpenSignal || WorldPaused();
								action = std::string("ShowJournalMenu called directly") + dropped
									+ " (focus=" + ObjectName(pc->FocusedMovie)
									+ ", cinematic=" + std::to_string(pc->bCinematicMode)
									+ ", cancelHint=" + std::to_string(pc->bCancelMatineeHintExisting)
									+ ", paused now=" + (opened ? "yes" : "no") + ")";
							}
							else
							{
								PostEscapeToGame();
								action = "Escape" + dropped;
							}
						}
					}
					else if (step == 0)
					{
						// The other player resumed: this game resumes too and
						// its pause menu goes away completely, from any page.
						// Walking the menu back with Escape (v10) opened the
						// "apply settings?" box when a setting had been
						// changed, and the repeated Escapes made it flicker
						// until the player answered it (24.10 18:13 report).
						// Now nothing is navigated: a memory video is stopped,
						// the controls page gives the input back, settings
						// changed but not applied are reverted to the saved
						// ones (interface_LoadConfigData, the menu's own
						// reload), the game resumes (continueGame ->
						// ContinueToGame) and the menu movie is closed the way
						// the game closes it (Close, unload - it is started
						// fresh on every Escape).
						// v12: the menu is only ever left the game's own ways.
						// Settings changed: revert them and continueGame (the
						// call the menu's Resume makes) - no Escape, so no
						// "apply settings?" box. Otherwise: main page, then
						// Escape, as the player would.
						// v13: from any page (settings, the "apply?" box,
						// memories, controls) the menu is restarted fresh -
						// see RestartMenusFresh. The old ways stay as the
						// fallback steps below.
						action = RestartMenusFresh();
						g_pauseSettingsTouched = false;
					}
					else if (step == 3)
					{
						action = ResumeMenusDirectly(false);
					}
					else if (step < 5 && AchievementOverlay::g_hWnd)
					{
						// Fallback: the old way, main page + Escape.
						const int pages = MenusToMainPage();
						PostEscapeToGame();
						action = "main page on " + std::to_string(pages)
							+ " menu(s) + Escape";
						g_pauseNextStep = now + std::chrono::milliseconds(400);
					}
					else
					{
						g_inGameMenuOpenSignal = false;
						ForceUnpauseWorld("resume from the other player");
						g_pauseExpect = -1;
						action = "world unpaused";
					}
					Log(std::string("SHAREDPAUSE step ") + std::to_string(step + 1)
						+ " to " + (want ? "pause" : "resume") + ": " + action + '.');
				}
			}

			// Watchdog: time stopped with nothing on screen that pauses it.
			const AAlicePlayerController* controller =
				g_State.AlicePlayerController;
			const bool uiPause = paused || g_pauseTarget == 1
				|| (controller && controller->FocusedMovie)
				|| PauseCinematicHere();
			if (WorldPaused() && !uiPause && !g_readyCheckPausedWorld && !g_pauseHardPaused
				&& now < g_pauseActivityUntil)
			{
				if (g_pauseStrayPauseSince == Clock::time_point{})
					g_pauseStrayPauseSince = now;
				else if (now - g_pauseStrayPauseSince
					> std::chrono::milliseconds(1500))
				{
					ForceUnpauseWorld("no pause menu or board on screen");
					g_pauseStrayPauseSince = {};
				}
			}
			else
				g_pauseStrayPauseSince = {};
		}

		void OnRemotePause(const SharedWorldEventPayload& event)
		{
			if (!SharedPauseAvailable() || LeavingWorld())
				return;
			const auto now = Clock::now();
			const int want = (event.flags & 1u) != 0 ? 1 : 0;
			const bool paused = g_inGameMenuOpenSignal;
			std::string result;
			if ((want == 1) == paused && g_pauseTarget == want
				&& !(g_pauseExpect >= 0 && now < g_pauseGuardUntil))
				result = paused ? "already paused here" : "already running here";
			else
			{
				g_pauseTargetSteps = 0;
				g_pauseTargetSince = now;
				g_pauseTarget = want;
				g_pauseActivityUntil = now + std::chrono::seconds(20);
				// Stop this world in the same frame; the menu opens right
				// after (its own SetPause keeps it stopped).
				AAlicePlayerController* const pc = g_State.AlicePlayerController;
				if (want == 1 && !paused && pc && pc->PlayerReplicationInfo
					&& g_currentWorld && IsUsableObjectFast(g_currentWorld)
					&& !PauseCinematicHere() && !BoardInputBlockedHere()
					&& !g_currentWorld->Pauser)
				{
					g_currentWorld->Pauser = pc->PlayerReplicationInfo;
				}
				// Act on the very next frame, not on the next poll.
				g_nextPausePoll = {};
				g_pauseNextStep = {};
				result = "target set";
			}
			Log(std::string("SHAREDPAUSE RX ") + (want ? "pause" : "resume")
				+ ": " + result + '.');
		}

		// joinlatest1 / joinunpause1 (13.11 02:12, chapter 4: the client went
		// to the menu and came back by hand - the join loads the chapter's
		// start, the host was far along the map). On the host, when the other
		// player comes into this map: a paused game resumes at once, and 3 s
		// later the host's latest level checkpoint is sent (the client saves
		// it and both restart from their checkpoint, see SHAREDSEQ RX).
		void TickPeerArrival()
		{
			static std::string lastPeerMap;
			static Clock::time_point sendAt{};
			if (g_config.role != Role::Host || !g_connected || g_config.localMirror)
			{
				lastPeerMap.clear();
				sendAt = {};
				return;
			}
			const auto now = Clock::now();
			const std::string peerMap = g_remotePresentation.valid
				? std::string(g_remotePresentation.state.mapName) : std::string();
			if (peerMap != lastPeerMap)
			{
				const bool arrived = !peerMap.empty() && !g_currentMap.empty()
					&& _stricmp(peerMap.c_str(), g_currentMap.c_str()) == 0
					&& _stricmp(g_currentMap.c_str(), "AliceEntry") != 0
					&& !lastPeerMap.empty()
					&& _stricmp(lastPeerMap.c_str(), g_currentMap.c_str()) != 0;
				lastPeerMap = peerMap;
				if (arrived)
				{
					if (g_inGameMenuOpenSignal)
					{
						SharedWorldEventPayload resume{};
						resume.flags = 0u;
						Log("JOINUNPAUSE the other player came into this map: the paused game resumes (joinunpause1).");
						OnRemotePause(resume);
					}
					if (g_lastCheckpointEventKey != 0
						&& _stricmp(g_lastCheckpointEventMap.c_str(), g_currentMap.c_str()) == 0)
					{
						sendAt = now + std::chrono::seconds(3);
					}
				}
			}
			if (sendAt != Clock::time_point{} && now >= sendAt)
			{
				sendAt = {};
				if (!peerMap.empty() && _stricmp(peerMap.c_str(), g_currentMap.c_str()) == 0
					&& g_lastCheckpointEventKey != 0)
				{
					SharedWorldEventPayload share{};
					share.kind = static_cast<SharedWorldEventKind>(27);
					share.entityKey = g_lastCheckpointEventKey;
					share.flags = 1u | 2u; // a checkpoint event, sent for a join
					share.originActorId = 1u;
					QueueSharedWorldEvent(share);
					Log("JOINLATEST TX the latest checkpoint " + g_lastCheckpointEventName
						+ " for the player who came in (joinlatest1).");
				}
			}
		}

		// ---- Shared hints (SHAREDHINT) -----------------------------------
		// Gameplay hints are Kismet SeqAct_ToggleUI (tutorial, inspect, POI,
		// enemy info). Only those in a shared touch chain reached both
		// screens; the rest (level start, volumes, counters, cinematics)
		// showed on one. When a ToggleUI starts playing here (bPlaying goes
		// up), the peer starts the same action (ForceActivateInput "On"),
		// unless it showed that hint itself a moment ago.
		constexpr SharedWorldEventKind kEventHint =
			static_cast<SharedWorldEventKind>(22);
		struct HintWatch
		{
			std::uint64_t key = 0; // computed only while the action runs
			bool lastPlaying = false;
			float lastPlayedTime = 0.0f;
			Clock::time_point localShownAt{};
			Clock::time_point remoteAppliedAt{};
			Clock::time_point remoteClosedAt{};
		};
		// Re-collected from GObjects on every pass: a streaming level that
		// unloads frees its Kismet, and a pointer kept from an older pass is
		// garbage (host crash 19:36:18: GetFullName of a ToggleUI whose outer
		// chain was already gone, inside SequenceActionStableKey). Nothing
		// from GObjects is touched unless the object and its whole outer
		// chain are still valid, and the key is only built for an action
		// that is executing right now.
		std::unordered_map<USeqAct_ToggleUI*, HintWatch> g_hintWatch;
		// hinthide4: ToggleUI hints this client started from the host's
		// touch replay. These latent hints finish at once (bPlaying never
		// shows), while their text stays until the player's own action.
		std::string g_hintWatchMap;
		Clock::time_point g_nextHintPass{};

		bool HintActionUsable(UObject* object)
		{
			static UClass* const toggleClass = USeqAct_ToggleUI::StaticClass();
			if (!object || !object->IsA(toggleClass) || object->IsDefaultObject()
				|| !IsUsableObjectFast(object)) // perf3: the class test first
			{
				return false;
			}
			return ObjectChainUsable(object);
		}

		bool HintTypeShared(const USeqAct_ToggleUI* action)
		{
			switch (action->UIType)
			{
			case EKismetToggleUIType::EUITYPE_Tutorial:
			case EKismetToggleUIType::EUITYPE_Inspect:
			case EKismetToggleUIType::EUITYPE_Poi:
			case EKismetToggleUIType::EUITYPE_EnemyInfo:
				return true;
			default:
				return false; // chapter title, others: each game has its own
			}
		}

		// Hints the host has already had on this map (25.10 request: a hint
		// the host has seen and dismissed is not shown again to a client
		// who joins later). The host keeps the keys per map and sends them
		// (kind 40) whenever the client is (re)connected and when a new one
		// ends; the client closes such a hint as soon as its own level
		// starts it, and sends nothing for it.
		constexpr SharedWorldEventKind kEventHintDone =
			static_cast<SharedWorldEventKind>(40);
		std::unordered_set<std::uint64_t> g_hostHintsDone;      // host: this map
		std::string g_hostHintsDoneMap;
		std::unordered_set<std::uint64_t> g_peerHintsDone;      // client: from the host
		std::string g_peerHintsDoneMap;
		std::unordered_set<USeqAct_ToggleUI*> g_hintsClosedAsDone;
		bool g_hintsDoneSentForPeer = false;

		void SendHostHintDone(std::uint64_t key)
		{
			SharedWorldEventPayload event{};
			event.kind = kEventHintDone;
			event.entityKey = key;
			event.originActorId = 1u;
			QueueSharedWorldEvent(event);
		}

		void OnRemoteHintDone(const SharedWorldEventPayload& event)
		{
			if (g_config.role != Role::Client || !event.entityKey)
				return;
			if (g_peerHintsDoneMap != g_currentMap)
			{
				g_peerHintsDoneMap = g_currentMap;
				g_peerHintsDone.clear();
			}
			if (g_peerHintsDone.insert(event.entityKey).second)
			{
				static int logsLeft = 60;
				if (logsLeft > 0)
				{
					--logsLeft;
					Log("SHAREDHINT host already had key="
						+ SharedWorldKeyText(event.entityKey) + " on this map.");
				}
			}
		}

		// hintpause1 (31.10 15:47): a hint closed here by the mod (the other
		// player dismissed it, or the host had it already) goes through the
		// action's Off input - not the button the player presses. Sometimes
		// the game stayed paused with nothing on screen until a pause-menu
		// round trip. 0.6 s and 2 s after such a close, a world still paused
		// with no hint showing, no menu and no cutscene is unpaused.
		std::vector<Clock::time_point> g_hintForcedCloseChecks;

		void NoteHintForcedClose()
		{
			const auto now = Clock::now();
			g_hintForcedCloseChecks.push_back(now + std::chrono::milliseconds(600));
			g_hintForcedCloseChecks.push_back(now + std::chrono::seconds(2));
		}

		void CheckPauseAfterHintClose(Clock::time_point now)
		{
			if (g_hintForcedCloseChecks.empty())
				return;
			bool due = false;
			for (auto it = g_hintForcedCloseChecks.begin(); it != g_hintForcedCloseChecks.end();)
			{
				if (now >= *it)
				{
					due = true;
					it = g_hintForcedCloseChecks.erase(it);
				}
				else
					++it;
			}
			if (!due)
				return;
			bool hintShowing = false;
			for (const auto& [action, watch] : g_hintWatch)
				if (watch.lastPlaying && action && IsUsableObjectFast(action) && action->bPlaying)
					hintShowing = true;
			AAlicePlayerController* const pc = g_State.AlicePlayerController;
			const bool cinematic = pc && IsUsableObjectFast(pc) && pc->bCinematicMode;
			Log(std::string("SHAREDHINT after a forced close: paused=") + (WorldPaused() ? "yes" : "no")
				+ ", hintShowing=" + (hintShowing ? "yes" : "no")
				+ ", menu=" + (g_inGameMenuOpenSignal ? "yes" : "no")
				+ ", cinematic=" + (cinematic ? "yes" : "no")
				+ ", ignoreMove=" + std::to_string(pc && IsUsableObjectFast(pc) ? pc->bIgnoreMoveInput : 0)
				+ ", ignoreLook=" + std::to_string(pc && IsUsableObjectFast(pc) ? pc->bIgnoreLookInput : 0) + '.');
			if (WorldPaused() && !hintShowing && !g_inGameMenuOpenSignal && !cinematic)
				ForceUnpauseWorld("a hint closed by the mod left it paused");
		}

		void TickSharedHints()
		{
			CheckPauseAfterHintClose(Clock::now());
			// The host also watches while alone, so a client who joins later
			// still learns which hints it has had (nothing is sent then).
			if (!g_config.enabled || !g_config.sharedHints
				|| g_config.localMirror
				|| (!g_connected && g_config.role != Role::Host)
				|| g_soloMinigameActive
				|| WorldTransitionActive() || g_currentMap.empty())
			{
				g_hintsDoneSentForPeer = false;
				return;
			}
			if (!g_connected)
				g_hintsDoneSentForPeer = false;
			const auto now = Clock::now();
			if (g_hintWatchMap != CurrentWorldTag())
			{
				g_hintWatch.clear();
				g_hintsClosedAsDone.clear();
				g_hintWatchMap = CurrentWorldTag();
			}
			if (g_config.role == Role::Host)
			{
				if (g_hostHintsDoneMap != g_currentMap)
				{
					g_hostHintsDoneMap = g_currentMap;
					g_hostHintsDone.clear();
					g_hintsDoneSentForPeer = false;
				}
				// The whole list once per (re)connection of a peer on this map.
				const bool peerHere = g_connected && g_remotePresentation.valid
					&& _stricmp(g_remotePresentation.state.mapName, g_currentMap.c_str()) == 0;
				if (!peerHere)
					g_hintsDoneSentForPeer = false;
				else if (!g_hintsDoneSentForPeer)
				{
					g_hintsDoneSentForPeer = true;
					for (const std::uint64_t key : g_hostHintsDone)
						SendHostHintDone(key);
					if (!g_hostHintsDone.empty())
						Log("SHAREDHINT host sent " + std::to_string(g_hostHintsDone.size())
							+ " hint(s) already had on " + g_currentMap + '.');
				}
			}
			if (now < g_nextHintPass)
				return;
			g_nextHintPass = now + std::chrono::milliseconds(1000); // perf4: was 250
			std::unordered_map<USeqAct_ToggleUI*, HintWatch> seen;
			TArray<UObject*>* objects = UObject::GObjObjects();
			for (int32_t index = 0; objects && index < objects->size(); ++index)
			{
				UObject* object = objects->at(index);
				if (!HintActionUsable(object))
					continue;
				auto* action = reinterpret_cast<USeqAct_ToggleUI*>(object);
				const auto previous = g_hintWatch.find(action);
				HintWatch watch = previous != g_hintWatch.end()
					? previous->second : HintWatch{};
				bool playing = action->bPlaying != 0;
				if (previous == g_hintWatch.end())
					watch.lastPlaying = playing; // first sight: no edge
				if (playing && !watch.lastPlaying)
				{
					const bool ourReplay = watch.remoteAppliedAt != Clock::time_point{}
						&& now - watch.remoteAppliedAt < std::chrono::seconds(3);
					if (!ourReplay && g_connected)
					{
						watch.localShownAt = now;
						if (HintTypeShared(action))
						{
							if (watch.key == 0)
								watch.key = SequenceActionStableKey(action);
							if (watch.key != 0)
							{
								SharedWorldEventPayload event{};
								event.kind = kEventHint;
								event.entityKey = watch.key;
								event.originActorId =
									g_config.role == Role::Host ? 1u : 2u;
								event.flags =
									static_cast<std::uint8_t>(action->UIType);
								QueueSharedWorldEvent(event);
								Log("SHAREDHINT TX key="
									+ SharedWorldKeyText(watch.key)
									+ ", action=" + ObjectName(action)
									+ ", type=" + std::to_string(
										static_cast<int>(action->UIType))
									+ '.');
							}
						}
					}
				}
				// Client: a hint the host already had on this map is closed
				// the moment this level starts it (nothing is sent for it).
				if (g_config.role == Role::Client && playing && HintTypeShared(action)
					&& !g_peerHintsDone.empty() && g_peerHintsDoneMap == g_currentMap
					&& !g_hintsClosedAsDone.count(action))
				{
					if (watch.key == 0)
						watch.key = SequenceActionStableKey(action);
					if (watch.key != 0 && g_peerHintsDone.count(watch.key)
						&& action->InputLinks.size() > 1
						&& NativeForceActivateSequenceInput(action, 1))
					{
						g_hintsClosedAsDone.insert(action);
						watch.remoteClosedAt = now;
						NoteHintForcedClose();
						Log("SHAREDHINT closed key=" + SharedWorldKeyText(watch.key)
							+ " (" + ObjectName(action) + "): the host already had it.");
						playing = false;
					}
				}
				if (!playing && watch.lastPlaying && g_config.role == Role::Host
					&& HintTypeShared(action))
				{
					if (watch.key == 0)
						watch.key = SequenceActionStableKey(action);
					if (watch.key != 0 && g_hostHintsDone.insert(watch.key).second
						&& g_hintsDoneSentForPeer)
					{
						SendHostHintDone(watch.key);
					}
				}
				if (!playing && watch.lastPlaying)
				{
					// Closed here before its time (the player pressed the
					// button on a tutorial poster): close it on the other
					// screen too. A hint that simply ran out is not sent.
					const bool closedByUs = watch.remoteClosedAt != Clock::time_point{}
						&& now - watch.remoteClosedAt < std::chrono::seconds(2);
					const bool early = action->Duration <= 0.0f
						|| watch.lastPlayedTime < action->Duration - 0.3f;
					// hinthide3: the "press T" hint is not one of the shared
					// types; the host closing it early closes it here too.
					if (!closedByUs && early && g_connected
						&& (HintTypeShared(action)
							|| action->UIType == EKismetToggleUIType::EUITYPE_Others))
					{
						if (watch.key == 0)
							watch.key = SequenceActionStableKey(action);
						if (watch.key != 0)
						{
							SharedWorldEventPayload event{};
							event.kind = kEventHint;
							event.entityKey = watch.key;
							event.originActorId =
								g_config.role == Role::Host ? 1u : 2u;
							event.flags = 0x80u
								| static_cast<std::uint8_t>(action->UIType);
							QueueSharedWorldEvent(event);
							Log("SHAREDHINT TX close key="
								+ SharedWorldKeyText(watch.key)
								+ ", action=" + ObjectName(action) + '.');
						}
					}
				}
				watch.lastPlaying = playing;
				watch.lastPlayedTime = action->PlayedTime;
				seen.emplace(action, watch);
			}
			g_hintWatch.swap(seen);
		}

		// hinthide3 (04.11 16:56, report: the host pressed T, his hint went
		// away, the client's stayed): the client never presses T itself, so
		// its own copy of that Kismet hint never got its Off input. When the
		// host goes into first person in the real world, every POI / other /
		// tutorial ToggleUI still playing here is closed through Off.
		void CloseHintsForHostFirstPerson()
		{
			if (g_config.role != Role::Client)
				return;
			int closed = 0;
			const auto now = Clock::now();
			for (auto& [action, watch] : g_hintWatch)
			{
				if (!action || !HintActionUsable(action) || !action->bPlaying)
					continue;
				const auto type = action->UIType;
				if (type != EKismetToggleUIType::EUITYPE_Poi
					&& type != EKismetToggleUIType::EUITYPE_Others
					&& type != EKismetToggleUIType::EUITYPE_Tutorial)
				{
					continue;
				}
				if (action->InputLinks.size() > 1 && NativeForceActivateSequenceInput(action, 1))
				{
					watch.remoteClosedAt = now;
					++closed;
					Log("HINTHIDE closed " + ObjectName(action) + " (type "
						+ std::to_string(static_cast<int>(type))
						+ "): the host went into first person.");
				}
			}
			// hinthide4 (04.11 17:10:52, the client's log: "no Kismet hint
			// was playing here" - the "press T" hint is SeqAct_ToggleUI_1 of
			// Chapter1_L1_Doctor_S, started here by the host's touch replay;
			// it never reads as playing). Every hint started that way in the
			// last 3 minutes gets its Off input.
			for (auto it = g_recentToggleUiStarts.begin(); it != g_recentToggleUiStarts.end();)
			{
				USeqAct_ToggleUI* const action = it->first;
				const bool fresh = now - it->second < std::chrono::minutes(3);
				// hintcrash1 (04.11 20:31:02, client crash in HintActionUsable:
				// a hint remembered before a restart had been freed with its
				// streamed level). Only an action the last GObjects pass saw
				// is touched at all.
				if (fresh && action && g_hintWatch.count(action) && HintActionUsable(action) && action->InputLinks.size() > 1
					&& NativeForceActivateSequenceInput(action, 1))
				{
					++closed;
					Log("HINTHIDE closed " + ObjectName(action) + " (started by the host's touch,"
						" type " + std::to_string(static_cast<int>(action->UIType))
						+ "): the host went into first person.");
				}
				it = g_recentToggleUiStarts.erase(it);
			}
			if (closed > 0)
				NoteHintForcedClose();
			else
				Log("HINTHIDE the host went into first person; no Kismet hint was playing here.");
		}

		void OnRemoteHint(const SharedWorldEventPayload& event)
		{
			if (!g_config.sharedHints || WorldTransitionActive())
				return;
			const auto now = Clock::now();
			USeqAct_ToggleUI* action = nullptr;
			TArray<UObject*>* objects = UObject::GObjObjects();
			for (int32_t index = 0; objects && index < objects->size(); ++index)
			{
				UObject* object = objects->at(index);
				if (!HintActionUsable(object))
					continue;
				auto* candidate = reinterpret_cast<USeqAct_ToggleUI*>(object);
				auto found = g_hintWatch.find(candidate);
				std::uint64_t key = found != g_hintWatch.end()
					? found->second.key : 0;
				if (key == 0)
				{
					key = SequenceActionStableKey(candidate);
					if (found != g_hintWatch.end())
						found->second.key = key;
				}
				if (key == event.entityKey)
				{
					action = candidate;
					break;
				}
			}
			std::string result;
			if (!action)
				result = "not found here";
			else
			{
				HintWatch& watch = g_hintWatch[action];
				watch.key = event.entityKey;
				if ((event.flags & 0x80u) != 0)
				{
					if (!action->bPlaying)
						result = "close: not showing here";
					else if (action->InputLinks.size() > 1
						&& NativeForceActivateSequenceInput(action, 1))
					{
						watch.remoteClosedAt = now;
						NoteHintForcedClose();
						result = "closed (the other player dismissed it)";
					}
					else
						result = "close: Off input failed";
				}
				else if (action->bPlaying)
					result = "already showing here";
				else if (watch.localShownAt != Clock::time_point{}
					&& now - watch.localShownAt < std::chrono::seconds(30))
				{
					result = "shown here a moment ago";
				}
				else if (NativeForceActivateSequenceInput(action, 0))
				{
					watch.remoteAppliedAt = now;
					result = "shown";
				}
				else
					result = "ForceActivateInput failed";
			}
			Log("SHAREDHINT RX key=" + SharedWorldKeyText(event.entityKey)
				+ ", action=" + ObjectName(action) + ": " + result + '.');
		}

