		// 25.10 logs: Actor.Destroy through ProcessEvent returned false for
		// every actor the mod made (shot copies, the retired Alice, her
		// weapons), although their flags pass every refusal in the engine's
		// own UWorld::DestroyActor (dumped from both exes: bStatic/bNoDelete
		// 0x48 at +0x3C, Role at +0xA2 == Authority, network PC). The native
		// behind Actor.Destroy is, on both builds,
		//   mov ecx, [GWorld]; push 1; push 0; push esi; call DestroyActor
		// so read GWorld and DestroyActor out of those bytes and call it
		// directly (thiscall, 3 args); ProcessEvent stays as the fallback.
		bool IsExecutableAddress(uintptr_t address);
		using DestroyActorFn = int(__fastcall*)(void* world, void* edx,
			AActor* actor, int netForce, int modifyLevel);
		bool ResolveDestroyActor(void**& gworldSlot, DestroyActorFn& destroyActor)
		{
			static bool resolved = false;
			static void** slot = nullptr;
			static DestroyActorFn target = nullptr;
			if (!resolved)
			{
				resolved = true;
				UFunction* const function = FindFunctionSafe(
					"Function Engine.Actor.Destroy");
				const auto* const code = function
					? reinterpret_cast<const std::uint8_t*>(function->Func.Dummy) : nullptr;
				if (code && IsReadableRange(code, 0x60))
				{
					for (int at = 0; at + 16 < 0x60; ++at)
					{
						if (code[at] == 0x8B && code[at + 1] == 0x0D
							&& code[at + 6] == 0x6A && code[at + 7] == 0x01
							&& code[at + 8] == 0x6A && code[at + 9] == 0x00
							&& code[at + 10] == 0x56 && code[at + 11] == 0xE8)
						{
							std::uint32_t world = 0;
							std::int32_t rel = 0;
							std::memcpy(&world, code + at + 2, 4);
							std::memcpy(&rel, code + at + 12, 4);
							const uintptr_t call = reinterpret_cast<uintptr_t>(code + at + 16) + rel;
							if (IsReadableRange(reinterpret_cast<void*>(
								static_cast<uintptr_t>(world)), 4) && IsExecutableAddress(call))
							{
								slot = reinterpret_cast<void**>(static_cast<uintptr_t>(world));
								target = reinterpret_cast<DestroyActorFn>(call);
							}
							break;
						}
					}
				}
				const uintptr_t base = reinterpret_cast<uintptr_t>(GetModuleHandleW(nullptr));
				std::ostringstream text;
				text << std::hex << "DESTROYACTOR native resolved: GWorld slot=+0x"
					<< (slot ? reinterpret_cast<uintptr_t>(slot) - base : 0)
					<< ", DestroyActor=+0x"
					<< (target ? reinterpret_cast<uintptr_t>(target) - base : 0)
					<< (target ? "." : " - NOT found, ProcessEvent only.");
				Log(text.str());
			}
			gworldSlot = slot;
			destroyActor = target;
			return slot && target;
		}

		// Used for the shot copies only for now (the retired Alice and her
		// weapons keep the old, refused path until this is proven).
		bool NativeDestroyActorDirect(AActor* actor)
		{
			if (!actor || !IsLiveUObject(actor))
				return false;
			if (actor->bDeleteMe)
				return true;
			void** gworldSlot = nullptr;
			DestroyActorFn destroyActor = nullptr;
			if (ResolveDestroyActor(gworldSlot, destroyActor) && *gworldSlot)
			{
				const int result = destroyActor(*gworldSlot, nullptr, actor, 0, 1);
				static int logsLeft = 6;
				if (logsLeft > 0)
				{
					--logsLeft;
					Log("DESTROYACTOR direct " + ObjectName(actor) + ": result="
						+ std::to_string(result) + ", deleteMe="
						+ std::to_string(actor->bDeleteMe ? 1 : 0) + '.');
				}
				if (result || actor->bDeleteMe)
					return true;
			}
			return NativeDestroyActor(actor);
		}

