		bool NativeSetComponentHidden(UPrimitiveComponent* component,
			bool hidden)
		{
			static UFunction* function = nullptr;
			if (!function)
				function = FindFunctionSafe(
					"Function Engine.PrimitiveComponent.SetHidden");
			// PrimitiveComponent.SetHidden only re-registers the primitive
			// when the flag CHANGES. Most callers write HiddenGame first, which
			// turned this into a no-op: the render state kept the old value
			// (25.10: the flower and the departed client's "statue" stayed
			// visible). For ordinary primitives the flag is put back first so
			// the engine sees the change. Cloth and hair are left as they were:
			// re-registering them with a live solver is what crashed (ears).
			if (component && !component->IsA(UClothComponent::StaticClass())
				&& !component->IsA(UHairComponent::StaticClass())
				&& static_cast<bool>(component->HiddenGame) == hidden)
			{
				component->HiddenGame = !hidden;
			}
			UPrimitiveComponent_execSetHidden_Params parameters{};
			parameters.NewHidden = hidden;
			return InvokeNativeFunction(component, function, parameters);
		}

