		// shootanim1 (12.11 02:55: "the client doesn't see the sharks'
		// animations"): the playing animation of the host's shark
		UAnimNodeSequence* FindShooterSequence(UAnimNode* node, int depth)
		{
			if (!node || depth > 5 || !IsUsableObjectFast(node))
				return nullptr;
			static UClass* const sequenceClass = UAnimNodeSequence::StaticClass();
			static UClass* const blendClass = UAnimNodeBlendBase::StaticClass();
			if (sequenceClass && node->IsA(sequenceClass))
				return reinterpret_cast<UAnimNodeSequence*>(node);
			if (!blendClass || !node->IsA(blendClass))
				return nullptr;
			auto* const blend = reinterpret_cast<UAnimNodeBlendBase*>(node);
			UAnimNodeSequence* first = nullptr;
			for (int32_t i = 0; i < blend->Children.size(); ++i)
			{
				UAnimNodeSequence* const found = FindShooterSequence(blend->Children.at(i).Anim, depth + 1);
				if (found && found->bPlaying && found->AnimSeqName.ToString() != "None")
					return found;
				if (found && !first)
					first = found;
			}
			return first;
		}
		UAnimNodeSequence* ShooterActorSequence(AActor* actor)
		{
			static UClass* const skelClass = ASkeletalMeshActor::StaticClass();
			if (!actor || !skelClass || !actor->IsA(skelClass))
				return nullptr;
			USkeletalMeshComponent* const mesh = reinterpret_cast<ASkeletalMeshActor*>(actor)->SkeletalMeshComponent;
			if (!mesh || !IsUsableObjectFast(mesh))
				return nullptr;
			return FindShooterSequence(mesh->Animations, 0);
		}
